window.QBANK = {"v":"2026-08-28","courses":["新型电力系统概述","电力系统基础（主网调度）","电力系统基础（发电技术）","电力系统基础（变电运行）","电力系统基础（配电运行）","电力系统基础（配网调度）","电力系统基础（变电检修·整体业务）","电力系统基础（变电检修·线圈类）","电力系统基础（变电检修·开关类）","电力系统基础（输电线路知识）","电力系统基础（电力电缆基础入门）","电力系统基础（电能计量）","电力系统基础（用电检查）","电力系统基础（客户服务）","电力系统基础（数字化与人工智能技术）","无线电能传输技术","招标采购法律法规及制度","舆情素养提升第一课","现代物流体系建设通识"],"q":[{"i":1,"c":0,"t":1,"s":"在电力系统的构成中，电能从生产到消费依次经过五大环节，正确的排列顺序是（　）。","a":"A","e":"考点：电力系统构成的五大环节。课件依据：「电力系统＝电能生产＋消费网络，五大环节为发电、输电、变电、配电、用电」，缺少任何一个环节，电力系统都将无法完成。","o":["发电—输电—变电—配电—用电","发电—变电—输电—配电—用电","发电—输电—配电—变电—用电","发电—配电—输电—变电—用电"]},{"i":2,"c":0,"t":1,"s":"传统电力系统的特征常被概括为“高、大、远”。下列各项中，不属于这一概括所包含内容的是（　）。","a":"D","e":"考点：传统电力系统“高大远”特征与新型系统拓扑的对比。课件依据：「01高——高电压、高参数、高集控；02大——大机组、大电厂、大电网；03远——远距离（特高压直流输电线路）」。分布式发电出现在用户侧是新型电网系统拓扑变化的体现。","o":["高电压、高参数、高集控","大机组、大电厂、大电网","远距离（特高压直流输电线路）","分布式电源大量接入用户侧"]},{"i":3,"c":0,"t":1,"s":"在我国承诺的“双碳”目标中，实现碳达峰与碳中和的目标年份分别是（　）。","a":"B","e":"考点：“双碳”目标时间节点。课件依据：「中国承诺（双碳）：2030年碳达峰，2060年碳中和，预计清洁能源装机比例达80-90%」。","o":["2030年和2050年","2030年和2060年","2035年和2050年","2040年和2060年"]},{"i":571,"c":0,"t":1,"s":"在智能电网的自愈性、互动性、鲁棒性、可负担性、多能源兼容性等特性中，居于核心地位的是（　）。","a":"D","e":"考点：智能电网特性的核心。笔记依据：「智能电网……特性：自愈性（核心）、互动性、鲁棒性、可负担性、多能源的兼容性」。","o":["互动性","鲁棒性","可负担性","自愈性"]},{"i":572,"c":0,"t":1,"s":"在新型电力系统中被称为“末梢神经元”的设备是（　）。","a":"A","e":"考点：智能电网成员的形象定位。笔记依据：「智能电网成员：空调负荷、电动汽车、智能电表（新型电力系统『末梢神经元』）、负荷调控」。","o":["智能电表","电动汽车充电桩","配电变压器","继电保护装置"]},{"i":680,"c":0,"t":1,"s":"截至2025年，我国抽水蓄能装机已达1.2亿千瓦，其中装机容量居全球之首、达360万千瓦的抽水蓄能电站是（　）。","a":"B","e":"考点：我国电源结构中水电与抽蓄的关键参数。课件载明：“抽蓄装机达1.2亿千瓦（丰宁电站全球最大360万千瓦）”。其余三座均为我国知名抽水蓄能电站但规模均非全球最大。","o":["惠州抽水蓄能电站","丰宁抽水蓄能电站","广州抽水蓄能电站","天荒坪抽水蓄能电站"]},{"i":684,"c":0,"t":1,"s":"关于我国首座深远海浮式风电场所在地及其单机容量，正确的组合是（　）。","a":"D","e":"考点：海上风电跃升的技术标杆。课件载明：“中国首座深远海浮式风电场（海南万宁）单机容量20MW”；广东阳江基地投运的单机16MW为常规海上风电机组的技术亮点。","o":["广东阳江，单机容量16MW","江苏如东，单机容量8MW","福建福清，单机容量10MW","海南万宁，单机容量20MW"]},{"i":685,"c":0,"t":1,"s":"按电气特性对负荷进行分类，某类负荷的典型设备为电动机、变压器，功率因数约0.6～0.8，运行时需要无功补偿，这类负荷是（　）。","a":"B","e":"考点：负荷按电气特性的三分法。课件载明感性负荷“典型设备：电动机、变压器”“功率因数0.6-0.8，需无功补偿”；阻性负荷功率因数接近1，容性负荷功率因数超前、易引发谐振。","o":["阻性负荷","感性负荷","容性负荷","冲击性负荷"]},{"i":691,"c":0,"t":1,"s":"关于我国电力责任演进的时间节点，下列说法正确的是（　）。","a":"A","e":"考点：电力责任的两大时间节点。课件原文：“（1）2012年，拐点，政策驱动；（2）2020年，电力企业对碳排放的控制起到主导作用。”两个节点的主导力量不可混淆。","o":["2012年是拐点，以政策驱动为主要特征","2012年起电力企业开始主导碳排放控制","2020年是政策驱动的拐点起点","2020年前碳排放控制一直由电力企业主导"]},{"i":692,"c":0,"t":1,"s":"课件对新型电力系统面临的挑战分方面阐述，其中“风光电源存在先天性缺陷、负荷与电源属性匹配难以趋同”属于（　）方面的挑战。","a":"A","e":"考点：发展挑战的分类归属。课件在“电力供应方面”指出：“（1）电源：风光电源先天性‘缺陷’；（2）负荷：负荷与电源的属性匹配难以趋同。”","o":["电力供应","系统安全","电力成本","体制机制"]},{"i":694,"c":0,"t":1,"s":"按课件预测，到2060年我国电力占终端用能的比重将达到约（　），全社会用电量可达约15万亿千瓦时。","a":"B","e":"考点：终端用能电气化的远景预测。课件原文：“电力占终端用能比重逐年提升，在2060年达到80%”“2060年，社会用电量可达15000TWH（15万亿）。”","o":["50%","80%","65%","95%"]},{"i":696,"c":0,"t":1,"s":"课件认为，（　）是实现新型电力系统不可或缺的基石，没有它就难以应对高比例新能源带来的复杂性、不确定性，也难以实现源网荷储深度协同。","a":"A","e":"考点：数字电网的战略定位。课件原文：“数字电网：是实现新型电力系统不可或缺的基石，没有强大的数字化赋能……就无法实现源网荷储的深度协同。”","o":["数字电网","特高压电网","配电网重构","虚拟电厂"]},{"i":698,"c":0,"t":1,"s":"智能电网的某一特性是指“体系结构在面对人为失误、人为攻击、自然灾害时具有更强的抵抗力”，该特性是（　）。","a":"D","e":"考点：智能电网五大特性的内涵区分。课件关于鲁棒性的表述为：“体系结构在面对人为失误、人为攻击、自然灾害具有更强的抵抗力”；自愈性是对问题快速预测、检测和响应的能力，且被列为智能电网的核心。","o":["互动性","自愈性","可负担性","鲁棒性"]},{"i":4,"c":0,"t":2,"s":"课件将电力系统的运行特点归纳为若干个“性”，下列属于其中的有（　）。","a":"ABDE","e":"考点：电力系统运行特点。课件依据：「同时性、整体性、快速性、连续性、随机性」，并强调电能不能大量储存、负荷变化与故障的发生是随机的。“间歇性”是对风光电源先天缺陷的描述，不属于电力系统运行特点。","o":["同时性","整体性","间歇性","连续性","随机性"]},{"i":5,"c":0,"t":2,"s":"课件在介绍新型电网时给出了系统拓扑变化及其主要特征，下列属于新型电力系统主要特征的有（　）。","a":"ACDE","e":"考点：新型电力系统主要特征。课件依据：「主要特征：可靠、高效、充足、灵活、洁净」。“集中”不属于上述特征，新型系统拓扑已变为发电—输电—配电—用户—分布式发电的多元形态。","o":["可靠","集中","高效","灵活","洁净"]},{"i":6,"c":0,"t":2,"s":"关于新型电力系统发展趋势中的能源互联网，下列说法正确的有（　）。","a":"ACD","e":"考点：能源互联网的发展趋势与优势。课件依据：「通过互联网技术将电力系统与其他能源系统（如天然气、热力等）深度融合」以及「提升新能源的消纳能力」「实现‘源荷网储’设备广泛链接，全面感知系统运行状态」，且明确其建设依托先进的特高压输电和智能电网技术，B项与之相悖。","o":["它能够提升新能源的消纳能力","它的建设可以完全脱离特高压输电和智能电网技术","它通过互联网技术将电力系统与天然气、热力等其他能源系统深度融合","它能够实现“源荷网储”设备的广泛链接，全面感知系统运行状态"]},{"i":7,"c":0,"t":2,"s":"课件列举了支撑新型电力系统发展的关键技术，下列属于其中的有（　）。","a":"ABC","e":"考点：新型电力系统三大关键技术。课件依据：「常见的储能方式，如电池储能、抽水蓄能、压缩空气储能等」「电力电子器件实现电能的高效变换和控制」「物联网、大数据、云计算、人工智能等技术在电力系统中的应用」。“电压调控技术”不在课件所列关键技术之中。","o":["储能技术","电力电子技术","信息技术与通信技术","电压调控技术"]},{"i":432,"c":0,"t":2,"s":"根据课程归纳，数字电网具备的三大能力是（　）。","a":"ABD","e":"考点：数字电网的三能力。依据：「数字电网三能力：实时、预测、自愈」，这正是数字电网支撑新型电力系统运行的关键所在。","o":["实时能力","预测能力","离线能力","自愈能力"]},{"i":547,"c":0,"t":2,"s":"下列属于新兴颠覆性负荷的有（　）","a":"ACD","e":"课件将电动汽车充电负荷、数据中心负荷、氢能制备负荷等列为新兴颠覆性负荷；空调负荷仍归入居民、商业负荷范畴，不属于新兴颠覆性负荷。","o":["电动汽车充电负荷","空调负荷","数据中心负荷","氢能制备负荷"]},{"i":586,"c":0,"t":2,"s":"按时间特性对电力系统负荷进行划分，下列属于其中类别的有（　）。","a":"ABC","e":"考点：负荷按时间特性的分类。笔记依据：「按时间特性：基荷（全天稳）、峰荷（早晚尖峰）、腰荷（日间平段）、谷荷（夜间低谷）」；“冲击负荷”不属于该分类。","o":["基荷（全天稳）","峰荷（早晚尖峰）","腰荷（日间平段）","冲击负荷"]},{"i":682,"c":0,"t":2,"s":"课件将2025年的电力系统电源划分为六大类并解析其特点，下列属于其中的有（　）。","a":"BCD","e":"考点：2025年电源的六大类划分。课件列举的六类为“传统基荷电源、核能电源、波动性可再生能源、可调节可再生能源、新兴颠覆性能源、储能与虚拟电源”，电网侧输变电设备不属于该分类。","o":["电网侧输变电设备","波动性可再生能源","储能与虚拟电源","新兴颠覆性能源"]},{"i":687,"c":0,"t":2,"s":"南方电网的服务区域覆盖下列哪些省区（　）。","a":"ABDE","e":"考点：南方电网的规模与覆盖。课件载明南方电网“覆盖广东、广西、云南、贵州、海南五省区及港澳”，福建省不在其供电范围内。","o":["广东","云南","福建","贵州","广西"]},{"i":699,"c":0,"t":2,"s":"课件列举了接入智能电网的新型负荷成员，下列属于其中的有（　）。","a":"ACD","e":"考点：智能电网的典型新成员。课件列出的新负荷成员为“01空调负荷 02电动汽车 03智能电表 04负荷调控”，燃煤发电机组不属于新负荷成员。","o":["空调负荷","燃煤发电机组","电动汽车","智能电表"]},{"i":700,"c":0,"t":2,"s":"课件提出电网新员工的成长“工具箱”，下列属于其中的有（　）。","a":"ABCD","e":"考点：新员工成长“工具箱”的四项内容。课件原文：“包括持续学习新能源、智能技术等新知识的能力；融合电力、信息、通信等多学科知识的跨学科思维；勇于探索新方法的创新意识；以及保障电力系统安全运行的责任担当。”","o":["持续学习新能源、智能技术等新知识的能力","融合电力、信息、通信等多学科知识的跨学科思维","勇于探索新方法的创新意识","保障电力系统安全运行的责任担当","固守单一专业、拒绝跨界协作的思维习惯"]},{"i":8,"c":0,"t":3,"s":"微电网可实现局部电力的自给自足，提高供电可靠性，同时与大电网相互配合，优化电力资源配置。","a":"对","e":"考点：分布式电源与微电网的发展趋势。课件依据：「微电网可实现局部电力的自给自足，提高供电可靠性，同时与大电网相互配合，优化电力资源配置」，可见微电网须与大电网配合而非孤立运行。"},{"i":9,"c":0,"t":3,"s":"按照课件观点，风光发电来自大自然、表面上成本很低，因此其实际供电成本也一定很低。","a":"错","e":"考点：新型电力系统在电力成本方面面临的挑战。课件依据：「表面上风光发电来自于大自然，成本‘很低』」「看不到的方面，比如替代率低，同样的发电量所需要的装机容量增加」。故实际供电成本并非一定很低。"},{"i":449,"c":0,"t":3,"s":"新能源发电的高峰通常出现在午间，而全社会用电高峰大多出现在晚间，二者存在时间上的错位。","a":"对","e":"考点：新型电力系统的供需时空特征。依据：「新能源发电高峰在午间，用电高峰在晚间」，这一错位是系统灵活性建设面临的重点问题。"},{"i":450,"c":0,"t":3,"s":"智能电网的主要特点包括自愈、互动、鲁棒、可负担和单一能源供电。","a":"错","e":"考点：智能电网的五大特点。依据：「智能电网五特点：自愈、互动、鲁棒、可负担、多能源兼容」，最后一项是多能源兼容而非单一能源供电。"},{"i":617,"c":0,"t":3,"s":"电力系统的核心目标是实现电能的安全供应、经济供应和清洁供应。","a":"对","e":"考点：电力系统的核心目标。笔记依据：「电力系统核心目标：电能安全、电能经济、电能清洁供应」。"},{"i":618,"c":0,"t":3,"s":"数字电网以数据为驱动，借助物联网、AI、5G、云计算等技术实现电力系统全环节数字化、智能化和协同化，具备实时性、预测能力和自愈能力。","a":"对","e":"考点：数字电网的定义与能力。笔记依据：「数字电网（数字化）：以数据为驱动，通过物联网（IoT）、AI、5G、云计算等技术……具备实时性、预测能力和自愈能力」。"},{"i":619,"c":0,"t":3,"s":"随着新型电力系统建设推进，电网正逐步向“主干电网＋中小型电网及微型电网”的柔性互联形态发展。","a":"对","e":"考点：新型电网的发展形态。笔记依据：「电网逐步向『主干电网+中小型电网及微型电网』柔性互联形态发展」。"},{"i":620,"c":0,"t":3,"s":"截至2025年，我国风电和太阳能发电装机占比已合计超过40%；煤电装机占比37.5%，仍是重要的调节性电源。","a":"对","e":"考点：我国2025年电源结构关键参数。笔记依据：「我国电源总装机约32.5亿千瓦；非化石能源占比53.2%；风光占比超40%；煤电占比37.5%，仍为重要调节电源」。"},{"i":679,"c":0,"t":3,"s":"关于电力负荷的“峰谷”特性，系统为满足负荷波动而预留的一定裕度，将带来一定的浪费。","a":"对","e":"考点：电力负荷的“峰谷”特性。课件原文：“满足实际负荷的供电特性：系统需要一定的裕度，来满足负荷的波动，但这将造成一定的浪费。”这反映了电能实时平衡要求下的固有代价。"},{"i":681,"c":0,"t":3,"s":"石岛湾电站是我国第四代高温气冷堆投入商业运行的核电站。","a":"对","e":"考点：先进核电技术进展。课件在2025年电源结构表核电一栏注明：“第四代高温气冷堆商运（石岛湾电站）”。"},{"i":683,"c":0,"t":3,"s":"据课件概括，2025年电力系统电源呈现“清洁化、智能化、去中心化、价值多元化”的“四化”特征。","a":"对","e":"考点：2025年电源的“四化”特征。课件原文：“2025年电力系统电源呈现‘清洁化、智能化、去中心化、价值多元化’‘四化’特征，以下分六大类解析其特点与最新进展。”"},{"i":686,"c":0,"t":3,"s":"白炽灯、电加热器属于典型的容性负荷，运行时功率因数超前，易引发电网谐振。","a":"错","e":"考点：阻性负荷与容性负荷的区分。课件载明阻性负荷“典型设备：电加热器、白炽灯”“功率因数接近1，但能效低”；功率因数超前、易引发谐振的是逆变器、换流站等构成的容性负荷。"},{"i":688,"c":0,"t":3,"s":"南方电网覆盖广东、广西、云南、贵州、海南五省区及港澳，供电面积约100万平方公里，服务人口超过2.7亿。","a":"对","e":"考点：南方电网的规模与覆盖。课件原文：“覆盖广东、广西、云南、贵州、海南五省区及港澳，供电面积100万平方公里，服务人口2.72亿。”"},{"i":689,"c":0,"t":3,"s":"从国际压力看，我国碳排放总量居全球第一，但人均碳排放约为美国的50%。","a":"对","e":"考点：新型电力系统发展背景中的国际压力。课件原文：“国际压力：（1）碳排放量全球第一；（2）人均是美国50%。”"},{"i":690,"c":0,"t":3,"s":"我国用电量保持稳定增长，同时电源构成正在转变为以非化石能源装机为主。","a":"对","e":"考点：源、荷基本情况。课件原文：“（1）用电量稳定增长；（2）电源构成正在以非化石资源装机为主。”这是新型电力系统发展的重要背景。"},{"i":693,"c":0,"t":3,"s":"按课件对未来40年能源消费趋势的预测，我国对煤炭的依赖将逐年上升，并在2060年后达到峰值。","a":"错","e":"考点：能源消费的转型方向。课件原文恰好相反：“未来40年的能源消费趋势：（1）对煤炭的依赖逐年下降，2060年后更加平滑；（2）‘黑色’能源占比随着2060年的到来比例越发降低。”"},{"i":695,"c":0,"t":3,"s":"按课件对未来电源结构的预测，2060年火电将取代清洁能源成为主体电源，风电光伏仅承担辅助调频功能。","a":"错","e":"考点：2060年电源结构预测。课件原文与之相反：“2060年电源侧将发展为以清洁能源为主（光、风、水电、核电），以火电为辅助调频功能的电力生产结构。”"},{"i":697,"c":0,"t":3,"s":"数字电网下负荷侧的发展方向是电力需求稳步萎缩，电能占终端能源消费的比重大幅下降。","a":"错","e":"考点：数字电网的负荷侧需求。课件原文：“电力需求稳步增长，电能占终端能源消费比重大幅提升。”工业、建筑、交通领域均是重点，交通领域提升主要来自电动汽车。"},{"i":10,"c":1,"t":1,"s":"根据南方电网调度管辖范围的划分，500kV主电网、省间联络线和主力电厂应由哪一级调度机构管辖？","a":"C","e":"考查调度分层分级管辖范围。课件依据：「500kV主电网、省间联络线、主力电厂、港澳400kV电网等」属南网总调调度管辖。","o":["各省中调","各区地调","南网总调","各区配调"]},{"i":11,"c":1,"t":1,"s":"南方电网频率标准为50Hz，联网省区正常运行时频率偏差不得超过多少？","a":"D","e":"考查电网频率运行管理标准。课件依据：「正常运行频率偏差不得超过±0.2Hz（联网省区）」。","o":["±0.1Hz","±0.3Hz","±0.5Hz","±0.2Hz"]},{"i":12,"c":1,"t":1,"s":"变压器停电检修操作中，依次断开变压器各侧开关的正确顺序是什么？","a":"B","e":"考查电网运行操作流程。课件依据：「按照由低至高的电压等级顺序依次断开变压器各侧开关」，随后同样由低至高拉开各侧开关两侧刀闸。","o":["由高至低按电压等级顺序逐台断开","由低至高按电压等级顺序依次断开","高压侧与低压侧同时断开","无顺序要求，按现场方便程度断开"]},{"i":13,"c":1,"t":1,"s":"电网发生功率扰动时，能迅速动作（秒级）以限制频率偏差、但属于有差调节的是哪一层级的频率调节？","a":"D","e":"考查频率调控体系三个层级。课件依据：「当发生功率扰动时，一次调频迅速动作（秒级）限制频率偏差在指定范围之内（有差调节）」，二次调频随后无差恢复至额定值。","o":["三次调节","二次调频","电压自动控制（AVC）","一次调频"]},{"i":14,"c":1,"t":1,"s":"关于发布调度指令的规范，下列说法正确的是什么？","a":"A","e":"考查调度指令发布规范。发受令双方应全程录音记录、互报单位姓名、使用（名称）+（编号）双重命名并严格执行复诵制度，严禁无监护人操作或联系业务。","o":["发受令双方应全程录音和记录，严格执行复诵制度并使用双重命名","为提高效率，情况紧张时可以省去复诵环节","允许无监护人单独进行操作或联系业务","调度术语可根据个人习惯随意简化"]},{"i":15,"c":1,"t":1,"s":"电网事故处理应遵循的基本原则及正确顺序是什么？","a":"C","e":"考查事故处理基本原则及顺序。即迅速限制事故发展、消除事故根源，用一切可能的方法保持电网稳定运行，再调整系统运行方式使其恢复正常。","o":["稳定局面、恢复自愈、快速控制","恢复自愈、快速控制、稳定局面","快速控制、稳定局面、恢复自愈","快速控制、恢复自愈、稳定局面"]},{"i":416,"c":1,"t":1,"s":"电网解列为孤网运行后，当频率低于（　）时，应对低频减载装置的动作情况进行检查。","a":"C","e":"考点：孤网低频运行的检查门槛。依据：「孤网低于49.0Hz要检查低频减载」。","o":["47.5Hz","48.0Hz","49.0Hz","49.8Hz"]},{"i":565,"c":1,"t":1,"s":"依靠自动控制系统（AGC）设定发电机组功率基准值、改变原动机功率以恢复系统频率，这种调节属于（　），且是无差调节。","a":"C","e":"考点：二次调频的实现方式与特征。笔记依据：「二次调频：通过自动控制系统（AGC）设定发电机组功率的基准值……恢复系统频率的目的，为无差调节」。","o":["一次调频","三次调频","二次调频","联合调频"]},{"i":566,"c":1,"t":1,"s":"系统发生潮流越限时，潮流调控要求在（　）内将系统断面控制到限值以内。","a":"D","e":"考点：潮流调控的时限要求。笔记依据：「系统潮流调控。15分钟内将系统断面控制到限值以内：灵敏调节、转移负荷、片区转移、错峰限电」。","o":["5分钟","10分钟","30分钟","15分钟"]},{"i":567,"c":1,"t":1,"s":"系统频率异常时，造成频率异常的责任网应在（　）内完成限制负荷措施，使电网频率恢复到正常范围之内。","a":"B","e":"考点：系统频率异常处置时限。笔记依据：「造成频率异常的责任网出力，10分钟内完成限制负荷措施恢复电网频率在正常范围之内；非责任网支援时间为30分钟」。","o":["5分钟","10分钟","20分钟","30分钟"]},{"i":717,"c":1,"t":1,"s":"依据课件对南方电网构成的界定，下列各项中属于保障电网运行所需的二次设备的是（　）。","a":"C","e":"考点：南方电网“一次设备＋二次设备”的统一整体构成。课件定义中列举的二次设备包括“继电保护、安全自动装置、电力通信、调度自动化、电力市场技术支持系统等”，变压器、线路、断路器均属一次设备。","o":["500kV主变压器","输电线路","电力市场技术支持系统","断路器"]},{"i":719,"c":1,"t":1,"s":"系统频率异常由南网总调统一指挥处置时，要求非责任网调出备用容量或减少发电机出力进行支援，其支援时间为（　）；若确需继续支援，责任方应提出申请，由南网总调协调修改送受电计划。","a":"D","e":"考点：系统频率异常处置中各主体的职责与时限。课件原文：“非责任网支援时间为30分钟，超过25分钟后，若有需要，责任方应提出申请，南网总调协调修改送受电计划”；另有造成频率异常的责任网应在10分钟内完成限制负荷措施的要求。","o":["10分钟","25分钟","60分钟","30分钟"]},{"i":720,"c":1,"t":1,"s":"南方电网调频模式分为三个层级，其中“三次调节”的主要内容是（　）。","a":"B","e":"考点：三层级频率调控体系的分工。课件原文：“三次调节考虑机组经济性、输电断面安全性进行机组功率重新分配”；秒级有差调节是一次调频的特征，恢复至额定值的无差调节是二次调频的特征。","o":["秒级快速动作限制频率偏差，属于有差调节","考虑机组经济性、输电断面安全性，重新分配机组功率","在一二次调频后使频率恢复至额定值的无差调节","通过低频减载装置自动切除部分负荷"]},{"i":721,"c":1,"t":1,"s":"按照南方电网调度管辖范围的划分，220kV终端变电站及直馈线、110kV电网和35kV电网应由（　）调度管辖。","a":"C","e":"考点：四级调度机构管辖范围的划分。课件载明地调管辖“220kV终端变电站及直馈线、110kV电网和35kV电网”；配调管辖10kV（20kV）中压配电网，中调管辖500kV地方电网、220kV主网电网等重要对象。","o":["南网总调","省级中调","地调","配调"]},{"i":16,"c":1,"t":2,"s":"依据课件定义，电力调度是对所辖电网运行进行的下列哪些工作？","a":"ABCD","e":"课件依据：「指电力调度机构对所辖电网运行进行的组织、指挥、指导和协调」，并包括调度、运行方式、继电保护、电力通信、调度自动化等专业管理工作。","o":["组织","指挥","指导","协调"]},{"i":17,"c":1,"t":2,"s":"调度机构的生产任务是对所辖电网运行进行组织、指挥、指导和协调，其中包含的专业管理工作有哪些？","a":"ABD","e":"课件依据：生产任务包括「调度运行、运行方式、继电保护、电力通信、调度自动化、网络安全等专业管理工作」，市场交易结算不属于该范畴。","o":["调度运行","继电保护","市场交易结算","电力通信与调度自动化"]},{"i":18,"c":1,"t":2,"s":"按照南方电网调度管辖范围的划分，下列哪些设备和电网属于省级中调的调度管辖范围？","a":"BCD","e":"课件依据：中调管辖「500kV地方电网、220kV主网电网、重要直调电厂和用户」；10kV（20kV）中压配电网属配调管辖。","o":["10kV（20kV）中压配电网","500kV地方电网","220kV主网电网","重要直调电厂和用户"]},{"i":19,"c":1,"t":2,"s":"下列哪些属于电网无功电压的控制手段？","a":"ACD","e":"考查无功电压的三类控制手段：增减无功出力（发电机、电容器、电抗器、SVC等）、改变无功功率分布（如调主变分接头）、改变负荷供电方式。调整售电价格不是电网调压手段。","o":["调整发电机无功出力","调整售电价格","投切电容器、电抗器、SVC等无功补偿设备","调整主变分接头位置"]},{"i":20,"c":1,"t":2,"s":"区域电网因故障被动进入孤网运行时，下列关于频率控制的措施正确的有哪些？","a":"ABCE","e":"以上均为孤网频率控制措施，唯独D错误。课件依据：「拉停的线路、限制的负荷和低频切除的负荷，未经值班调度员同意，不得自行恢复」。","o":["指定调频厂负责孤立电网的调频","频率低于49.0Hz时，立即检查各轮低频减载装置动作情况，装置应动而未切除的线路立即手动拉开","按“有序合理、逐步恢复”的原则恢复负荷，优先恢复重要负荷","被拉停的线路、限制的负荷和低频切除的负荷，可在处置告一段落后由厂站自行恢复","孤网频率恢复正常后，值班调度员应视条件尽快将孤立电网重新并入主网运行"]},{"i":21,"c":1,"t":2,"s":"为防止电网事故扩大，下列哪些情形下厂站值班人员可以不待调度指令自行处理？","a":"ABDE","e":"课件规定了四种可不待调令自行处理的情形：对人员生命和设备安全有严重威胁的设备停电、隔离已损坏设备、恢复站厂用电源、现场规程中有明确规定者。将正常运行的机组解列不在其列。","o":["将直接对人员生命和设备安全有严重威胁的设备停电","将已损坏的设备隔离","将运行正常的机组全部迅速解列","恢复站、厂用电源","现场规程中有明确规定的情形"]},{"i":22,"c":1,"t":2,"s":"处理电网事故时，对于可能导致破坏电力系统稳定和电网大面积停电的情况，调度员应采取的必要措施包括哪些？","a":"ABC","e":"课件依据：「对于可能导致破坏电力系统稳定和电网大面积停电的情况，应采取拉限负荷、解列电网、解列发电机组等必要措施予以应对」。","o":["拉限负荷","解列电网","解列发电机组","完全依赖机组一次调频自动纠正，调度不再采取其他措施"]},{"i":718,"c":1,"t":2,"s":"依据课件，调度机构开展调度工作应做到的要求包括（　）。","a":"ABC","e":"考点：调度机构主要任务的三方面要求。课件列出贯彻法律、法规，“三公”调度与节能、环保三个方面，并要求“协调流域水库优化调度，充分合理利用一次能源……充分发挥电力系统设备能力”，售电利润并非调度的目标导向。","o":["贯彻国家有关法律、法规，保障电网安全、优质、经济、环保运行","按照规程规定实施“公开、公平、公正”调度，维护各方的合法权益","遵循节能、环保原则，优先利用可再生能源和清洁能源发电","把提高公司售电利润作为调度工作的首要目标"]},{"i":23,"c":1,"t":3,"s":"独立运行电网装机容量小于3000MW时，频率运行偏差正常不得超过±0.2Hz。","a":"错","e":"±0.2Hz是联网省区的正常频率偏差限值。课件依据：「独立运行电网装机容量小于3000MW时，频率运行偏差正常不得超过±0.5Hz」。"},{"i":24,"c":1,"t":3,"s":"系统无功电压按调度管辖范围实行分级管理，并按照“分层分区，就地平衡”的原则进行调整和控制。","a":"对","e":"考查无功电压控制基本原则。课件依据：「系统无功电压按照‘分层分区，就地平衡’的原则进行调整和控制，兼顾系统无功优化」。"},{"i":25,"c":1,"t":3,"s":"电网运行操作应根据调度管辖范围的划分，实行统一调度、分级管理。","a":"对","e":"课件依据：「电网运行操作应根据调度管辖范围的划分，实行统一调度，分级管理」；紧急情况下上级调度可对下级调度管辖范围内的设备进行指挥和操作。"},{"i":612,"c":1,"t":3,"s":"电网电压控制应兼顾站内各级电压等级，并优先满足低电压等级的调压要求。","a":"错","e":"考点：电压控制基本原则。笔记依据：「电压控制基本原则：兼顾各级，优先高级：兼顾站内各电压等级，优先满足高电压等级要求」。"},{"i":613,"c":1,"t":3,"s":"南方电网公司成立于2002年12月29日。","a":"对","e":"考点：南方电网公司的成立时间。笔记依据：「南网成立于2002年12月29日」。"},{"i":26,"c":2,"t":1,"s":"在电力系统的发电、输电、变电、配电、用电各环节中，利用发电动力装置将其他形式能量转换为电能的环节是？","a":"A","e":"考点：电力系统五大环节的功能定位。课件依据：「发电——利用发电动力装置将其他形式能转换为电能的过程」，其能量变化为其他形式能量→电能。","o":["发电","输电","变电","配电"]},{"i":27,"c":2,"t":1,"s":"火力发电厂燃烧煤、油、天然气等燃料加热水生成高温高压蒸汽，其中受蒸汽冲击而高速旋转、并进一步拖动发电机旋转的设备是？","a":"B","e":"考点：火电生产流程与能量转换链条。课件依据：「蒸汽冲击汽轮机高速旋转，汽轮机拖动发电机旋转，最终将机械能转变成电能」。","o":["锅炉","汽轮机","发电机","冷凝器"]},{"i":28,"c":2,"t":1,"s":"按厂房布置位置和引水方式分类，某水电站的厂房与大坝布置在同一直线上，厂房成为坝的一部分、起挡水作用，适用于水头较低的情况，如葛洲坝。这类水电站是？","a":"A","e":"考点：水电站按厂房布置与引水方式的分类。课件依据：「河床式水电站：葛洲坝——厂房与大坝布置在同一直线上，成为坝的一部分，也起挡水作用」；坝后式如三峡，引水式如锦屏二级。","o":["河床式","坝后式","引水式","混合式"]},{"i":29,"c":2,"t":1,"s":"根据转换水流能量方式的不同，水轮机分为哪两大类？","a":"D","e":"考点：水轮机的分类体系。课件依据：「根据转换水流能量方式的不同，水轮机分为反击式水轮机和冲击式水轮机两大类」；混流式、轴流式属反击式，切击式、斜击式属冲击式。","o":["混流式和轴流式","定桨式和转桨式","切击式和斜击式","反击式和冲击式"]},{"i":30,"c":2,"t":1,"s":"轻核在超高温、高压条件下结合成更稳定的重核而发生核聚变。课件指出，核聚变单位质量释放的能量约为核裂变的多少倍？","a":"B","e":"考点：核聚变的能量特征。课件依据：「核聚变单位质量释放能量更高（约3~4倍裂变）」，且可控核聚变反应堆技术仍在探索中。","o":["1~2倍","3~4倍","10倍左右","20倍以上"]},{"i":31,"c":2,"t":1,"s":"单晶硅、多晶硅、非晶态硅三种太阳能电池中，变换效率最高的是？","a":"C","e":"考点：太阳能电池技术效率对比。课件依据：「太阳能电池技术主要有单晶硅、多晶硅、非晶态硅3种，转化效率普遍在15%~25%，其中单晶硅太阳能电池变换效率最高」。","o":["多晶硅","非晶态硅","单晶硅","三种电池效率相同"]},{"i":32,"c":2,"t":1,"s":"风力发电的能量转化效率存在理论上限，该理论极限值约为多少？","a":"C","e":"考点：风能利用效率的理论极限（贝茨极限）。课件依据：「风电的能量转化效率理论极限59.3%，实际风机效率通常35%~50%」。","o":["39.3%","49.3%","59.3%","69.3%"]},{"i":33,"c":2,"t":1,"s":"下列潮汐电站与其地位的对应关系，正确的是？","a":"C","e":"考点：典型潮汐电站的地位。课件依据：法国朗斯1966年投运为「全球首个大型潮汐电站」，韩国始华湖2011年投运「目前全球最大」，中国江厦潮汐试验电站1980年投运、「中国最大」。","o":["法国朗斯潮汐电站——目前全球最大","韩国始华湖潮汐电站——全球首个大型潮汐电站","中国江厦潮汐试验电站——中国最大的潮汐电站","中国江厦潮汐试验电站——全球首个投运的大型潮汐电站"]},{"i":34,"c":2,"t":1,"s":"目前技术最成熟、应用最广泛、在储能领域占据主导地位的大规模储能技术是？","a":"D","e":"考点：抽水蓄能的技术地位。课件依据：「抽水蓄能是目前技术最成熟、应用最广泛的大规模储能技术，在储能领域占据主导地位」，其综合效率约70%~80%。","o":["锂离子电池储能","压缩空气储能","飞轮储能","抽水蓄能"]},{"i":413,"c":2,"t":1,"s":"与光伏发电将太阳能直接转换为电能不同，太阳能光热发电的发电路径是（　）。","a":"A","e":"考点：光热发电的能量转换路径。依据：「光热＝定日镜聚光→热介质→蒸汽→汽轮机」，先将太阳能转为热能，再经机械能转换为电能。","o":["定日镜聚光加热介质→产生蒸汽→驱动汽轮机发电","借助半导体PN结直接输出电流","利用风能带动压缩机压缩空气后发电","通过电解化学反应直接释放电能"]},{"i":414,"c":2,"t":1,"s":"大型水力发电的能量转换效率大约是（　）。","a":"D","e":"考点：水力发电的能量转换效率。依据：「大型水电效率80%～90%」，明显高于火电机组的发电效率区间。","o":["30%～40%","50%～60%","70%～75%","80%～90%"]},{"i":415,"c":2,"t":1,"s":"抽水蓄能机组按水泵工况启动时，用于拖动机组升速至并网的重要设备是（　）。","a":"B","e":"考点：抽蓄机组水泵工况的启动设备。依据：「SFC＝泵工况启动、拖动机组至并网的重要设备」。","o":["励磁变压器","静止变频器（SFC）","站用备用变压器","柴油发电机组"]},{"i":469,"c":2,"t":1,"s":"关于抽水蓄能电站主进水阀的选型，下列说法正确的是（　）。","a":"C","e":"主进水阀选型的总体规律是“高水头用球阀、低水头用蝶阀”，故球阀适用于高水头大容量场景，蝶阀多用于中小型或低水头电站，其余三项均颠倒或混淆了两者的分工。","o":["高水头大容量电站普遍采用蝶阀","低水头电站普遍采用球阀","球阀适用于高水头、大容量场景","蝶阀与球阀的适用场景完全相同"]},{"i":472,"c":2,"t":1,"s":"下列属于核裂变燃料的是（　）。","a":"D","e":"铀-235是目前核电站使用的核裂变燃料；氘和氚是核聚变的燃料，氦-4则是聚变生成的产物。","o":["氘","氚","氦-4","铀-235"]},{"i":477,"c":2,"t":1,"s":"大型水电站的能量转换效率大约为（　）。","a":"A","e":"大型水电站的能量转换效率约为80%～90%，还高于抽水蓄能电站70%～80%的综合效率。","o":["80%～90%","60%～70%","70%～80%","90%～98%"]},{"i":482,"c":2,"t":1,"s":"中国第一座自主设计、建造和运营的核电站是（　）。","a":"B","e":"秦山核电站是中国第一座自主设计、建造和运营的核电站；大亚湾核电站是中国第一座大型商用核电站，两个“第一”不可混淆。","o":["大亚湾核电站","秦山核电站","田湾核电站","岭澳核电站"]},{"i":573,"c":2,"t":1,"s":"按各类发电方式的效率对比，效率最高、可达80%～90%的是（　）。","a":"A","e":"考点：各类发电效率对比排序。笔记依据：「大型水电（80～90%，最高）＞压缩空气储能（40～70%）＞燃煤火电（30～48%）＞燃气（30～40%）＞核电（30～35%）＞光伏（15～25%）」。","o":["大型水电","压缩空气储能发电","燃煤火电","核能发电"]},{"i":574,"c":2,"t":1,"s":"我国首座大型商用核电站是（　）。","a":"A","e":"考点：我国核电发展的标志性工程。笔记依据：「中国首座大型商用核电站：大亚湾核电站」。","o":["大亚湾核电站","秦山核电站","岭澳核电站","田湾核电站"]},{"i":575,"c":2,"t":1,"s":"光热发电中，通过大规模阵列镜面收集太阳热能、借助储热可实现24小时发电，典型代表为敦煌100MW电站的形式是（　）。","a":"B","e":"考点：光热发电的技术特点。笔记依据：「光热发电……熔盐塔式可24小时发电；光电转换效率约15%-20%（敦煌100MW熔盐塔式光热电站）」。","o":["槽式光热发电","熔盐塔式光热发电","碟式光热发电","线性菲涅尔式光热发电"]},{"i":701,"c":2,"t":1,"s":"根据国家能源局2024年全国电力工业统计数据，我国太阳能发电装机容量占全国发电总装机的比重约为（　）。","a":"C","e":"考点：2024年全国装机结构。课件表格载明太阳能装机88666万千瓦、占比26%、同比增长45.2%；同期风电占比16%、水电13%、火电43%、核电2%，火电仍居首位。","o":["8%","16%","26%","43%"]},{"i":702,"c":2,"t":1,"s":"根据国家能源局2025年全国电力工业统计数据，装机容量占比仅次于火电、跃居第二位的电源类型是（　）。","a":"A","e":"考点：2025年装机结构的重大变化。课件表格显示太阳能装机120173万千瓦、占比30.9%，超过风电的16.4%，仅次于火电的39.6%；当年全国总装机同比增长16.1%。","o":["太阳能","风电","水电","核电"]},{"i":705,"c":2,"t":1,"s":"核反应堆中通过吸收多余中子来调节裂变速率、确保反应稳定持续的部件叫控制棒，按课件其通常由（　）制成。","a":"D","e":"考点：核裂变反应的可控手段。课件原文：“通过控制棒（如镉或硼制成）吸收多余中子，调节裂变速率，确保反应稳定持续。”","o":["石墨或铍","铜或铝","铅或铋","镉或硼"]},{"i":707,"c":2,"t":1,"s":"“华龙一号”全球首堆示范工程所在的核电站是（　）。","a":"D","e":"考点：我国代表性核电站的定位区分。课件载明福清核电站5、6号机组为“华龙一号全球首堆示范工程”；另注意阳江核电站是首个“一次核准6台机组”的电站，不可混淆。","o":["秦山核电站","大亚湾核电站","阳江核电站","福清核电站"]},{"i":708,"c":2,"t":1,"s":"规划总装机2000万千瓦、被称作“陆上三峡”、国内首个风电装机突破1000万千瓦的风电基地是（　）。","a":"B","e":"考点：典型风电场的地位。课件载明：“甘肃酒泉千万千瓦风电基地规划总装机2000万kW，21年国内首个风电装机突破1000万kW，‘陆上三峡’”；江苏如东集群配套建设的是亚洲首个海上柔性直流送出工程。","o":["江苏如东海上风电集群","甘肃酒泉千万千瓦风电基地","新疆哈密风电基地","内蒙古乌兰察布风电基地"]},{"i":35,"c":2,"t":2,"s":"按能源类型划分发电方式时，下列属于新能源发电方式的有？","a":"ABE","e":"考点：发电厂的能源类型分类。课件依据：新能源发电包括「太阳能发电、风能发电、潮汐能发电、生物质能发电、地热能发电」；火力、水力、核能与新能源发电并列分类。","o":["太阳能发电","潮汐能发电","水力发电","核能发电","生物质能发电"]},{"i":36,"c":2,"t":2,"s":"关于火力发电，下列说法正确的有？","a":"ABD","e":"考点：火电原理与效率参数。课件依据：「燃煤电厂30~48%；燃油电厂35~40%；燃气电厂30~40%，50~63%」，故C错误；超超临界的外高桥三厂为「全球首个实际运行供电煤耗<270g/kWh的电厂」。","o":["燃烧煤、油、天然气等燃料，加热水生成高温高压蒸汽","燃煤电厂的能量转换效率约为30%~48%","燃油电厂的能量转换效率一般在70%~85%","外高桥第三发电厂是全球首个实际运行供电煤耗低于270克/千瓦时的电厂"]},{"i":37,"c":2,"t":2,"s":"水电站按厂房布置位置和引水方式分类。下列水电站与其类型的对应关系，正确的有？","a":"ABC","e":"考点：三类水电站的代表工程。课件依据：「河床式水电站：葛洲坝」「坝后式水电站：三峡……适用于中高水头」「引水式水电站：锦屏二级……适合高水头、小流量或地形复杂的河段」。","o":["葛洲坝——河床式","三峡——坝后式","锦屏二级——引水式","三峡——引水式"]},{"i":38,"c":2,"t":2,"s":"下列水轮机的具体型式中，属于反击式水轮机的有？","a":"ABD","e":"考点：水轮机两大类下的细分型式。课件依据：反击式水轮机包括混流式、轴流式（定桨、转桨）、斜流式、贯流式等；「切击式（QJ）」属于冲击式水轮机。","o":["混流式（HL）","轴流转桨式（ZZ）","切击式（QJ）","贯流式（GL）"]},{"i":39,"c":2,"t":2,"s":"关于核能发电，下列说法正确的有？","a":"ABDE","e":"考点：核裂变与核聚变要点及核电效率。课件依据：「核聚变单位质量释放能量更高（约3~4倍裂变）」故C错误；「核电站效率：30~35%」。","o":["当前核电站主要通过核裂变方式发电","核裂变的核燃料主要是铀-235或钚-239","核聚变单位质量释放的能量仅为核裂变的十分之一","控制棒可以用镉或硼制成，用于吸收多余中子、调节裂变速率","核电站的能量转换效率约为30%~35%"]},{"i":40,"c":2,"t":2,"s":"关于风力发电，下列说法正确的有？","a":"ABD","e":"考点：风电原理、分类与效率。课件依据：「风电的能量转化效率理论极限59.3%，实际风机效率通常35%~50%」，故C错误。","o":["风力发电是把风的动能转为电能","风电场主要分为陆上风电场和海上风电场两种","实际风机的能量转化效率通常达到90%以上","甘肃酒泉千万千瓦风电基地被誉为“陆上三峡”"]},{"i":41,"c":2,"t":2,"s":"关于潮汐能发电，下列说法正确的有？","a":"ABC","e":"考点：潮汐发电原理、类型与代表电站。课件依据：目前全球最大的是韩国始华湖潮汐电站（254MW），江厦试验电站（4.1MW）为「中国最大」。","o":["潮汐发电与普通水力发电原理类似","涨潮时将海水储存在水库内，以势能的形式保存","潮汐电站的类型包括单库单向电站、单库双向电站和双库双向电站","目前全球装机容量最大的潮汐电站是中国江厦潮汐试验电站"]},{"i":42,"c":2,"t":2,"s":"关于生物质能发电和地热能发电，下列说法正确的有？","a":"ABC","e":"考点：生物质发电的特点与地热资源的分类利用。课件依据：地热能五类资源中，「目前开发利用得较多的是蒸汽型及热水型两类资源」，故D错误。","o":["生物质能发电主要利用农业、林业和工业废弃物甚至城市垃圾为原料","生物质能发电可以作为小水电、风电、太阳能发电等间歇性发电的补充能源","地热能发电的基本原理与火力发电类似，是将地下热能转变为机械能再转变为电能","地热能目前开发利用较多的资源类型是干热岩型和岩浆型"]},{"i":43,"c":2,"t":2,"s":"关于抽水蓄能电站，下列说法正确的有？","a":"ABC","e":"考点：抽水蓄能的构成、效率与运行方式。课件依据：「抽水蓄能是目前技术最成熟、应用最广泛的大规模储能技术」；低谷抽水储能、高峰放水发电才体现其削峰填谷作用。","o":["以水为能量载体，通过抽水和放水过程实现能量的存储和利用","电站主要由上水库、输水系统、厂房和下水库等组成","综合效率约70%~80%","是目前技术尚不成熟、应用较少的储能技术","宜在电网负荷高峰时段大量抽水耗电"]},{"i":44,"c":2,"t":2,"s":"以设备检修规模和停用时间为原则，抽水蓄能电站设备的检修分为A、B、C、D四个等级。关于各级检修，下列说法正确的有？","a":"ABC","e":"考点：检修等级的划分与含义。课件依据：「D级检修指设备总体运行状况良好，对主要设备及其附属系统进行的消缺性维修」，并非全面解体、更换核心部件。","o":["A级检修指对设备进行全面的解体检查和修理，以保持、恢复或提高设备性能","B级检修指对设备进行部分的解体检查和修理","C级检修可根据设备的磨损、老化规律，有重点地对设备进行检查、评估、修理、清扫","D级检修指对设备进行全面解体并整体更换转子等核心部件"]},{"i":434,"c":2,"t":2,"s":"关于抽水蓄能电站在电力系统中发挥的作用，下列属于其五大作用的有（　）。","a":"ACD","e":"考点：抽水蓄能电站的五大作用。依据：「抽蓄五大作用＝削峰填谷、调频、调压、事故备用、黑启动」，抽蓄并非承担基荷的常规电源。","o":["削峰填谷","连续满发承担基荷","事故备用","调频调压","抬高电网正常运行频率上限"]},{"i":464,"c":2,"t":2,"s":"按照能量存储机理，储能技术可分为物理储能、化学储能和电磁储能等类型。下列属于物理储能的有（　）。","a":"ABDE","e":"依据课件分类表，抽水蓄能、飞轮储能、压缩空气储能、熔盐储能、固态重力储能等属于物理储能；锂离子电池属于化学储能，超级电容器、超导储能属于电磁储能。","o":["抽水蓄能","飞轮储能","锂离子电池","熔盐储能","固态重力储能"]},{"i":587,"c":2,"t":2,"s":"下列储能技术路线中，属于化学储能的有（　）。","a":"ACD","e":"考点：三大储能路线的划分。笔记依据：「化学储能（锂离子电池、铅蓄电池、液流电池、钠离子电池、氢燃料电池）」；抽水蓄能、飞轮储能属物理储能。另注意钠离子电池也属化学储能。","o":["锂离子电池","抽水蓄能","液流电池","氢燃料电池","飞轮储能"]},{"i":45,"c":2,"t":3,"s":"可控核聚变已经是当前核电站的主要发电方式。","a":"错","e":"考点：核裂变与核聚变的现状区别。课件依据：「可控核聚变反应堆技术仍在探索中」，当前核电站是通过核裂变将核能转换为热能来发电的。"},{"i":46,"c":2,"t":3,"s":"抽水蓄能电站可在无外界电力供应的情况下迅速自启动，并为其他机组提供启动功率，这种作用称为黑启动。","a":"对","e":"考点：抽水蓄能电站五大作用之一的黑启动。课件依据：「抽水蓄能电站可在无外界电力供应的情况下，迅速自启动，并为其他机组提供启动功率，使电力系统在短时间内恢复供电」。"},{"i":47,"c":2,"t":3,"s":"从全国发电装机容量占比来看，太阳能发电已经超过火电，成为我国装机占比最高的电源类型。","a":"错","e":"考点：我国电力装机结构。课件所引国家能源局全国电力工业统计中，火电装机占比仍为各电源类型之首（两版数据分别为43%、39.6%），太阳能装机占比位居第二。"},{"i":48,"c":2,"t":3,"s":"生物质能发电在可再生能源发电中电能质量好、可靠性高，可以作为小水电、风电、太阳能发电的补充能源。","a":"对","e":"考点：生物质能发电的特点与定位。课件依据：「其在可再生能源发电中电能质量好、可靠性高，比小水电、风电和太阳能发电等间歇性发电要好得多，可以作为小水电、风电、太阳能发电的补充能源」。"},{"i":451,"c":2,"t":3,"s":"储能技术路线大体可分为物理储能、化学储能和电磁储能三大类。","a":"对","e":"考点：储能技术路线的分类。依据：「储能路线＝物理储能＋化学储能＋电磁储能」，其中抽水蓄能属于目前最成熟的物理储能。"},{"i":452,"c":2,"t":3,"s":"抽水蓄能电站的综合运行效率大约在70%～80%之间。","a":"对","e":"考点：抽水蓄能的综合效率指标。依据：「抽蓄综合效率＝70%～80%」，反映了抽水—发电循环过程中的能量损耗水平。"},{"i":453,"c":2,"t":3,"s":"抽水蓄能机组的电机在发电工况下作为电动机运行，在抽水工况下作为发电机运行。","a":"错","e":"考点：抽蓄机组电机的可逆运行方式。依据：「M/G＝发电时发电机，抽水时电动机」，两种工况的运行方式正好相反。"},{"i":454,"c":2,"t":3,"s":"光伏发电利用光生伏特效应，将太阳光能直接转换为电能。","a":"对","e":"考点：光伏发电的基本原理。依据：「光伏＝光生伏特效应，太阳能直接转电能」，与光热发电经热能中转的路径不同。"},{"i":487,"c":2,"t":3,"s":"在储能技术的分类中，氢燃料电池属于化学储能。（　）","a":"对","e":"依据课件分类表，氢燃料电池与锂离子电池、液流电池、铅蓄电池等同属化学储能；超级电容器、超导储能才属于电磁储能。"},{"i":621,"c":2,"t":3,"s":"我国水能资源理论蕴藏量居世界首位，具有丰富的水电建设运营经验与技术储备。","a":"对","e":"考点：我国水电发展现状。笔记依据：「水能蕴藏量大：我国水能资源理论蕴藏量居世界首位」「技术积累：我国有丰富的水电建设运营经验与技术储备」。"},{"i":703,"c":2,"t":3,"s":"按2025年全国电力工业统计数据，火电发电量占全国发电量的比重已降至三成左右。","a":"错","e":"考点：装机占比与发电量占比的区别。课件表格载明2025年火电装机占比39.6%，但发电量占比仍约60.8%，火电依然是电量供应的主力。"},{"i":704,"c":2,"t":3,"s":"在天生桥一级、天生桥二级、鲁布革三座水电站中，鲁布革水电站的设计水头是最低的。","a":"错","e":"考点：三座水电站设计水头的对比。课件载明：天生桥一级设计水头80米、天生桥二级176米、鲁布革372米，鲁布革为三者最高而非最低。"},{"i":706,"c":2,"t":3,"s":"核聚变需要轻核在超高温（1亿℃以上）、高压条件下结合成更稳定的重核。","a":"对","e":"考点：核聚变的发生条件。课件原文：“轻核（氢、氘、氚）在极端条件下（超高温--1亿℃以上、高压）结合成更稳定的重核（氦）”，其单位质量释放能量约为裂变的3～4倍。"},{"i":49,"c":3,"t":1,"s":"变电站是电力系统的关键节点，下列不属于变电站主要承担的功能是（）。","a":"A","e":"考点：变电站的功能定位。课件依据：「变电站是电力系统的关键节点，主要承担电压转换、电能分配、系统保护及电网稳定等功能」，电能生产属于发电环节。","o":["电能生产","电压转换","电能分配","系统保护"]},{"i":50,"c":3,"t":1,"s":"变电运行专业是电力系统中负责变电站电气设备安全、稳定、经济运行的核心技术岗位，其主要涵盖的工作是（）。","a":"C","e":"考点：变电运行专业的业务范围。课件依据：「变电运行专业……主要涵盖变电站的巡视、维护、倒闸操作及事故处理等工作」；其余选项分别对应变电检修、电气试验、继保自动化专业。","o":["主变压器A修及技改修理","电气设备预防性试验和交接试验","设备巡视、设备维护、倒闸操作及事故处理","继电保护装置的调试与校验"]},{"i":51,"c":3,"t":1,"s":"变电运行专业严格执行“两票三制”，其中“三制”是指交接班制、巡回检查制以及（）。","a":"D","e":"考点：“两票三制”的内容。课件依据：「“两票三制”严格执行：工作票、操作票、交接班制、巡回检查制、设备定期试验轮换制是安全基石」。","o":["设备缺陷闭环管理制","安全工器具定期检验制","倒闸操作监护制","设备定期试验轮换制"]},{"i":52,"c":3,"t":1,"s":"倒闸操作可改变电气设备的运行状态和电力系统的运行方式，下列不属于电气设备运行状态的是（）。","a":"D","e":"考点：设备四种状态。课件依据：倒闸操作以「改变电气设备运行状态（运行、热备用、冷备用、检修）」为目的，调试不属于其中。","o":["运行","热备用","冷备用","调试"]},{"i":53,"c":3,"t":1,"s":"发生危及人身、电网及设备安全的紧急状况时需进行事故处理，该流程中最先进行的环节是（）。","a":"C","e":"考点：事故处理流程顺序。课件依据：事故处理按「初步检查→初步汇报→详细检查→详细汇报→隔离故障→恢复送电→汇报归档」的流程开展。","o":["详细检查","隔离故障","初步检查","恢复送电"]},{"i":54,"c":3,"t":1,"s":"变电站设备验收时，要求核对一致的是（）。","a":"B","e":"考点：设备验收要求。课件依据：设备验收中要求「五防主机、监控后台机、现场实际三者一致」。","o":["监控后台机与调度端实时数据","五防主机、监控后台机与现场实际","工作票与操作票的编号","设计图纸与施工日志"]},{"i":55,"c":3,"t":1,"s":"关于变电站人工巡视，下列说法正确的是（）。","a":"A","e":"考点：人工巡视的特点。课件依据：运维人员「使用热成像仪、望远镜等工具，通过望、听、闻来检查判断设备的健康状态」，且「可以手动开启端子箱、机构箱门进行巡视」。","o":["可以手动开启端子箱、机构箱门进行巡视","通过望、闻、尝三种感官方式判断设备状态","即使设备有明显异味也不能判定其异常","巡视工具主要是万用表和秒表"]},{"i":56,"c":3,"t":1,"s":"与人工巡视相比，无人机巡视的优点是（）。","a":"D","e":"考点：无人机巡视优缺点。课件依据：「无人机具有灵活机动的特点，能够快速到达变电站各个角落检查设备运行状态，且能远方开启巡视，不需要人员到站」；其缺点恰恰是不能进入室内。","o":["能够进入室内对室内设备进行全面检查","必须由人员携带到现场方可启动","受设备空间影响极大，户外窄小区域完全无法使用且无补救措施","能快速到达变电站各个角落，且能远方开启巡视，不需要人员到站"]},{"i":57,"c":3,"t":1,"s":"关于自然油循环风冷变压器上层油温的规定，正确的是（）。","a":"D","e":"考点：主变油温限额。课件依据：「自然油循环风冷变压器上层油温不得超过95℃，一般不宜经常超过85℃」。","o":["上层油温不得超过85℃，一般不宜经常超过75℃","上层油温不得超过105℃，无其他限制","上层油温可随意升高，只需每小时抄表记录","上层油温不得超过95℃，一般不宜经常超过85℃"]},{"i":58,"c":3,"t":1,"s":"主变巡视时对呼吸器的检查要求是外观无破损，硅胶变色不超过（）。","a":"D","e":"考点：呼吸器巡检标准。课件依据：「呼吸器外观无破损，硅胶变色不超过2/3；并随着油温的变化油杯中有气泡产生」。","o":["1/3","1/2","3/4","2/3"]},{"i":59,"c":3,"t":1,"s":"高压断路器通断元件包括触头、导电部分、灭弧介质和灭弧室等，其中灭弧介质通常为（）。","a":"B","e":"考点：断路器灭弧介质。课件依据：「通断元件是断路器的核心部分……灭弧介质通常为真空或SF6」。","o":["空气和水","真空或SF6","绝缘漆膜","变压器油蒸汽"]},{"i":60,"c":3,"t":1,"s":"运行中的SF6断路器出现压力降低闭锁时，正确的处理方法是（）。","a":"C","e":"考点：SF6气压闭锁处置。课件依据：「运行中的SF6断路器出现压力降低闭锁时，禁止带负荷进行分、合闸操作。应立即断开故障断路器的控制电源……断开上一级断路器，将故障断路器退出运行」。","o":["立即带负荷对该断路器进行分闸隔离","反复试分试合断路器以确认是否误闭锁","立即断开故障断路器的控制电源，及时采取措施断开上一级断路器，将故障断路器退出运行","维持原状继续运行，等待计划检修处理"]},{"i":61,"c":3,"t":1,"s":"KYN型高压开关柜被隔板分成若干单元，下列不属于其划分单元的是（）。","a":"B","e":"考点：开关柜结构分区。课件依据：「KYN高压开关柜由固定的柜体和可抽出部件（简称手车）两大部分组成。开关柜被隔板分成手车室（断路器室）、母线室、电缆室和继电器仪表室」。","o":["手车室（断路器室）","电容器室","电缆室","母线室"]},{"i":62,"c":3,"t":1,"s":"对高压开关柜进行红外热成像测温时，导电回路电流接近的不同间隔外壳温度差异不应超过（）。","a":"B","e":"考点：开关柜测温判据。课件依据：「对高压柜进行红外热成像测温，导电回路电流接近的不同间隔外壳温度差异不应超过5℃」。","o":["3℃","5℃","8℃","10℃"]},{"i":63,"c":3,"t":1,"s":"电流互感器在运行中二次回路严禁开路，这是因为一旦开路（）。","a":"D","e":"考点：CT二次不开路的原理。课件依据：「当二次开路时，电流互感器二次侧产生数千伏的高压，对二次绝缘构成威胁，严重时造成互感器损坏，对运行人员产生危险」。","o":["二次电流剧增，必定烧毁全部测量仪表","一次侧断路器会立即自动跳闸","仅影响计量准确性，并无安全危害","二次侧将产生数千伏的高电压，威胁二次绝缘和运行人员安全"]},{"i":64,"c":3,"t":1,"s":"电压互感器在运行中二次回路如果发生短路，可能造成的后果是（）。","a":"A","e":"考点：PT二次不短路的原理。课件依据：「如二次短路时，二次通过的电流增大，造成二次小开关跳闸或保险熔断，影响表计指示及引起保护误动」。","o":["二次通过的电流增大，造成二次小开关跳闸或保险熔断，影响表计指示并可能引起保护误动","二次侧产生数千伏高电压击穿绝缘","对回路运行没有任何影响","使一次绕组立刻烧毁"]},{"i":65,"c":3,"t":1,"s":"电容式电压互感器实质上是利用若干个电容器（）的原理，通过电磁装置感应出标准规定的二次电压。","a":"A","e":"考点：电容式TV的分压原理。课件依据：「电容式电压互感器实质上是用若干个电容器串联，利用电容器串联分压的原理，通过电磁装置感应出标准规定的电压互感器的二次电压」。","o":["串联分压","并联分流","谐振放大","整流降压"]},{"i":66,"c":3,"t":1,"s":"避雷器接入电网的方式是（）。","a":"B","e":"考点：避雷器接线方式。课件依据：「避雷器是变电站保护设备免遭雷电波侵害的设备。它连接在导线与地之间，与被保护设备并联」。","o":["与被保护设备串联连接在回路中","连接在导线与地之间，与被保护设备并联","经隔离开关接入直流母线","只能安装于主变低压侧中性点处"]},{"i":67,"c":3,"t":1,"s":"雷雨过后巡视检查防雷装置时，避雷器在线监测仪的泄漏电流应在（）范围内。","a":"A","e":"考点：防雷装置雷后特巡项目。课件依据：「雷雨过后必须巡视检查防雷装置……检查在线监测仪的泄漏电流小于1mA且大于0mA」。","o":["小于1mA且大于0mA","大于1mA即可","等于0mA","无任何数值要求"]},{"i":68,"c":3,"t":1,"s":"测控装置及监控系统可实现“四遥”功能，完成对变电站设备的监视和控制。“四遥”是指（）。","a":"A","e":"考点：监控系统四遥功能。课件依据：测控装置及监控系统可以实现「“四遥”功能：遥测、遥控、遥信、遥调」。","o":["遥测、遥控、遥信、遥调","遥测、遥信、遥视、遥印","遥控、遥感、遥测、遥录","遥信、遥调、遥播、遥存"]},{"i":69,"c":3,"t":1,"s":"在220kV变电站内作业时，作业人员与带电设备应保持的最小安全距离为（）。","a":"C","e":"考点：不同电压等级安全距离。课件依据：「安全距离不足：220kV：3米及以上、110kV：1.5米及以上、10kV:0.7米及以上」（另35kV为1米、500kV为5米），其余选项均为其他电压等级的限值。","o":["1米","1.5米","3米","5米"]},{"i":70,"c":3,"t":1,"s":"进入密闭空间作业时应先通风再检测后作业，并有人监护，空间内氧含量应保持在（）。","a":"C","e":"考点：有限空间作业条件。课件依据：「密闭空间应先通风再检测后作业，并有人监护。确保氧含量在19.5%～23.5%，内部温度超过50℃时不应进行作业」。","o":["16%～18%","25%～30%","19.5%～23.5%","31%～35%"]},{"i":71,"c":3,"t":1,"s":"按照现场安全管控要求，标示牌悬挂高度离地面一般为（）。","a":"C","e":"考点：标示牌悬挂高度。课件依据：「标示牌悬挂高度离地面1.5米～1.8米（现场设备不满足悬挂高度要求的，按照现场实际调整）」。","o":["0.8米～1米","1.2米～1.5米","1.5米～1.8米","2米～2.5米"]},{"i":72,"c":3,"t":1,"s":"外单位办理需签发的工作票时应实行“双签发”，正确的顺序是（）。","a":"B","e":"考点：工作票双签发制度。课件依据：「先由工作负责人所在单位签发，再由本设备运维单位会签」。","o":["先由本设备运维单位签发，再由工作负责人所在单位会签","先由工作负责人所在单位签发，再由本设备运维单位会签","只需本设备值班负责人一人签发确认","由调度许可人代签即可"]},{"i":466,"c":3,"t":1,"s":"母线在变电站中的主要作用是（　）。","a":"D","e":"母线是汇集、分配和传输电能的载流导体；变换电压靠变压器，切断短路电流靠断路器，补偿无功靠电容器组和电抗器。","o":["切断短路电流","补偿无功功率","变换电压等级","汇集、分配和传输电能"]},{"i":473,"c":3,"t":1,"s":"主变压器的主要作用是（　）。","a":"D","e":"主变压器通过电磁感应升高或降低电压等级，便于功率的升压输送与降压分配；分配电能靠母线，切断故障电流靠断路器，限制过电压靠避雷器。","o":["分配电能","切断故障电流","限制过电压","变换电压，以利于功率的传输"]},{"i":476,"c":3,"t":1,"s":"变压器保护按信息来源可分为电气量保护和非电量保护。下列属于非电量保护的是（　）。","a":"C","e":"瓦斯保护采集油流速、油压、油位等非电气量信息，属于典型的非电量保护；差动保护、过流保护反应电气量变化，属电气量保护。","o":["线路过流保护","变压器差动保护","瓦斯保护","电容器保护"]},{"i":481,"c":3,"t":1,"s":"变电站母线的运行电压一般不得超过其额定电压的（　）。","a":"B","e":"按变电站运行要求，母线运行电压不得超过其额定电压的±10%。","o":["±5%","±10%","±15%","±20%"]},{"i":492,"c":3,"t":1,"s":"一级重要客户的两路电源应当来自（　）。","a":"B","e":"为保证供电可靠性，一级重要客户的两路电源应当来自两个不同的变电站；临时重要客户在条件允许时也可通过临时架线等方式具备双回路或两路以上电源。","o":["同一变电站的同一母线段","两个不同的变电站","同一变电站的不同母线段","同一电网的同一条线路"]},{"i":564,"c":3,"t":1,"s":"严格按照工作票的流程开展变电站工作，其正确顺序是（　）。","a":"C","e":"考点：工作票流程顺序。笔记依据：「严格按照工作票的流程开展工作：接收→布置→许可→终结」。","o":["许可→接收→布置→终结","布置→许可→接收→终结","接收→布置→许可→终结","接收→许可→布置→终结"]},{"i":628,"c":3,"t":1,"s":"变电技术是电力系统的核心技术之一，按课件归纳，它广泛应用于（　）。","a":"C","e":"考点：变电技术的行业应用范围。依据：变电技术「广泛应用于发电、输电、配电及用电各个环节，确保电能安全、高效、稳定地传输和分配」。其余选项均缩小了应用范围。","o":["仅发电和输电环节","仅变电和配电环节","发电、输电、配电及用电各个环节","仅输电和用电环节"]},{"i":630,"c":3,"t":1,"s":"SVG、STATCOM 等电力电子设备在变电业务中的应用越来越广泛，按课件的表述，其主要目的是（　）。","a":"D","e":"考点：电力电子设备在变电业务中的应用目的。课件依据：「电力电子设备在变电业务中的应用越来越广泛，如SVG和STATCOM等，以提高电能质量」。降低造价、减少占地、增加有功输出均非课件所述目的。","o":["降低变电站工程造价","减少变电站占地面积","增加有功功率输出","提高电能质量"]},{"i":633,"c":3,"t":1,"s":"无人机对变电站内设备进行巡视时，采用的成像方式是（　）。","a":"B","e":"考点：无人机巡视采用的技术手段。课件依据：「无人机通过可见光和红外成像对变电站内设备进行巡视」。其余成像方式均不属于课件所述无人机巡视手段。","o":["X射线成像","可见光和红外成像","超声波成像","微波雷达成像"]},{"i":636,"c":3,"t":1,"s":"高压隔离开关由五个部件组成。下列不属于其组成部分的是（　）。","a":"D","e":"考点：高压隔离开关的部件构成。课件依据：「高压隔离开关由五个部件组成：开断导电部分、绝缘部分、传动机构、支持底座、操动机构」。隔离开关没有灭弧装置，灭弧室是断路器通断元件的组成部分。","o":["传动机构","支持底座","操动机构","灭弧室"]},{"i":638,"c":3,"t":1,"s":"关于避雷针的作用，下列说法正确的是（　）。","a":"A","e":"考点：避雷针的作用。课件依据：「避雷针是为了防止直击雷对变电站设备的侵害」，其核心作用是吸收雷击电能，「通过引下线和接地装置将雷电波引入大地」；避雷针高于电气设备等其他设备以吸引雷电放电，B、C与之相悖，D所述限残压是避雷器的工作原理。","o":["避雷针用于防止直击雷对变电站设备的侵害，并通过引下线和接地装置将雷电波引入大地","避雷针主要用于防止感应雷和沿线路传入的雷电波的侵害","避雷针应比周围电气设备布置得矮一些，以避免吸引雷电","避雷针依靠阀片电阻限制残压，使流过雷电流时的电压降不超过设备的冲击放电电压"]},{"i":639,"c":3,"t":1,"s":"二次设备构建了变电站的“神经中枢”。按课件表述，变电站二次设备的核心功能是（　）。","a":"B","e":"考点：二次设备的核心功能定位。课件依据：二次设备构建变电站的“神经中枢”，其核心功能是「通过自动化与信息化手段实现对一次设备的监测、控制、保护及通信」，最终使变电站具备智能化管理与远程调度能力。其余选项均为一次设备或站用电源的职能。","o":["完成电压等级的变换并向负荷分配电能","通过自动化与信息化手段实现对一次设备的监测、控制、保护及通信","直接承担电能在电网中的输送任务","把站用高压电变换为站内设备使用的低压电源"]},{"i":647,"c":3,"t":1,"s":"按照变电站防中毒等常用的控制措施，有限空间作业使用的灯具应满足的要求是（　）。","a":"A","e":"考点：密闭空间防中毒的控制措施。课件依据：「密闭空间应先通风再检测后作业，并有人监护」「有限空间灯具应防潮防爆」，且内部温度超过50℃时不应进行作业。","o":["防潮防爆","防电磁辐射","防小动物侵入","抗强紫外线"]},{"i":73,"c":3,"t":2,"s":"下列属于变电专业范畴的有（）。","a":"ABCE","e":"考点：变电专业的构成。课件依据：变电专业分为「变电运行专业、变电检修专业、电气试验专业、继保自动化专业、站用电源专业」五大类。","o":["变电运行","电气试验","站用电源","输电线路带电作业","继保自动化"]},{"i":74,"c":3,"t":2,"s":"变电站设备巡视既依靠感官观察也借助仪器检测，下列属于巡视方法的有（）。","a":"ABCD","e":"考点：巡视方法分类。课件依据：巡视方法包括「目测法、鼻嗅法、耳听法、手触法、仪器检测法」，凭想象推断不属于巡视方法。","o":["目测法","鼻嗅法","耳听法","手触法","凭想象推断法"]},{"i":75,"c":3,"t":2,"s":"变电运行专业的核心维护业务按维护对象可分为（）。","a":"ABC","e":"考点：运行专业维护业务分类。课件依据：运行专业核心维护业务分为「一次设备维护」「二次设备维护」「辅助设备维护（冷却系统、蓄电池、消防设施等）」三类。","o":["一次设备维护","二次设备维护","辅助设备维护","技改工程的施工作业"]},{"i":76,"c":3,"t":2,"s":"依据课件，倒闸操作的一般流程环节包括（）。","a":"ABC","e":"考点：倒闸操作流程。课件依据：流程包括「接受调度命令、操作票填写、操作票审核、风险分析、倒闸操作、记录及汇报」等环节，无票操作被严格禁止。","o":["接受调度命令","操作票填写与审核","倒闸操作完成后进行记录及汇报","为争取时间允许无票直接操作"]},{"i":77,"c":3,"t":2,"s":"变电站事故处理流程中涉及的环节有（）。","a":"ABD","e":"考点：事故处理流程环节。课件依据：事故处理流程为「初步检查、初步汇报、详细检查、详细汇报、隔离故障、恢复送电、汇报归档」，返厂修理不属于该流程。","o":["初步检查、初步汇报","详细检查、详细汇报","将故障设备转运返厂修理","隔离故障、恢复送电"]},{"i":78,"c":3,"t":2,"s":"关于人工巡视的说法，正确的有（）。","a":"ABD","e":"考点：人工巡视方法与优缺点。课件依据：人工巡视优点为「灵活，不受户内和户外的限制」「可手动开启端子箱、机构箱门进行巡视」，缺点是「成本高，耗时长」，故C错误。","o":["运维人员可使用热成像仪、望远镜等工具，通过望、听、闻检查判断设备健康状态","可以手动开启端子箱、机构箱门进行巡视","成本低、耗时短，是最经济的巡视方式","具有灵活性，不受户内和户外的限制"]},{"i":79,"c":3,"t":2,"s":"母线的巡视维护要求包括（）。","a":"ABC","e":"考点：母线巡视维护要点。课件依据：母线巡视要求「支柱绝缘子应清洁无裂纹，无污闪和放电痕迹」，D项与之相反。","o":["母线电流不能超过额定电流值，母线运行电压不得超过额定电压的±10%","与母线相连的金具无裂纹和异常声响，各个连接点的温度正常","对于硬母线应设立伸缩节观察点，防止抱死引起支柱绝缘子断裂","支柱绝缘子表面存在污闪和放电痕迹属于正常现象"]},{"i":80,"c":3,"t":2,"s":"关于单母线接线的特点，说法正确的有（）。","a":"BCD","e":"考点：单母线接线优缺点。课件依据：单母线「接线简单、操作方便、设备少、经济性好」，但「可靠性差」，故A项错误。","o":["可靠性最高，广泛用于大型枢纽变电站","接线简单、操作方便、设备少、经济性好","母线或母线隔离开关检修或故障时，该母线上所有回路都要停电","电源只能并列运行，不能分列运行"]},{"i":81,"c":3,"t":2,"s":"关于变电站安健环和安全标志的设置要求，正确的有（）。","a":"BCD","e":"考点：安健环标志设置三要求（安全、醒目、便于视读）。课件依据：「标志设置后，不应有造成人身、设备伤害的潜在危险」，A项相反。","o":["标志设置后允许带有少量造成人身伤害的潜在危险","有某种不安全的因素而需要用标志加以提醒时，应设置相应的安全标志","安全标志牌应设在与安全有关的醒目地方","悬挂式和柱式的环境信息标志牌的下缘距地面的高度不宜小于2m"]},{"i":82,"c":3,"t":2,"s":"关于分数断路器双母线（3/2接线），下列说法正确的有（）。","a":"AC","e":"考点：3/2接线特点。课件依据：3/2接线「运行的可靠性和灵活性很高」，但「一条回路故障有二台开关要跳开」「继电保护装置比其他接线要复杂很多」，故B、D错误。","o":["检修母线或回路开关时不必用隔离开关进行大量的倒闸操作","一条回路故障时只有一台开关要跳开","运行的可靠性和灵活性很高","该接线对继电保护装置没有任何特殊要求"]},{"i":83,"c":3,"t":2,"s":"主变的巡视维护要求包括（）。","a":"ACD","e":"考点：主变巡视项目。课件依据：「呼吸器外观无破损，硅胶变色不超过2/3」，B项超过限额仍运行的说法错误。","o":["瓦斯继电器内应充满油，油色无浑浊变黑现象，继电器无集聚气体","呼吸器硅胶变色超过2/3仍可不处理继续运行","变压器正常运行时发出的电磁响声应是连续均匀的“嗡嗡”声","套管瓷套完好无脏污、破损，无放电现象，油位指示在正常范围内"]},{"i":84,"c":3,"t":2,"s":"高压断路器由五个组成部分构成，除通断元件和操动机构外，还包括（）。","a":"ABD","e":"考点：断路器五大部件。课件依据：高压断路器五个组成部分为「通断元件、中间传动机构、操动机构、绝缘支撑件、基座」，瓦斯继电器是变压器的部件。","o":["中间传动机构","基座","瓦斯继电器","绝缘支撑件"]},{"i":85,"c":3,"t":2,"s":"关于高压开关柜（KYN型）的构成与巡视要求，正确的有（）。","a":"ABD","e":"考点：开关柜结构与巡视要求。课件依据：「每一单元均良好接地」「机构储能指示应处于‘储满能’状态」，C项明显违反该要求。","o":["柜内每一单元均良好接地","继电器室的面板上安装有微机保护装置、操作把手、仪表、状态指示灯等","机械储能指示处于“未储能”状态时可正常运行","开关机构已储能时机械储能指示正确、储能指示灯亮"]},{"i":86,"c":3,"t":2,"s":"关于电流互感器，下列说法正确的有（）。","a":"ABC","e":"考点：CT特性。课件依据：「电流互感器二次不允许开路」「一次电流的大小与二次负荷的电流无关」「正常工作时，由于阻抗很小，接近于短路状态」，开路会产生数千伏高压，D项错误。","o":["二次回路不允许开路","一次电流的大小与二次负荷的电流无关","正常工作时由于阻抗很小，接近于短路状态","二次开路只会让测量读数变小，并无其他危害"]},{"i":87,"c":3,"t":2,"s":"电容式电压互感器的组成部分包括（）。","a":"ABCD","e":"考点：电容式TV四大组成。课件依据：电容式电压互感器组成部分包括「电容分压器（C1 C2）、中间变压器（T）、补偿电抗器（L）、铁磁谐振阻尼装置（Ld Rd）」。","o":["电容分压器（C1、C2）","中间变压器（T）","补偿电抗器（L）","铁磁谐振阻尼装置（Ld、Rd）"]},{"i":88,"c":3,"t":2,"s":"关于防雷装置，下列说法正确的有（）。","a":"ACD","e":"考点：防雷装置原理与配置。课件依据：「避雷器在额定电压下，相当于绝缘体」，B项错误；A、C、D均符合课件表述。","o":["避雷器连接在导线与地之间，与被保护设备并联","避雷器在额定电压下相当于良导体","避雷针的核心作用是防止直击雷对变电站设备的侵害","避雷器监测器（计数器）可记录动作次数并监测泄漏电流的变化"]},{"i":89,"c":3,"t":2,"s":"关于电容器组和电抗器，说法正确的有（）。","a":"ACD","e":"考点：无功补偿两件套。课件依据：电容器组投入可「补偿系统无功」使电压升高，电抗器「吸收容性无功」「抑制电压过度升高」；巡视要求外壳无鼓肚、膨胀变形，B项错误。","o":["电容器组是变电站的无功补偿装置","发现电容器外壳鼓肚、膨胀变形时只需擦拭干净便可继续运行","当母线电压低于规定范围时投入电容器组，可以使电压升高","电抗器吸收容性无功，能抑制电压过度升高"]},{"i":90,"c":3,"t":2,"s":"关于变电站内的安全自动装置，说法正确的有（）。","a":"ABC","e":"考点：两种常见安自装置。课件依据：常见安自装置为「备用电源自动投入装置（BZT）」和「低频低压减载装置」，其侧重点为「故障后恢复、预防异常扩大」；切除短路故障是继电保护的职责。","o":["备用电源自动投入装置在工作电源故障时自动切换至备用电源，保障重要负荷供电","低频低压减载装置在系统频率、电压大幅下降时按优先级切除负荷，防止全网崩溃","安全自动装置侧重于故障后恢复、预防异常扩大","安全自动装置可以取代继电保护装置切除各类短路故障"]},{"i":91,"c":3,"t":2,"s":"关于工作票相关人员的安全管理规定，正确的有（）。","a":"ABD","e":"考点：工作票人员任职回避。课件依据：「工作票签发人、工作负责人禁止相互兼任，工作许可人不得兼任工作票签发人（会签人）、工作班成员」，C项与其矛盾。","o":["工作票签发人与工作负责人禁止相互兼任","工作许可人不得兼任工作票签发人","同一张工作票中，工作许可人可以同时担任工作票签发人","工作许可人不得兼任工作班成员"]},{"i":92,"c":3,"t":2,"s":"关于防小动物设施的“三道防线”及其巡视要求，正确的有（）。","a":"ABC","e":"考点：防小动物三道防线。课件依据：第一道为电缆沟封堵、第二道为电缆沟出入口封堵、第三道为柜体封堵；巡视要求「各密封口封堵严实无漏洞或裂缝」，D项错误。","o":["第一道防线是电缆沟封堵","第二道防线是电缆沟出入口封堵","第三道防线是柜体封堵","巡视中发现个别封堵物存在裂缝属正常现象，无需处理"]},{"i":93,"c":3,"t":2,"s":"下列属于变电站二次设备的有（）。","a":"ABD","e":"考点：一、二次设备划分。课件依据：二次设备包含「继电保护、安全自动装置、测控装置及监控系统、直流系统」，主变压器是一次设备。","o":["继电保护装置","安全自动装置","主变压器","直流系统"]},{"i":94,"c":3,"t":2,"s":"变电站作业中常用的风险辨识方法有（）。","a":"ABCD","e":"考点：风险辨识五种常用方法。课件依据：常用方法包括「作业流程分析法、安全规程对照法、经验案例法、情景模拟法、头脑风暴法」，侥幸忽略法不是风险辨识方法。","o":["作业流程分析法","安全规程对照法","经验案例法","头脑风暴法","侥幸忽略法"]},{"i":95,"c":3,"t":2,"s":"厂站第一种工作票“工作要求的安全措施”栏中应填写的内容包括（）。","a":"ABCD","e":"考点：第一种工作票安全措施栏内容。课件依据：安全措施包括「应拉开的断路器和隔离开关」「应投切的相关直流电源……低压及二次回路」「应合上的接地刀闸、装接的地线、应设绝缘挡板」「应设遮栏、应挂标示牌（位置）」。","o":["应拉开的断路器和隔离开关的双重名称或编号","应合上的接地刀闸、装设的接地线（装设地点）及应设的绝缘挡板","应投切的相关交直流电源、低压及二次回路","应设遮栏、应挂标示牌及其位置"]},{"i":588,"c":3,"t":2,"s":"按照课程归纳，变电站作业的风险类别包括（　）。","a":"ABDE","e":"考点：变电站作业风险分类。笔记依据：「变电站作业风险：设备风险、环境风险、操作与管理风险、触电风险、其他风险」。","o":["设备风险","触电风险","备品备件短缺风险","操作与管理风险","环境风险"]},{"i":589,"c":3,"t":2,"s":"变电站直流系统的组成部分包括（　）。","a":"ACD","e":"考点：直流系统的构成。笔记依据：「直流系统：为系统提供电源与数据传输通道。组成：监控装置、充电模块、蓄电池」。","o":["监控装置","柴油发电机组","充电模块","蓄电池"]},{"i":590,"c":3,"t":2,"s":"变电站继电保护装置中，非电量保护所依据的信息包括（　）。","a":"ABD","e":"考点：继电保护按电气量与非电量的划分。笔记依据：「构成：电气量保护（电压、电流）、非电量保护（油压、油位、油流速）」；二次电流属电气量。","o":["油压","油位","二次电流","油流速"]},{"i":629,"c":3,"t":2,"s":"课件归纳了变电业务的行业应用范围，下列说法正确的有（　）。","a":"BCD","e":"考点：变电业务的三大行业应用。课件依据：「随着城市化进程加快，变电业务在城市电网改造和升级中发挥关键作用」「变电业务为各类工业生产提供强大电力支持」「在太阳能、风能等可再生能源并网中起到桥梁作用」。电能的远距离大容量输送由输电线路承担，变电业务并不取代输电线路，A错误。","o":["主要用于取代输电线路，承担电能远距离大容量输送任务","在城市电网改造和升级中发挥关键作用，保障电力供应稳定","为各类工业生产提供强大电力支持，确保生产线连续运作和高效率","在太阳能、风能等可再生能源并网中起到桥梁作用，促进清洁能源的广泛应用"]},{"i":631,"c":3,"t":2,"s":"关于变电业务的发展趋势，下列说法正确的有（　）。","a":"ABCE","e":"考点：变电业务的发展趋势。课件列举了智能变电站逐渐普及、电力电子设备广泛应用、应对可再生能源大规模并网挑战、数字化推动智能化网络化发展等内容；变电技术应用于电能传输和分配的各环节，不可能脱离电力系统独立运行，D错误。","o":["智能变电站逐渐普及，利用自动化和信息化技术提高电网运行效率","电力电子设备（如SVG、STATCOM）的应用越来越广泛","面临可再生能源大规模并网的挑战，需优化电网结构以适应清洁能源的接入","脱离电力系统独立运行，不再需要与发、用电环节相互配合","数字化技术推动变电业务向智能化、网络化方向发展，实现数据的实时监控和分析"]},{"i":632,"c":3,"t":2,"s":"课件介绍的变电站设备巡视方式包括下列各项中的（　）。","a":"ABD","e":"考点：变电站设备巡视方式的构成。课件列出的巡视方式为人工巡视、无人机巡视和机器狗巡视三种；巡视必须实地检查设备状态，凭想象推断不属于巡视方式。","o":["人工巡视","无人机巡视","凭想象和经验推断的事后“巡视”","机器狗巡视"]},{"i":634,"c":3,"t":2,"s":"高压断路器俗称开关。关于开关的作用，下列说法正确的有（　）。","a":"ACD","e":"考点：高压断路器的作用。课件依据：断路器是电力系统重要的开关设备，「在正常运行时断路器可以接通和切断电气设备的空载电流和负荷电流，在系统发生故障时则能可靠地切断短路电流」，故正常时严禁接通负荷电流的说法错误。","o":["正常运行时可以接通和切断电气设备的空载电流","正常运行时严禁接通负荷电流，只能用于测量电压","正常运行时可以接通和切断电气设备的负荷电流","系统发生故障时能可靠地切断短路电流"]},{"i":635,"c":3,"t":2,"s":"关于隔离开关（刀闸），下列说法正确的有（　）。","a":"ABD","e":"考点：隔离开关的作用特点。课件依据：「分闸位置时其触头之间有符合规定的绝缘距离和可见断口」「合闸位置时能承载正常工作电流及短路电流」「没有灭弧装置，俗称刀闸」；因其无灭弧装置不能带负荷拉合，C错误。","o":["分闸位置时其触头之间有符合规定的绝缘距离和可见断口","合闸位置时能承载正常工作电流及短路电流","具有灭弧装置，可以用来接通和切断正常的负荷电流","没有灭弧装置，俗称刀闸"]},{"i":637,"c":3,"t":2,"s":"按结构划分，电流互感器的类型包括下列各项中的（　）。","a":"ABC","e":"考点：电流互感器的结构类型。课件列出的类型为干式电流互感器、浇注式电流互感器、油浸式电流互感器和气体绝缘电流互感器；阻波式不属于电流互感器的结构类型。","o":["干式电流互感器","浇注式电流互感器","油浸式电流互感器","阻波式电流互感器"]},{"i":641,"c":3,"t":2,"s":"下列属于常规220kV变电站组成的有（　）。","a":"ABDE","e":"考点：常规220kV变电站的组成。课件依据：「常规220kV变电站的组成：主控室、220kV设备区、110kV设备区、10kV配电室」，其中不包含500kV设备区。","o":["主控室","220kV设备区","500kV设备区","110kV设备区","10kV配电室"]},{"i":643,"c":3,"t":2,"s":"课件用生活化的例子说明了风险辨识的作用。下列属于风险辨识作用的有（　）。","a":"ACD","e":"考点：风险辨识的作用。课件将其概括为提前躲坑、少花冤枉钱、做事更靠谱、心里有谱，核心都是事前防范、提前准备；事故发生后的追责处罚不属于风险辨识的作用。","o":["提前做好准备，防止问题突然发生造成损失","事故发生后据此认定责任人并进行处罚","避免盲目投入，少花冤枉钱","把可能的麻烦列出来，明确重点防范对象，减少意外发生"]},{"i":644,"c":3,"t":2,"s":"下列属于变电站作业中“设备风险”具体表现的有（　）。","a":"ACD","e":"考点：设备风险的三类表现。课件将电气设备故障、继电保护失效、防雷接地问题列为设备风险的具体内容；保护装置正确动作属于保护功能的正常发挥，不属于风险表现。","o":["变压器、断路器等设备老化、绝缘损坏，可能引发短路、过载甚至火灾","保护装置正确动作、及时切除故障元件","保护装置误动作或拒动作，可能导致故障范围扩大","接地系统不良时，雷击易造成设备损坏及人员触电"]},{"i":645,"c":3,"t":2,"s":"下列属于变电站作业中“环境风险”的有（　）。","a":"ABC","e":"考点：环境风险的类别。课件将环境风险归纳为自然灾害、温湿度异常和外力破坏三类；未穿戴防护装备、违规进入高压区域属于操作与管理风险中安全意识不足的问题，电磁辐射属于其他风险。","o":["暴雨、台风等自然灾害可能导致设备进水、设备短路爆炸","高温或潮湿环境会加速设备老化，引发短路","周边施工、动物闯入（如蛇、鼠）可能损坏电缆或设备","未穿戴防护装备、违规进入高压区域开展作业","高压设备运行的电磁辐射对人员健康的长期影响"]},{"i":646,"c":3,"t":2,"s":"下列属于变电站作业中“其他风险”的有（　）。","a":"AB","e":"考点：“其他风险”的内容。课件所列其他风险为电磁辐射（需符合安全标准）和火灾爆炸两类；安全距离不足引发的触电属于触电风险，倒闸操作不按规程执行属于操作与管理风险。","o":["高压设备运行时的电磁辐射可能对周边人员健康产生长期影响","油浸式变压器漏油遇明火，或蓄电池发热可能引发火灾爆炸","作业时与带电设备保持的安全距离不足引发人身触电","倒闸操作未按规程执行，可能引发停电事故"]},{"i":96,"c":3,"t":3,"s":"变电站按功能可分为升压变电站、降压变电站和变频变电站三类。","a":"错","e":"考点：变电站按功能分类。课件依据：「变电站按功能可分为升压变电站、降压变电站」，变频站不属于此分类。"},{"i":97,"c":3,"t":3,"s":"隔离开关（刀闸）没有灭弧装置，因此不能带负荷拉合。","a":"对","e":"考点：隔离开关的特性。课件依据：隔离开关「没有灭弧装置，俗称刀闸」，分闸时只提供可见断口，严禁带负荷操作。"},{"i":98,"c":3,"t":3,"s":"无人机可以进入变电站室内，对室内设备进行全面巡视检查。","a":"错","e":"考点：无人机巡视的局限性。课件依据：「无人机不能进入室内巡视室内设备，室外设备空间较小的地方无人机也无法进行巡视，需要摄像头进行补充」。"},{"i":99,"c":3,"t":3,"s":"当沿线路传入变电站的雷电冲击波超过避雷器保护水平时，避雷器立即导通将雷电流引入大地；电压值正常后，避雷器又迅速恢复原状。","a":"对","e":"考点：避雷器动作原理。课件依据：「当沿线路传入变电站的雷电冲击波超过避雷器保护水平时，避雷器立即导通，将雷电流经过良导体安全的引入大地……当电压值正常后，避雷器又迅速恢复原状」。"},{"i":100,"c":3,"t":3,"s":"采用单母线分段接线时，任一出线的开关检修，该回线路可以不停电继续运行。","a":"错","e":"考点：单母线分段接线的缺点。课件依据：「任一出线的开关检修时，该回线路必须停电」。"},{"i":101,"c":3,"t":3,"s":"具备并列运行的站用变，在低压侧并列前，必须检查高压侧确已并列（分段开关已合上）。","a":"对","e":"考点：站用变并列运行前提。课件依据：「具备并列运行的站用变，在低压侧并列前，必须检查高压侧确已并列（分段开关合上）」。"},{"i":102,"c":3,"t":3,"s":"抢修任务特别紧急时，经值班负责人口头同意即可不用操作票直接进行倒闸操作，事后补记即可。","a":"错","e":"考点：倒闸操作票纪律。课件依据：「倒闸操作必须按操作票逐项执行，严禁跳项、漏项」，不得无票操作。"},{"i":103,"c":3,"t":3,"s":"状态检修（CBM）依托在线监测数据评估设备健康状态，可减少不必要的停电检修，正逐步替代定期检修。","a":"对","e":"考点：变电运行专业特点之设备管理精细化。课件依据：「状态检修（CBM）替代定期检修：依托在线监测数据……减少不必要的停电检修」。"},{"i":104,"c":3,"t":3,"s":"值班负责人收到工作票后，即使发现工作票未按要求填写或各栏填写错误、不明确，也应先行签名接收，待开工前再让工作负责人当面改正。","a":"错","e":"考点：工作票接收审核要求。课件依据：「值班负责人在审票时发现未按要求填写工作票、工作票各栏填写错误或不明确的，应拒收工作票」。"},{"i":105,"c":3,"t":3,"s":"由承包商承接变电站检修工作时，该承包商的工作负责人必须进行现场勘察。","a":"对","e":"考点：现场勘查强制情形。课件依据：「对本设备运维单位内部工作负责人，必要时开展现场勘察。对承包商的工作负责人，必须进行现场勘察」。"},{"i":106,"c":3,"t":3,"s":"在室外高压设备上工作时，应在工作地点四周装设遮栏，并将“止步，高压危险！”标示牌朝向外面悬挂。","a":"错","e":"考点：遮栏与标示牌的朝向。课件依据：「在室外高压设备上工作时在工作地点四周装设遮栏，并悬挂朝向里面的“止步，高压危险！”标示牌」，警示对象是遮栏内的人员。"},{"i":107,"c":3,"t":3,"s":"变电站设备验收是由建设单位、运行单位、监理单位等相关单位按照合同、技术协议、设计图纸及相关标准、规程的要求，对设备进行全面检查、测试、审核和确认的过程。","a":"对","e":"考点：设备验收的定义。课件依据：「变电站设备验收是指在新设备安装完成、设备大修后或技术改造后，由相关单位……对设备进行的全面检查、测试、审核和确认的过程」。"},{"i":494,"c":3,"t":3,"s":"变电站的直流系统主要为继电保护、控制、通信等关键设备提供直流电源。（　）","a":"对","e":"直流系统是变电站的重要二次设备，为保护、控制、通信及事故照明等关键负荷提供可靠的直流电源，而不是交流电源。"},{"i":609,"c":3,"t":3,"s":"在变电站作业中，触碰未充分放电的电容器不属于引起触电的原因。","a":"错","e":"考点：触电原因的识别。笔记依据：「触电原因：作业时与带电设备保持的安全距离不足、触碰未充分放电的电容器」。"},{"i":610,"c":3,"t":3,"s":"站用变的作用是把高压电变为站内设备使用的电压等级，输出220V相电压和380V线电压，并有干式和油浸式两种类型。","a":"对","e":"考点：站用变的功能与输出电压。笔记依据：「站用变：高压变为设备使用的电压等级，输出220V相电压和380V线电压，干式和油浸式」。"},{"i":611,"c":3,"t":3,"s":"变电站按电压传输方式可分为直流（DC）变电站和交流（AC）变电站。","a":"对","e":"考点：变电站按电压传输方式的分类。笔记依据：「变电站分类：……直流（DC）、交流（AC）变电站（电压传输方式）」。"},{"i":640,"c":3,"t":3,"s":"变电站二次设备分工明确：继电保护装置可实时识别故障并触发跳闸，测控系统采集运行数据并支持远程操作，直流与通信设备为系统提供电源与数据传输通道。","a":"对","e":"考点：二次设备各子系统的功能分工。课件依据：「继电保护装置可实时识别故障并触发跳闸」「测控系统采集运行数据并支持远程操作」「直流与通信设备为系统提供电源与数据传输通道」。"},{"i":642,"c":3,"t":3,"s":"风险辨识是指在事故发生之后查明事故原因、划分责任归属的过程。","a":"错","e":"考点：风险辨识的概念。课件指出，风险辨识是事前「发现潜在问题」的动作——看看身边可能有哪些会出问题的地方，即所谓“找麻烦”的过程，并不是事后查明原因和划分责任。"},{"i":108,"c":4,"t":1,"s":"10kV配电网采用n供一备型接线时，两供一备和三供一备的设备利用率分别为（ ）。","a":"C","e":"考查n供一备型接线的设备利用率数值对比。课件依据：「设备利用率高，三供一备为75%，两供一备为67%」。","o":["均为50%","50%和75%","67%和75%","75%和100%"]},{"i":109,"c":4,"t":1,"s":"关于10kV配电网辐射型接线，下列说法正确的是（ ）。","a":"A","e":"辐射型的优点是接线简单、投资省、新增负荷连接方便，设备利用率可达100%；缺点是供电可靠性低，故障或检修点以后部分无法转供电。B为单环网型的优点，50%利用率也是单环网型的特征。","o":["接线简单、投资省，设备利用率可达100%，但供电可靠性低","一回线路故障时，非故障段可由另外一回线路转供电","能满足N-1安全准则，供电可靠性高","结构复杂，设备利用率仅为50%"]},{"i":110,"c":4,"t":1,"s":"10kV电网的中性点接地一般采用（ ）方式。","a":"B","e":"课件依据：「10kV电网的中性点接地一般采用经小电阻接地或经消弧线圈接地方式，低压配电网中性点接地一般采用直接接地方式」。注意区分中压与低压配电网的接地方式。","o":["中性点直接接地","中性点经小电阻接地或经消弧线圈接地","中性点不接地","中性点经电容器接地"]},{"i":111,"c":4,"t":1,"s":"按照公司标准电压等级的划分，10kV属于（ ）。","a":"C","e":"课件依据：「中压：10kV」，低压为380/220V，高压指220kV、110kV和35kV。课堂强调过10kV属于中压而不属于高压。","o":["超高压","高压","中压","低压"]},{"i":112,"c":4,"t":1,"s":"普通型和轻型钢芯铝绞线用于一般地区，而加强型钢芯铝绞线（LGJJ）适用于（ ）。","a":"D","e":"课件依据：「普通型和轻型钢芯铝绞线用于一般地区，加强型钢芯铝绞线用于重冰区和大跨越地段」。A、B为绝缘导线的适用场合。","o":["城市人口密集地区","风景绿化区、林带区等污秽严重地区","一般地区","重冰区和大跨越地段"]},{"i":113,"c":4,"t":1,"s":"下列关于普通拉线应用场合的说法，正确的是（ ）。","a":"B","e":"普通拉线应用于终端杆、转角杆、分支杆和耐张杆等处，用于平衡固定性的不平衡荷载。A为人字拉线、C为十字拉线、D为V形拉线的特点。","o":["装设于垂直线路方向两侧，用来加强电杆防风抗倾倒能力，多用于直线杆","应用在终端杆、转角杆、分支杆和耐张杆等处，主要用来平衡固定性的不平衡荷载","装设在顺线路和横线路方向，用来加强耐张杆的稳定性","在电杆较高、横担层数较多、架设多条导线之处，于受力点上下两处装设"]},{"i":114,"c":4,"t":1,"s":"关于电缆直埋敷设方式，下列说法正确的是（ ）。","a":"A","e":"课件依据：「直埋敷设……具有投资小、施工方便和散热条件好等优点，是最经济而广泛采用的一种敷设方法」，适用于电缆根数较少的场合。B为排管敷设、C为沟道敷设的特点。","o":["投资小、施工方便和散热条件好，是最经济而广泛采用的一种敷设方法","适用于交通频繁、城市地下走廊等较为拥挤的地段","须将电缆敷设在预先砌好的电缆沟中","只适用于电缆根数很多、走廊狭窄的场合"]},{"i":115,"c":4,"t":1,"s":"统计表明，在电缆线路事故中占电缆事故比例约70%的是（ ）。","a":"D","e":"课件依据：「电缆接头事故占电缆事故的70％」，由于外力破坏的事故占电缆事故的30％，电缆接头是电缆线路的薄弱环节。","o":["雷击闪络事故","绝缘自然老化事故","动物啃咬事故","电缆接头事故"]},{"i":116,"c":4,"t":1,"s":"按照课程要求，目前新安装的三相配电变压器要求的型号为（ ）。","a":"D","e":"课件依据：「目前新安装的三相配电变压器要求的型号为：S11、S13和SH15」。SJ、SL、SLZ和S7型为高损耗配电变压器。","o":["SJ、SL、SLZ","S7、S9和SLZ","SC（B）9、SC（B）10","S11、S13和SH15"]},{"i":117,"c":4,"t":1,"s":"关于高压负荷开关的工作原理，下列说法正确的是（ ）。","a":"B","e":"课件依据：「一般装有简单的灭弧装置，但其结构比较简单」「气缸中的压缩空气通过喷口吹灭电弧」，负荷开关能切断额定负荷电流和一定的过载电流，但不能切断短路电流。","o":["完全依靠串接的熔断器熔断后产生的气体吹灭电弧","一般装有简单的灭弧装置，分闸时主闸刀先打开、灭弧闸刀再使弧触头分开，气缸中被压缩的气体经喷口吹灭电弧","具有完善的灭弧装置，能够可靠开断任意大小的短路电流","没有任何灭弧措施，仅靠拉开后形成明显的断开点"]},{"i":118,"c":4,"t":1,"s":"安装在配电网馈线回路的开关站、配电室、环网柜、箱式变电站等处，具有遥信、遥测、遥控和馈线自动化功能的配电自动化终端是（ ）。","a":"A","e":"课件依据：「站所终端（DTU），安装在配电网馈线回路的开关站、配电室、环网柜、箱式变电站等处」。FTU安装在配电网架空线路杆塔等处，TTU一般为计量自动化终端。","o":["站所终端（DTU）","馈线终端（FTU）","配变监测终端（TTU）","故障指示器"]},{"i":418,"c":4,"t":1,"s":"在10kV配电网中，分支线路和配电变压器常用的短路保护设备是（　）。","a":"A","e":"考点：跌落式熔断器的典型应用场合。依据：「跌落式熔断器＝10kV分支线、配变常用短路保护」。","o":["跌落式熔断器","隔离开关","避雷器","负荷开关"]},{"i":419,"c":4,"t":1,"s":"10kV配电网采用单环网接线方式时，其设备利用率约为（　）。","a":"C","e":"考点：配电网接线方式的设备利用率。依据：「辐射100%；单环网50%」；另有双环网、n供一备等利用率数据可对照记忆。","o":["100%","67%","50%","25%"]},{"i":533,"c":4,"t":1,"s":"在电力系统中，担负着分配电能任务的电力网称为（　）","a":"C","e":"输电网负责输送电能，配电网负责分配电能；“配电网”正是电力系统中担负分配电能任务的部分，二者共同构成电力网。","o":["输电网","发电网","配电网","电力网"]},{"i":534,"c":4,"t":1,"s":"配电架空线路中，导线是通过（　）固定在杆塔上的","a":"D","e":"架空配电线路中导线经绝缘子被固定、支持在杆塔上，绝缘子同时保证带电导线与杆塔之间的绝缘；拉线用于平衡杆塔受力。","o":["金具","横担","拉线","绝缘子"]},{"i":535,"c":4,"t":1,"s":"按照课程要求，超过（　）公里以上的输电线路需要进行导线换位","a":"B","e":"超过10公里以上的输电线路应进行导线换位，以减小三相参数不平衡带来的影响。","o":["5","10","15","20"]},{"i":537,"c":4,"t":1,"s":"跌落式熔断器型号RW中的“W”代表（　）","a":"A","e":"型号RW中R代表熔断器、W代表户外式，即RW为户外式高压熔断器的型号代码。","o":["户外","稳定","无灭弧","熔断器"]},{"i":538,"c":4,"t":1,"s":"配电系统中，B相母排涂的颜色是（　）","a":"C","e":"配电母线相色规定：A相涂黄色、B相涂绿色、C相涂红色，中性线（N）涂黑色。","o":["黄色","红色","绿色","黑色"]},{"i":539,"c":4,"t":1,"s":"配电线路用绝缘子的绝缘电阻要求为（　）","a":"B","e":"按要求绝缘子的绝缘电阻不应低于500兆欧，低于该值说明绝缘劣化，应及时检查更换。","o":["≥100兆欧","≥500兆欧","≥1000兆欧","≥2000兆欧"]},{"i":540,"c":4,"t":1,"s":"配电网中使用的直流电源，按安装方式分为（　）","a":"D","e":"配电网直流电源按安装方式分为直流电源屏和直流电源箱两种；蓄电池、整流模块是其内部组成而非安装方式分类。","o":["蓄电池和整流模块","主站和子站","高压和低压","直流电源屏和直流电源箱"]},{"i":561,"c":4,"t":1,"s":"10kV配电网采用单环网接线时，其设备利用率为（　），供电可靠性较高。","a":"D","e":"考点：单环网接线的设备利用率。笔记依据：「环网型（单环网：50%，供电可靠性较高；双环网：N-1-1:50%，N-1:75%）」。","o":["67%","75%","100%","50%"]},{"i":562,"c":4,"t":1,"s":"位于线路分段承力处，除承受垂直荷载、风荷载外，还需承受不平衡张力、断线张力的杆塔是（　）。","a":"C","e":"考点：杆塔按用途分类的受力特点。笔记依据：「耐张杆塔（线路分段承力处，还承受不平衡张力、断线张力）」。","o":["直线杆塔","跨越杆塔","耐张杆塔","换位杆塔"]},{"i":768,"c":4,"t":1,"s":"按照公司采用的标准电压等级划分，交流500kV属于（　）。","a":"B","e":"公司标准电压等级为：「直流±800kV和±500kV；交流超高压500kV；高压220kV、110kV和35kV；中压10kV；低压380/220V」。","o":["高压","超高压","中压","低压"]},{"i":773,"c":4,"t":1,"s":"在电力电缆的结构层中，起均匀导体表面电场、消除气隙作用的是（　）。","a":"A","e":"课件指出：「导体屏蔽（内半导电层）：均匀导体表面电场、消除气隙的作用」；绝缘屏蔽承担屏蔽并消除绝缘与金属屏蔽间的间隙，铠装层用于增加机械保护。","o":["导体屏蔽（内半导电层）","绝缘屏蔽（外半导电层）","金属屏蔽层","铠装层"]},{"i":774,"c":4,"t":1,"s":"下列属于干式配电变压器型号的是（　）。","a":"C","e":"课件列出常见干式配电变压器型号为「SC（B）9、SC（B）10、SC（B）11、SG（B）9、SG（B）10和SG（B）11」；SJ、SL、SLZ、S7、S11、S13、SH15等均为油浸式配电变压器型号。","o":["SH15","S13","SC(B)10","SLZ"]},{"i":776,"c":4,"t":1,"s":"关于矩形母线，下列说法正确的是（　）。","a":"D","e":"课件指出矩形母线「常用在35kV及以下的屋内配电装置中，具有散热条件好，集肤效应小，安装简单，连接方便等优点」，当工作电流超过单条允许电流时，每相可用两条或三条并列使用。","o":["散热条件差、不便于安装连接","只能用于户外敞开式布置","每相在任何情况下都只允许使用一条母线","常用在35kV及以下的屋内配电装置中"]},{"i":782,"c":4,"t":1,"s":"下列不属于绝缘子按结构分类类别的是（　）。","a":"D","e":"绝缘子按结构可分为「高低压绝缘子、悬式绝缘子、防污型绝缘子和套管绝缘子」；按绝缘材料的不同分为瓷绝缘子、玻璃绝缘子和复合绝缘子，不存在塑料绝缘子这一类别。","o":["高低压绝缘子","防污型绝缘子","套管绝缘子","塑料绝缘子"]},{"i":119,"c":4,"t":2,"s":"关于高压负荷开关与断路器的区别，下列说法正确的有（ ）。","a":"ABE","e":"课件依据：「负荷开关主要用于开断和关合负荷电流，断路器主要用于开断、关合故障、短路电流」。负荷开关构造与隔离开关相似、只加装简单灭弧装置，需要开断短路电流时要依靠与其串接的高压熔断器实现。","o":["负荷开关主要用于开断和关合负荷电流","断路器主要用于开断、关合故障、短路电流","负荷开关装有完善的灭弧装置，能直接切断短路电流","断路器不需要任何灭弧装置即可开断故障电流","自动化负荷开关设置有“得电合闸，失电分闸”的功能"]},{"i":120,"c":4,"t":2,"s":"高压开关柜的“五防”装置应具备的功能包括（ ）。","a":"ACDE","e":"五防即防止误分、误合断路器，防止带负荷分、合隔离开关，防止带电挂（合）接地线（接地开关），防止带地线送电，防止误入带电间隔。「防止相邻间隔发生短路」不属于五防内容。","o":["防止误分、误合断路器","防止相邻间隔发生短路","防止带负荷分、合隔离开关","防止带地线送电","防止误入带电间隔"]},{"i":121,"c":4,"t":2,"s":"10kV配电网的主要接线方式包括（ ）。","a":"BCDE","e":"课件依据：「主要接线方式可分为辐射型、环网型（单环网型和双环网型）、n供一备型和多分段n联络型」。低压配电网一般才采用以配电变压器为中心的辐射型接线。","o":["星形接线","辐射型","环网型（单环网型和双环网型）","n供一备型","多分段n联络型（n≤3）"]},{"i":122,"c":4,"t":2,"s":"下列10kV配电网接线方式中，能够满足N-1安全准则的有（ ）。","a":"ABD","e":"课件依据：「单辐射线路利用率为100%，分段联络、环网式网络架构、N供一备网络结构满足N-1供电准则」。单环网、双环网、n供一备均可满足N-1，仅单辐射不满足。","o":["单环网型","双环网型","单辐射型","三供一备型"]},{"i":123,"c":4,"t":2,"s":"关于互感器的使用注意事项，下列说法正确的有（ ）。","a":"ABC","e":"课件依据：「电流互感器使用时二次侧不得开路」「电压互感器二次侧严禁短路」，且两者的二次侧均有一端子必须接地，接线时端子极性不能接错。","o":["运行中的电流互感器二次侧未经旁路（短接）时，不允许拆下电流表、继电器等设备","电压互感器二次侧严禁短路，否则会烧断一次侧熔断器、计量停止","电流互感器和电压互感器的二次侧均规定有一端子必须接地","电流互感器二次侧可以随时开路，不影响运行","互感器接线时端子极性接反也不影响安全运行"]},{"i":124,"c":4,"t":2,"s":"下列关于电力电缆线路优缺点的说法，正确的有（ ）。","a":"ACE","e":"课件依据：「安全可靠 不占空间，不受外界影响维修工作量小」「造价高 不便分支 施工和维修难度大」。电缆不便分支且造价高，B、D说反了。","o":["安全可靠，不受外界影响","便于分支，造价低廉","不占用地面空间，维修工作量小","易于分支改接，工程造价低","施工和维修难度大"]},{"i":125,"c":4,"t":2,"s":"架空线路绝缘子的表面通常被做成波纹形，这样做的原因有（ ）。","a":"ADE","e":"课件依据：「一是可以增加绝缘子的泄漏距离……二是当下雨时……避免形成污水柱造成短路事故……三是污秽物质将不能均匀的附在绝缘子上」。B、C并非制作波纹形表面的原因。","o":["可以增加绝缘子的泄漏距离（爬电距离），每个波纹又能起到阻断电弧的作用","可以使导线免受雷电冲击的直接破坏","便于导线在杆塔上滑动位移","下雨时污水不会从绝缘子上部直接流到下部，避免形成污水柱造成短路事故","污秽物质将不能均匀地附着在绝缘子上"]},{"i":126,"c":4,"t":2,"s":"高压负荷开关常见的类型有（ ）。","a":"ABCE","e":"课件依据将高压负荷开关分为固体产气式、压气式、压缩空气式、SF6式、真空式等类型，如「压气式高压负荷开关：利用开断过程中活塞的压气吹灭电弧」。油浸式不属于其中的分类。","o":["固体产气式高压负荷开关","压气式高压负荷开关","SF6式高压负荷开关","油浸式高压负荷开关","真空式高压负荷开关"]},{"i":127,"c":4,"t":2,"s":"电力电缆工程敷设的主要方式包括（ ）。","a":"BCD","e":"课件依据：「电力电缆敷设主要有直埋敷设、排管敷设、沟道敷设等方式」，此外还有隧道敷设、桥架敷设、电缆竖井敷设、架空敷设等方式。敷设方法分为人力敷设和机械敷设。","o":["绑扎敷设","沟道敷设","直埋敷设","排管敷设","缠绕敷设"]},{"i":128,"c":4,"t":2,"s":"配网自动化系统的基本组成部分包括（ ）。","a":"ABCD","e":"课件依据：「配网自动化系统包括配电自动化主站、配电自动化子站、配电自动化终端以及配网通信通道」，主站与子站、终端之间的通信通道主要有光纤、载波、无线等。","o":["配电自动化主站","配电自动化子站","配电自动化终端","配网通信通道","计量自动化系统"]},{"i":542,"c":4,"t":2,"s":"配网自动化系统的通信通道主要有（　）","a":"BCD","e":"配网自动化系统的通信通道主要有光纤、载波和无线三种方式，“电缆”不是此处所指的通信通道类型。","o":["电缆","光纤","载波","无线"]},{"i":543,"c":4,"t":2,"s":"故障指示器按实现功能可分为（　）","a":"ABD","e":"故障指示器按实现功能分为就地型、远传型和智能型三类，“自动型”不是规范分类。","o":["就地型","远传型","自动型","智能型"]},{"i":594,"c":4,"t":2,"s":"配电网故障指示器按功能划分，可分为（　）。","a":"ABC","e":"考点：故障指示器的两种分类维度。笔记依据：「故障指示器分类：按安装位置分架空线路型和电缆型；按功能分就地型、远传型、智能型」。","o":["就地型","远传型","智能型","机械型"]},{"i":769,"c":4,"t":2,"s":"配电网中性点常用的接地方式包括（　）。","a":"ACD","e":"课件指出配电网中性点接地方式「常用有三种：中性点直接接地、中性点经小电阻接地、中性点经消弧线圈接地」，不同方式对绝缘水平、过电压保护和继电保护方式均有影响。","o":["中性点直接接地","中性点经电抗器接地","中性点经小电阻接地","中性点经消弧线圈接地"]},{"i":770,"c":4,"t":2,"s":"架空配电线路的杆塔按材料分类，主要包括（　）。","a":"ACD","e":"杆塔按材料分为「钢筋混凝土杆（水泥杆）、铁塔（钢管杆）、木杆」三类；铝绞线是传导电流的导线品种，不属于杆塔类别。","o":["钢筋混凝土杆（水泥杆）","铝绞线","铁塔（钢管杆）","木杆"]},{"i":129,"c":4,"t":3,"s":"低压配电网一般采用以配电变压器为中心的辐射型接线。","a":"对","e":"课件依据：「低压配电网一般采用以配电变压器为中心的辐射型接线」。注意区分主体：若题干写成10kV配电网则错误。"},{"i":130,"c":4,"t":3,"s":"电缆附件中，电缆终端通常称为电缆终端头，电缆接头通常称为电缆中间头。","a":"对","e":"课件依据：「电缆终端通常称为电缆终端头，电缆接头通常称为电缆中间头」，二者是对应关系，不可混淆称呼。"},{"i":131,"c":4,"t":3,"s":"玻璃绝缘子表面处于压缩预应力状态，如发生裂纹和电击穿将自行破裂成碎块（俗称“自爆”），因此玻璃绝缘子在运行中无须进行“零值”检测。","a":"对","e":"课件依据：「如发生裂纹和电击穿，玻璃绝缘子将自行破裂成不碎块，俗称『自爆』。这一特性使得玻璃绝缘子在运行中无须进行『零值』检测」。"},{"i":132,"c":4,"t":3,"s":"对于具有五防功能的高压开关柜，在未合接地刀闸前打不开柜门、无法进行直接验电时，可进行间接验电，且判断时应有几个指示均已同时发生对应变化，才能确认设备已无电。","a":"对","e":"课件依据：「可进行间接验电。通过设备的机械指示位置、电气指示、带电显示装置、仪表和各种遥测、遥信等信号的变化来判断。判断时应有两个及以上的指示，且所有指示均已同时发生对应变化，才能确认设备已无电」。"},{"i":133,"c":4,"t":3,"s":"高压组合式变电站俗称“欧变”，并且相对于高压预装式变电站，其占地面积更大。","a":"错","e":"俗称弄反了：高压预装式变电站俗称“欧变”。课件依据：「将变压器器身、开关设备、熔断器……放置在变压器油箱内的成套设备，俗称美变。相对于预装式变电站，组合式变电站占地更小」。"},{"i":134,"c":4,"t":3,"s":"电缆线路故障分析表明：由于外力破坏的事故占电缆事故的70%，电缆接头事故约占电缆事故的30%。","a":"错","e":"两者比例颠倒了。课件依据：「电缆接头事故占电缆事故的70％」「由于外力破坏的事故占电缆事故的30％」。"},{"i":455,"c":4,"t":3,"s":"变压器既可以改变交流电压的大小，也可以同时改变交流电的频率。","a":"错","e":"考点：变压器的功能边界。依据：「变压器改变交流电压，但频率不变」。"},{"i":456,"c":4,"t":3,"s":"电压等级6kV及以上的电力电缆，其结构中还需增加屏蔽层。","a":"对","e":"考点：电缆结构与电压等级的关系。依据：「电缆＝导体＋绝缘层＋护套；6kV以上增加屏蔽层」，屏蔽层可使电场分布均匀并提高运行安全性。"},{"i":536,"c":4,"t":3,"s":"高压跌落式熔断器主要用于10kV配电线路。","a":"对","e":"高压跌落式熔断器主要用于10kV中压配电线路，可实现过载和短路保护，并在规定条件下分合空载变压器及线路。"},{"i":541,"c":4,"t":3,"s":"耐张杆塔正常运行时承受垂直荷载、风荷载和不平衡张力，发生断线事故时还将承受断线张力。","a":"对","e":"耐张杆塔起锚固导线作用，正常运行时承受垂直荷载、风荷载和不平衡张力，事故情况下还要承受断线张力。"},{"i":544,"c":4,"t":3,"s":"单环网接线方式的设备利用率为75%。","a":"错","e":"单环网接线方式的设备利用率为50%；75%是三供一备接线的设备利用率，两者不可混淆。"},{"i":545,"c":4,"t":3,"s":"目前中压开关柜主要以微机防误闭锁装置为主。","a":"错","e":"目前中压开关柜主要采用机械联锁（机械程序锁）实现“五防”闭锁，而非以微机防误闭锁装置为主。"},{"i":546,"c":4,"t":3,"s":"配电变压器按绝缘方式可分为干式和油浸式两大类。","a":"对","e":"配电变压器按绝缘方式分为干式变压器和油浸式变压器两大类。"},{"i":623,"c":4,"t":3,"s":"中压架空线路采用绝缘导线后，就可以不再增设避雷器了。","a":"错","e":"考点：绝缘导线与避雷器的配置要求。笔记依据：「导线分类（按外绝缘层）：裸导线（中压线路）、绝缘导线（中压架空线路要增设避雷器）」。"},{"i":624,"c":4,"t":3,"s":"电缆的基本结构为导体、绝缘层、护套，6kV以上的电缆还具有屏蔽层。","a":"对","e":"考点：电缆结构与屏蔽层的电压界限。笔记依据：「电缆结构：导体、绝缘层、护套，6kV以上电缆有屏蔽层。中压配网使用交联聚乙烯绝缘电缆」。"},{"i":625,"c":4,"t":3,"s":"N-1安全准则是指正常运行方式下，电力系统中任一元件无故或因故断开，系统应能保持稳定运行和正常供电。","a":"对","e":"考点：N-1安全准则的定义。笔记依据：「N-1安全准则：正常运行电力系统中任一元件无故/因故断开，系统能保持稳定运行正常供电」。"},{"i":771,"c":4,"t":3,"s":"杆塔按用途可分为直线杆塔、耐张杆塔、转角杆塔、跨越杆塔和换位杆塔五类。","a":"错","e":"正确划分为「直线杆塔、耐张杆塔、转角杆塔、终端杆塔、特种杆塔」五类；跨越杆、换位杆只是特种杆塔下的具体形式，不能并列为其独立类别。"},{"i":772,"c":4,"t":3,"s":"拉线的主要作用是支撑导线，并使带电导线与杆塔之间保持良好的绝缘。","a":"错","e":"使导线与杆塔保持绝缘是绝缘子的功能。拉线的作用是「为平衡导线、避雷线的张力，保证杆塔的稳定性」，一般用于终端杆、转角杆、跨越杆等处。"},{"i":775,"c":4,"t":3,"s":"干式配电变压器的铁芯和绕组均浸入绝缘液体中。","a":"错","e":"恰好相反，课件定义「干式配电变压器：铁芯和绕组都不浸入绝缘液体中的变压器」；铁芯和绕组浸入绝缘油中的是油浸式配电变压器。"},{"i":777,"c":4,"t":3,"s":"将刀开关和熔断器串联组合成一个单元，称为刀开关熔断器组合电器（刀熔开关）。","a":"对","e":"课件指出：「刀开关和熔断器串联组合成一个单元，称为刀开关熔断器组合电器」；再增装操作杠杆、弹簧及弧刀等辅助元件，则可组合为负荷开关。"},{"i":778,"c":4,"t":3,"s":"高压隔离开关是指额定电压在1kV以上的隔离开关，其使用量大、工作可靠性要求高。","a":"对","e":"课件指出：「高压隔离开关即额定电压在1kV以上的隔离开关」，其本身工作原理及结构比较简单，但由于使用量大、工作可靠性要求高，对配电所、电站的设计建立和安全运行影响较大。"},{"i":779,"c":4,"t":3,"s":"高压跌落式熔断器也可装在长线路末端或分支线路上，对继电保护保护不到的范围提供保护。","a":"对","e":"课件说明跌落式熔断器的安装场所时指出：它「可装在杆上变压器高压侧、互感器和电容器与线路连接处」，「也可装在长线路末端或分支线路上，对继电保护保护不到的范围提供保护」。"},{"i":780,"c":4,"t":3,"s":"监测型配电自动化的常见形式是故障指示器，它主要由监测单元和通信单元组成。","a":"对","e":"课件指出：「监测型配电自动化：常见的为故障指示器」，通过检测故障电流的特征判别线路故障并将故障信息远传主站，「主要包含监测单元和通信单元」。"},{"i":781,"c":4,"t":3,"s":"配电自动化终端中的配变监测终端（TTU），一般为计量自动化终端。","a":"对","e":"课件注明：「配变监测终端简称TTU，一般为计量自动化终端」；馈线终端FTU装于配电网架空线路杆塔等处，站所终端DTU装于开关站、配电室、环网柜等处。"},{"i":135,"c":5,"t":1,"s":"配网调度应当按照国家有关法律、法规及电网运行的客观规律，保障配网安全、优质、经济、环保运行；同时按照有关规程、规定实施（　）调度，维护发电、供电、售电、用电等各方的合法权益。","a":"A","e":"考查配网调控的主要任务。课件依据：「按照有关规程、规定实施『公开、公平、公正』调度，维护发电、供电、售电、用电等各方的合法权益」；“安全、优质、经济、环保”是保障配网运行的总体目标，并非“三公”调度原则。","o":["公开、公平、公正","安全、优质、经济","统一、分级、协调","高效、廉洁、透明"]},{"i":136,"c":5,"t":1,"s":"按配网设备状态定义，“该设备已具备运行条件，其继电保护及自动装置满足运行要求，开关的控制、合闸及信号电源投入，经一次合闸操作即可转为运行状态”，这一描述对应的是设备的哪种状态？","a":"B","e":"考查设备四大状态的区分。课件依据：热备用状态是指该设备「已具备运行条件……经一次合闸操作即可转为运行状态的状态」；运行状态强调带有电压、功能有效，冷备用各侧有明显断开点，检修状态还要求可能来电的各侧均已接地。","o":["运行状态","热备用状态","冷备用状态","检修状态"]},{"i":137,"c":5,"t":1,"s":"合环转供电现场操作时，配电运维单位原则上应安排操作人员同时在合环点和解环点待令操作，以缩短合环时间。按课件规定，合解环操作宜在多长时间内完成？","a":"D","e":"考查合环转供电的操作管理要求。课件依据：「配电运维单位原则上应安排操作人员同时在合环点和解环点待令操作，缩短合环时间，合解环操作宜在10分钟内完成」。","o":["5分钟以内","30分钟以内","60分钟以内","10分钟以内"]},{"i":138,"c":5,"t":1,"s":"配网检修停电类型中，未纳入计划但又亟需开展的计划类检修属于哪一类，并且须严格执行“一支笔”审批？","a":"C","e":"考查配网检修停电类型的界定。课件依据：「临时检修：未纳入计划，但又亟需开展的计划类检修。须严格执行『一支笔』审批」；而计划检修指纳入年、月度停电计划并按规定时间提交申请的检修，紧急抢修（故障检修）指设备因事故停运或紧急消缺需要的抢修类检修。","o":["计划检修","紧急抢修","临时检修","定期检修"]},{"i":139,"c":5,"t":1,"s":"关于调度业务联系的语言要求，下列说法正确的是（　）。","a":"B","e":"考查调度业务联系基本原则。课件依据：「调度业务联系原则上应使用普通话：调度员下令必须使用普通话，工作负责人可以不用普通话，但必须口齿清楚」。","o":["调度员下令时可视沟通便利改用方言","调度员下令必须使用普通话，工作负责人可以不用普通话，但必须口齿清楚","是否使用普通话由受令单位自行决定","普通话要求仅适用于调度员之间的内部联系"]},{"i":140,"c":5,"t":1,"s":"分布式电源装置是功率为数千瓦至50MW、与环境兼容的小型模块式独立电源。按课件的界定，它是不直接与集中输电系统相连的多少千伏及以下电压等级的电源？","a":"C","e":"考查分布式电源的基本概念。课件依据：分布式电源是「不直接与集中输电系统相连的35kV及以下电压等级的电源，主要包括发电设备和储能装置」。此外课件还指出小型水电站指单站装机容量5万千瓦以下的水电工程。","o":["10kV","20kV","35kV","110kV"]},{"i":141,"c":5,"t":1,"s":"配网调度员使用调度操作票下达操作命令或口头下达调度命令时，按调度用语规范，首先应说的是（　）。","a":"D","e":"考查调度用语的区分。课件依据：下达操作命令时首先说「现在开始下令」；“现在向你了解情况”“现在向你核实／确认”分别是了解情况和核实状态时的首要用语。","o":["现在向你了解情况","现在向你核实／确认","请各单位做好准备","现在开始下令"]},{"i":401,"c":5,"t":1,"s":"《中华人民共和国能源法》经审议通过后正式施行的日期是（　）。","a":"C","e":"考点：《能源法》施行时间。依据：「《能源法》于2025年1月1日起正式施行」。注意与2024年6月1日施行的新修订《供电营业规则》相区分。","o":["2024年6月1日","2024年12月1日","2025年1月1日","2025年6月1日"]},{"i":563,"c":5,"t":1,"s":"按照安全用电常识，单相三孔插座的正确接线方式是（　）。","a":"B","e":"考点：三孔插座接线口诀。笔记依据：「三插孔：左零右火中接地——左边零线（中性线）、右边火线（相线）、中间为接地线」。","o":["左火线、右零线、中间接地线","左零线、右火线、中间接地线","左接地线、右零线、上火线","任意接线均可，只要电器能工作"]},{"i":709,"c":5,"t":1,"s":"配网操作中保证安全的技术措施一般分为三类，它们分别是由（　）负责的安全措施。","a":"A","e":"考点：配网操作管理中安全措施的分工。课件原文：“保证安全的技术措施由设备运维单位具备相应资格的运行人员执行。一般分为三类，分别为调度负责的安全措施、运维单位负责的安全措施、施工单位负责的安全措施。”","o":["调度机构、设备运维单位、施工单位","设计单位、监理单位、建设单位","政府部门、供电企业、电力用户","南网总调、省级中调、地调"]},{"i":710,"c":5,"t":1,"s":"配网检修停电类型中，因设备事故停运或紧急消缺而需要开展的抢修类检修称为（　）。","a":"C","e":"考点：配网检修停电类型的界定。课件原文：“紧急抢修（故障检修）：设备因事故停运或紧急消缺需要进行抢修类检修”；临时检修指未纳入计划但又亟需开展的计划类检修，须严格执行“一支笔”审批。","o":["计划检修","临时检修","紧急抢修（故障检修）","状态检修"]},{"i":142,"c":5,"t":2,"s":"根据配网调度一般操作原则对操作模式的划分，下列属于规定操作模式的有（　）。","a":"BCD","e":"考查配网操作模式的构成。课件依据：操作模式分为「直接操作、委托操作、配合操作、许可操作」四种，“远方遥控操作”不在其中。","o":["远方遥控操作","直接操作","配合操作","许可操作"]},{"i":143,"c":5,"t":2,"s":"配网停电管理推行综合停电“六步法”，下列环节属于其中步骤的有（　）。","a":"ACD","e":"考查综合停电“六步法”的内容。课件依据：六步法为「状态检修、带电作业、转供电、合并停电事件、停电时间定额、重大停电审查」，“随工验收”不属于六个步骤之一。","o":["状态检修","随工验收","带电作业","转供电"]},{"i":144,"c":5,"t":2,"s":"关于配网调度操作命令中的综合令，其适用的操作对象包括下列哪些？","a":"AC","e":"考查综合令的适用范围。课件依据：综合令适用于「配变、开关（单侧配置刀闸或两侧均未配置刀闸的开关除外）、单辐射配电线路、继电保护及安全自动装置」，且只有涉及一个受令主体的操作才能使用综合令，B、D恰是被排除的开关类型。","o":["配变","单侧配置刀闸的开关","单辐射配电线路","两侧均未配置刀闸的开关"]},{"i":145,"c":5,"t":2,"s":"分布式电源并网管理提出“四可”要求，下列选项均属于“四可”所包含内容的有（　）。","a":"ABCD","e":"考查分布式电源“四可”要求。课件依据：「可观：运行状态可被实时监控；可测：对发电功率、电压、电流等数据具备准确测量能力；可调：可根据电网负荷需求调节电站的有功、无功功率输出；可控：确保发电项目可被电网远程或自动化控制」。","o":["可观","可测","可调","可控"]},{"i":146,"c":5,"t":2,"s":"配网调度与用户进行停／送电业务联系时的注意事项，下列说法正确的有（　）。","a":"ACD","e":"考查停／送电联系的注意事项。课件依据：「停电时注意用户私自搞工作（注意安措）；送电时提前通知用户做好准备；严禁约时停送电；注意用户的备用电源」，故B“无须提前通知”错误。","o":["停电时要注意用户私自搞工作的问题，注意安全措施","送电时无须提前通知用户，到时间直接送电即可","严禁约时停送电","要注意了解用户的备用电源情况"]},{"i":147,"c":5,"t":2,"s":"分布式电源接入会对配电网网损产生影响，按课件列举，决定这一影响程度的主要因素有哪些？","a":"ABD","e":"考查分布式电源对配电网网损影响的因素。课件依据：影响因素包括「分布式电源容量、分布式电源接入位置、负荷容量相对大小、网络拓扑结构」，用户电价水平不属于其中因素。","o":["分布式电源容量","分布式电源接入位置","用户的电价水平","网络拓扑结构"]},{"i":148,"c":5,"t":2,"s":"关于分布式电源接入配电网产生的影响，下列说法正确的有（　）。","a":"ABC","e":"考查分布式电源接入的多方面影响。课件依据：「分布式电源并网会增大配电网的短路电流水平」「大多数DG会装有逆功率继电器……使故障扩大危及整个系统的安全运行」「含分布式电源的配网部分可能会与系统解列，形成孤岛……控制复杂度提升，对检修安全造成影响」；电能质量方面课件指出的是谐波频率范围扩大，故D错误。","o":["分布式电源并网会增大配电网的短路电流水平","大多数DG装有逆功率继电器，故障瞬间电流注入电网可能导致断路器开断能力不足而不能有效切除故障","含DG的配网部分可能与系统解列形成孤岛，可为重要负荷供电，同时控制复杂度提升、对检修安全造成影响","大量DG接入可缩小谐波频率范围，显著改善配电网的电能质量"]},{"i":711,"c":5,"t":2,"s":"按课件归纳，分布式电源的主要形式包括下列哪些（　）。","a":"BCD","e":"考点：分布式电源的类型构成。课件归纳分布式电源形式包括风力发电、光伏发电、小水电、潮汐能发电、燃气轮机等小型模块式独立电源，大型凝汽式燃煤机组不属于分布式电源。","o":["大型凝汽式燃煤发电机组","小水电","燃气轮机","光伏发电"]},{"i":149,"c":5,"t":3,"s":"解口是通过拆除线路的电气连接，使无法通过设备操作实现隔离的待检修线路、设备与电源之间形成明显断开点并有足够的安全距离；解口后，被解口侧视为与原线路没有物理连接。","a":"对","e":"考查“解口”的概念。课件依据：「被解口侧视为与原线路没有物理连接，因检修工作需另行落实的安全措施由设备运维单位自行组织落实，工作结束后恢复与原线路连接前应自行解除」。"},{"i":150,"c":5,"t":3,"s":"对于涉及两个及以上厂站共同配合、有两个及以上受令主体的操作，为加快进度，配网调度员可以采用综合令一次性下达给各受令单位。","a":"错","e":"考查操作命令的适用条件。课件依据：「凡涉及两个及以上厂站共同配合，有两个及以上受令主体，并按一定逻辑关系才能进行的……均应使用逐项令」，且「只涉及一个受令主体的操作才能使用综合令」。"},{"i":151,"c":5,"t":3,"s":"设备处于冷备用状态，是指连接该设备的各侧均有明显的断开点或可判断的断开点，且需要检修的设备可能来电的各侧均已接地。","a":"错","e":"考查设备状态定义的区分。“可能来电的各侧均已接地，或与系统彻底隔离”是检修状态的特征；冷备用状态是指「连接该设备的各侧均无安全措施，且连接该设备的各侧均有明显断开点或可判断的断开点」。"},{"i":152,"c":5,"t":3,"s":"合环转供电操作过程中，配网调度员应检查、确认合环后环网线路的负荷、潮流正常，方可进行解环操作。","a":"对","e":"考查合环转供电的操作管理要求。课件依据：「合环转供电操作过程中，配网调度员应检查、确认合环后环网线路的负荷、潮流正常后方可进行解环操作」。"},{"i":153,"c":6,"t":1,"s":"下列设备中，属于变电一次设备的是（　）。","a":"C","e":"考查变电一次设备的辨识。课件依据：「变电一次设备……如：变压器、断路器、隔离开关、电流互感器、电压互感器、避雷器、电力电缆、高压开关柜、组合电气（GIS或HGIS）等」，继电保护装置、测控装置属二次设备范畴。","o":["微机继电保护装置","监控系统测控单元","电流互感器","直流电源屏"]},{"i":154,"c":6,"t":1,"s":"课件将检修定义为为评估、保持或提升设备状态，针对设备开展的巡检、带电检测、停电试验以及检查、保养和修复等工作的总称，并指出了其核心目标是（　）。","a":"B","e":"考查检修的定义与核心目标。课件依据：「其核心目标是确保电力设备安全、稳定、可靠地运行，预防故障发生，延长设备使用寿命」。","o":["尽量压缩停电时间，减少电量损失","确保电力设备安全、稳定、可靠地运行，预防故障发生，延长设备使用寿命","降低运维成本，实现检修效益最大化","提高设备优良率评级等考核指标"]},{"i":155,"c":6,"t":1,"s":"按照检修分类，避雷器带电测试、SF6气体测试等需要停电或不停电进行的周期性试验工作属于（　）。","a":"D","e":"考查检修分类的辨析。课件依据：「B2检修是指设备需要停电或不停电进行的周期性试验工作」，课件举例即为避雷器带电测试、SF6气体测试。","o":["A类检修","B1类检修","C1类检修","B2类检修"]},{"i":156,"c":6,"t":1,"s":"变电检修典型作业流程中，“作业前准备”阶段的工作内容是（　）。","a":"A","e":"考查典型作业流程的阶段划分。课件依据：「作业前准备：包括人员组织、作业方案与资料、工器具材料及备品备件准备等各方面」；工作票办理、安全交底属作业实施过程，归档闭环为最后阶段。","o":["人员组织、作业方案与资料、工器具材料及备品备件准备","办理工作票并进行安全交底","现场实施检修作业并采集试验数据","汇总检修记录和结论，办理归档闭环"]},{"i":157,"c":6,"t":1,"s":"变电检修工作中，用于指导工作票填写和使用的文件是（　）。","a":"C","e":"考查专业规章文件的适用对象。课件将「电气工作票技术规范」列为所需掌握的规范性文件，对应工作票填写、工作票使用两项技能。","o":["电力生产事故调查规程","公司设备维护检修手册","电气工作票技术规范","变电设备缺陷管理标准"]},{"i":471,"c":6,"t":1,"s":"在变电检修需掌握的规章文件中，适用于设备的检修、预试（预防性试验）工作的规程是（　）。","a":"C","e":"设备的检修和预防性试验工作应执行《电力设备检修试验规程》；事故调查规程用于事故调查分析，安全生产令是年度安全工作部署文件。","o":["安全生产令","电力生产事故调查规程","电力设备检修试验规程","电力安全工作规程"]},{"i":479,"c":6,"t":1,"s":"按检修分类，设备需要停电进行的局部检查、维修、更换、试验工作属于（　）。","a":"B","e":"B1类检修是需要停电进行的局部检查、维修、更换、试验工作；B2类是需要停电或不停电进行的周期性试验，C1类是不需要停电的一般巡维，A类则是整体性的停电检修。","o":["A类检修","B1类检修","B2类检修","C1类检修"]},{"i":493,"c":6,"t":1,"s":"在重要客户的用电检查管理中，一级及以上重要客户的现场检查周期为（　）。","a":"C","e":"对一级及以上重要客户应加密检查频次，每半年开展一次用电检查，以便及时掌握客户受电设施状况。","o":["每月1次","每季度1次","每半年1次","每年1次"],"n":"检查周期与本库#289所引“重要客户每年1次”的口径不一致，按模拟题库（一级及以上每半年1次）命题"},{"i":548,"c":6,"t":1,"s":"开展设备检修、预防性试验工作时，适用的规程是（　）","a":"C","e":"设备检修、预试工作适用《电力设备检修试验规程》；工作票填写使用《电气工作票技术规范》，事故调查另用《电力生产事故调查规程》。","o":["安全生产令","电力生产事故调查规程","电力设备检修试验规程","变电设备缺陷管理标准"]},{"i":549,"c":6,"t":1,"s":"变电站设备需要停电进行的局部检修，属于（　）类检修","a":"B","e":"B1类检修指需要停电进行的局部检修；注意区分B2类检修是指周期性试验工作，C类检修一般为不停电进行的检查维修试验。","o":["A1","B1","B2","C1"]},{"i":577,"c":6,"t":1,"s":"变电站母线采用涂色标识相别时，符合规范的做法是（　）。","a":"B","e":"考点：母线相色标识。笔记依据：「母线：汇集和分配电能作用：A相-黄色，B相-绿色，C相-红色，零线/中性线（N)-黑色」。","o":["A相红色、B相黄色、C相绿色、中性线黑色","A相黄色、B相绿色、C相红色、中性线（零线）黑色","A相绿色、B相红色、C相黄色、中性线白色","A相黄色、B相红色、C相蓝色、中性线黑色"]},{"i":648,"c":6,"t":1,"s":"变电一次检修专业是变电检修体系的核心专业之一，它承担的主要工作是（　）。","a":"B","e":"考查变电一次检修专业的职责定位。课件依据：「主要承担变电站所有高压主设备的检修维护工作，管控电网输电主干道设备状态，消除高压设备机械、绝缘、密封、电气类缺陷」，保障变电站主系统安全可靠送电。","o":["负责继电保护装置的定值整定与校验","承担变电站所有高压主设备的检修维护，管控电网输电主干道设备状态","主要负责输电线路通道内的树障清理","承担电力营销抄表收费与业扩报装"]},{"i":651,"c":6,"t":1,"s":"在电力系统中直接参与电能的生产、输送、分配和使用，构成电力主系统核心部分的电气设备统称为（　）。","a":"C","e":"考查变电一次设备的定义。课件依据：「变电一次设备是指在电力系统中直接参与电能的生产、输送、分配和使用的电气设备，是构成电力主系统的核心部分」，其作用是实现电能的变换、控制、保护和存储等功能。","o":["变电辅助设备","热工自动化设备","变电一次设备","变电站二次设备"]},{"i":654,"c":6,"t":1,"s":"变压器、断路器、隔离开关、互感器等变电一次设备相互连接在一起构成的电路，称为（　）。","a":"A","e":"考查主接线的概念。课件依据：「由这些设备连接在一起构成的电路，称之为变电一次接线或称主接线」。","o":["变电一次接线（又称主接线）","站用电系统接线","直流控制回路","远动通信回路"]},{"i":660,"c":6,"t":1,"s":"关于B1修及维护在检修工作中的定位，下列说法正确的是（　）。","a":"D","e":"考查B1修及维护的定位。课件依据：「B1修及维护属于中等深度的检修类别……及时处理显性及潜在问题，同时兼顾检修效率与成本」，是在控制成本的同时有效保障设备核心可靠性、实现「精准检修」的重要手段。","o":["属于最浅层的例行外观巡查，不涉及实际作业","属于最高等级检修，须对设备进行整体解体","与检修成本无关，追求无限度的检修深度","属于中等深度的检修类别，能及时处理显性及潜在问题，兼顾检修效率与成本"]},{"i":666,"c":6,"t":1,"s":"恢复性检修及维护的核心目标是（　）。","a":"D","e":"考查恢复性检修的定义与目标。课件依据：恢复性检修及维护是针对性能劣化或发生故障设备进行的「抢救性」修复措施，「核心目标是让设备重新具备安全运行能力，在保障电网稳定的同时，实现设备资源的高效利用」。","o":["尽可能压缩单次检修的工期","使设备性能全面超越出厂水平","仅消除影响观感的外部缺陷","让设备重新具备安全运行能力，在保障电网稳定的同时实现设备资源的高效利用"]},{"i":158,"c":6,"t":2,"s":"关于变电一次设备A、B、C三类检修及其相互关系，下列说法正确的有（　）。","a":"ABD","e":"考查三类检修的层级包含关系与A类定义。课件依据：「原则上A类检修应包括所有B类检修项目，B类检修应包含C类检修项目」「A类检修是指设备需要停电进行的整体检查、维修、更换、试验工作」。","o":["原则上A类检修应包括所有B类检修项目","B类检修应包含C类检修项目","C类检修应包括所有A类和B类检修项目","A类检修是指设备需要停电进行的整体检查、维修、更换、试验工作"]},{"i":159,"c":6,"t":2,"s":"变电检修专业的业务范畴涵盖下列哪些工作（　）。","a":"ABCD","e":"本题为全选题，考查业务范畴的完整清单。课件依据：「变电一次设备的A、B、C类检修、维护、缺陷处理、技改修理和变电一次设备的安装和验收工作」。","o":["变电一次设备的A、B、C类检修","变电一次设备的维护和缺陷处理","变电一次设备的技改修理","变电一次设备的安装和验收"]},{"i":160,"c":6,"t":2,"s":"变电检修典型作业流程中，“作业实施过程”阶段包括下列哪些环节（　）。","a":"ABC","e":"考查作业实施过程的环节构成。课件依据：「作业实施过程：包括工作票办理、安全交底、作业实施等各方面」；归档、闭环是作业完成后的另一阶段。","o":["办理工作票","安全交底","作业实施","检修记录归档并闭环"]},{"i":161,"c":6,"t":2,"s":"作业结束后进入“归档、闭环”环节，该环节应包括的内容有（　）。","a":"ABCE","e":"考查归档闭环的内容要素。课件依据：「归档、闭环：包括检修项目、检修记录、试验数据、遗留问题、结论等」，下年度检修计划不在其中。","o":["检修项目和检修记录","试验数据","遗留问题","下一年度检修工作计划","检修结论"]},{"i":162,"c":6,"t":2,"s":"下列属于恢复性检修相关日常工作内容的有（　）。","a":"BCD","e":"考查恢复性检修的定位与典型工作。课件依据：恢复性检修是针对性能劣化或发生故障设备进行的“抢救性”修复措施，主变渗漏油处理、更换受潮硅胶及呼吸器、操动机构常见故障处理等均在其列；例行巡视测温属C类一般巡维内容。","o":["设备例行巡视和红外测温","主变压器渗漏油处理（紧固法兰工艺）","受潮的硅胶、呼吸器更换","弹簧操动机构、气动操动机构等的常见故障处理"]},{"i":657,"c":6,"t":2,"s":"变电检修日常相关工作中，属于高压主设备解体检修、安装调试类业务的有（　）。","a":"ABDE","e":"考查变电检修日常相关业务的构成。课件将断路器、隔离开关、接地开关等的解体检修和清洗组装，互感器解体检修组装调整，主变A修及安装工艺和质量标准，GIS组合电器安装A修调试试验等列为主设备解体检修与安装调试类业务；补充加油、调整油位属日常维护类工作。","o":["断路器、隔离开关、接地开关等设备的解体检修和清洗组装","互感器解体、检修、组装和调整","补充加油、调整油位等日常维护作业","主变A修及其安装工艺和质量标准执行","GIS组合电器安装、A修、调试及试验"]},{"i":663,"c":6,"t":2,"s":"下列属于B1修及维护日常工作内容的有（　）。","a":"ABCE","e":"考查B1修及维护的典型工作。课件列举了变电设备清扫、SF6电气设备补气、补充加油调整油位、设备发热缺陷处理等B1修及维护内容；GIS解体A修属A类检修范畴。","o":["变电设备清扫","六氟化硫电气设备补气","补充加油、调整油位","GIS组合电器解体A修","设备发热缺陷处理"]},{"i":163,"c":6,"t":3,"s":"C类检修是指设备不需要停电进行的检查、维修、更换、试验工作。","a":"对","e":"考查C类检修的定义。课件依据：「C类检修是指设备不需要停电进行的检查、维修、更换、试验工作」，其下分C1一般巡维和C2专业巡维、动态巡维。"},{"i":164,"c":6,"t":3,"s":"变电工程验收时只需核查施工工艺和设备外观，试验数据和资料完整性不属于验收核查内容。","a":"错","e":"考查工程验收的核查要素。课件依据：工程验收需「按照规范、设计图纸与技术标准，分阶段核查施工工艺、设备质量、试验数据、资料完整性，检验工程是否满足设计、送电投运条件」。"},{"i":669,"c":6,"t":3,"s":"检修工艺是“规矩”，技能是“执行能力”，二者结合是保证变电一次设备检修工作“修必修好、安全高效”的关键。","a":"对","e":"考查检修工艺与检修技能的关系。课件依据：「检修工艺是‘规矩’，技能是‘执行能力’，二者结合是保证变电一次设备检修工作‘修必修好、安全高效’的关键」。"},{"i":165,"c":7,"t":1,"s":"变压器利用闭合铁芯高效传递交变磁场能量，在原、副线圈间实现电压的升高或降低，其核心工作原理是（　）。","a":"B","e":"考查变压器的工作原理。课件依据：「核心原理：电磁感应……在原副线圈间实现电压的升高或降低」，能量以磁场为媒介传递。","o":["光生伏特效应","电磁感应原理","电化学效应","静电感应原理"]},{"i":166,"c":7,"t":1,"s":"课件总结，从发电厂到用户插座，电能至少经历“升压→降压→再降压”的关键电压变换，所需关键变换的总次数是（　）。","a":"C","e":"考查电能输送过程中的变压环节数量。课件依据：「从发电厂到插座，电能至少经历‘升压 → 降压 → 再降压’三次关键变换」。","o":["一次","两次","三次","四次"]},{"i":167,"c":7,"t":1,"s":"电压互感器本质上是一个特殊的“降压变压器”，它将高电压按比例变换后供给测量和保护系统使用，其二次输出的标准电压通常为（　）。","a":"D","e":"考查电压互感器二次额定电压。课件依据：「交变磁通同时切割匝数很少的二次绕组，二次线圈感应出交流电压，通常为标准 100V」。","o":["24V","36V","48V","100V"]},{"i":168,"c":7,"t":1,"s":"电流互感器基于电磁感应原理，将电力系统中数值巨大的一次侧电流按比例精确转换为标准的二次侧小电流，其常规二次额定电流为（　）。","a":"B","e":"考查电流互感器二次额定电流。课件依据：「将电力系统中数值巨大的一次侧电流，按比例精确地转换为数值较小的、标准的二次侧电流（通常为 5A 或 1A）」。","o":["2A或4A","5A或1A","1A或3A","10A或15A"]},{"i":169,"c":7,"t":1,"s":"并联接入变电站母线的并联电容器，就像一个随时为系统补充无功功率的“能量补给站”，其主要功能特性是（　）。","a":"C","e":"考查并联电容器的功能特性。课件依据：「并联接入变电站母线，实时补偿系统无功功率，提升功率因数，降低变压器及站内线路损耗，稳定母线电压」；A为串联电容器的功能。","o":["利用容抗补偿线路感抗，提升线路末端电压水平","作为高精度电容参考元件用于工频高压测量和介质损耗测试","实时补偿系统无功功率，提升功率因数，降低变压器及站内线路损耗，稳定母线电压","耦合传递高压电力线路的高频通信信号"]},{"i":170,"c":7,"t":1,"s":"关于氧化锌避雷器与碳化硅阀式避雷器，下列说法正确的是（　）。","a":"A","e":"考查避雷器类型的对比。课件依据：「氧化锌避雷器内部是氧化锌电阻片……无间隙、体积小、保护效果好，变电站、线路、配电几乎都在用」「碳化硅阀式避雷器……必须搭配火花间隙才能工作，性能差、漏电流大，现在电网已基本不再使用」。","o":["氧化锌避雷器无间隙、体积小、保护效果好，是变电站、线路、配电领域几乎都在用的型式","碳化硅阀式避雷器性能优异，是当前电网的主打产品","碳化硅阀式避雷器无需搭配火花间隙即可正常工作","氧化锌避雷器漏电流大，正逐步被碳化硅阀式避雷器替代"]},{"i":649,"c":7,"t":1,"s":"变压器的核心作用是（　）。","a":"B","e":"考查变压器的作用。课件依据：「变压器的核心作用：改变交流电电压，实现远距离输电、安全配电，是电网必备设备」，还能隔开高压电防止触电危险。","o":["改变交流电的频率以满足不同用户需求","改变交流电电压，实现远距离输电和安全配电","将交流电转换为直流电","在电网中长时间大量储存电能"]},{"i":655,"c":7,"t":1,"s":"关于电压互感器按绝缘介质的分类，下列说法正确的是（　）。","a":"A","e":"考查电压互感器按绝缘介质的分类特点。课件依据：油浸式PT「绝缘性能好，但存在漏油等维护问题，常用于中高压电力系统」；干式PT无油、维护简单，气体绝缘式采用六氟化硫，具有良好绝缘和灭弧性能，适用于高压和超高压系统。","o":["油浸式电压互感器绝缘性能好，但存在漏油等维护问题，常用于中高压电力系统","干式电压互感器工作时必须定期补充绝缘油","六氟化硫电压互感器以空气作为绝缘介质","气体绝缘式电压互感器只适用于0.4kV低压配电系统"]},{"i":661,"c":7,"t":1,"s":"在大型工厂、矿山、园区的高压配电系统中，电压互感器的主要用途是（　）。","a":"C","e":"考查工矿企业高压配电系统中PT的应用。课件依据：高压配电室的电压互感器「用于高压电机、配电变压器的电压监控、用电计量、故障保护，保障生产供电稳定」。","o":["为照明和办公生活负荷提供交流电源","代替继电保护装置直接切除短路故障","用于高压电机、配电变压器的电压监控、用电计量和故障保护","调节电网的系统频率"]},{"i":664,"c":7,"t":1,"s":"以浇注式为主、安装在高压开关柜和室内配电室的电流互感器属于（　）。","a":"D","e":"考查电流互感器按安装场所的分类。课件依据：户内型CT「浇注式为主，装在高压开关柜、室内配电室」；户外型以油浸、SF6气体绝缘为主，安装在室外构架、线路杆塔。","o":["户外型电流互感器","油浸式电流互感器","六氟化硫电流互感器","户内型电流互感器"]},{"i":672,"c":7,"t":1,"s":"可以不停电加装、常用于临时检测和老旧线路改造的电流互感器是（　）。","a":"D","e":"考查特殊用途电流互感器。课件依据：开合式电流互感器「不停电加装，多用于临时检测、老旧线路改造」；零序电流互感器则专门检测零序电流，用于漏电保护、接地故障保护。","o":["零序电流互感器","测量级电流互感器","保护级电流互感器","开合式电流互感器"]},{"i":676,"c":7,"t":1,"s":"谐波治理专用的电容器是（　）。","a":"B","e":"考查电容器的其他应用。课件依据：「滤波电容器（谐波治理专用）」；耦合电容器用于高频信号耦合，标准电容器用作高精度测量参考元件，断路器电容器用于均衡断口间电压分布。","o":["断路器电容器","滤波电容器","耦合电容器","标准电容器"]},{"i":677,"c":7,"t":1,"s":"安装在10kV电线杆上、用于保护配电变压器的避雷器类型是（　）。","a":"C","e":"考查避雷器按用途的分类。课件依据：「配电避雷器——10kV电线杆、配电变压器用」；线路型避雷器铁塔悬挂、保护输电导线，站用型避雷器保护变电站设备设施。","o":["线路型避雷器","站用型避雷器","配电避雷器","母线避雷器"]},{"i":171,"c":7,"t":2,"s":"关于变压器的分类，下列说法正确的有（　）。","a":"BCD","e":"考查变压器不同维度上的分类。课件列出的冷却方式有油浸自冷、油浸风冷、油浸水冷三种，故A错误；绝缘介质、绕组结构、调压方式三个维度的分类均出自课件。","o":["变压器的冷却方式只有油浸自冷一种","按绝缘介质可分为干式变压器、油浸式变压器和六氟化硫绝缘变压器","按绕组结构可分为双绕组变压器、三绕组变压器和自耦变压器","按调压方式可分为有载调压变压器和无载调压变压器"]},{"i":172,"c":7,"t":2,"s":"工业生产中各类变压器的典型应用，下列对应关系正确的有（　）。","a":"AC","e":"考查特种及专用变压器的应用对应。课件依据：「整流变压器……电解铝/铜、氯碱化工、高压直流输电系统、电镀及充电装置等」「电炉变压器……钢铁冶炼电弧炉、有色金属熔炼、金属热处理、感应加热设备等」；铁路与轨道交通是牵引变压器的应用场景。","o":["整流变压器——电解铝、氯碱化工、高压直流输电系统、电镀及充电装置等","医疗设备专用变压器——电气化铁路干线、高速动车组、城市轨道交通","电炉变压器——钢铁冶炼电弧炉、有色金属熔炼、金属热处理、感应加热设备等","试验变压器——金属热处理和城市轨道交通供电"]},{"i":173,"c":7,"t":2,"s":"关于电压互感器的应用场所，下列说法正确的有（　）。","a":"BCD","e":"考查PT的应用分布。课件依据：发电厂的电压互感器「安装在发电机出口、主变压器高低压侧、厂用母线上」，可见A错误；B、C、D分别对应变电站、高压开关柜和新能源电站的应用描述。","o":["出于绝缘配合考虑，发电厂发电机出口不允许安装电压互感器","110kV及以上高压、超高压线路/母线普遍使用电容式电压互感器（CVT），除电压变换外还可兼任电力载波通信耦合设备","10kV高压开关柜内配置单相浇注式PT、三相五柱式PT，多台组合使用","新能源电站并网侧装设电压互感器，完成并网检测、防孤岛保护、电能计量"]},{"i":174,"c":7,"t":2,"s":"关于电流互感器的作用与用途，下列说法正确的有（　）。","a":"ABCD","e":"本题为全选题，考查电流互感器的三大作用与特殊用途。课件依据：「将一次侧大电流按比例转换成标准小电流（常规二次额定电流：5A/1A）」「一、二次回路绝缘隔离……保障人身、设备安全」，另有降低二次回路阻抗保证信号稳定及零序电流互感器用途的说明。","o":["将一次侧大电流按比例转换成标准小电流，适配仪表、保护装置的量程","一、二次回路绝缘隔离，把高压强电系统和低压测控回路分开，保障人身、设备安全","精准传输测量计量信号和故障保护信号，并降低二次回路阻抗以保证信号传输稳定","零序电流互感器专门检测零序电流，用于漏电保护、接地故障保护"]},{"i":175,"c":7,"t":2,"s":"关于避雷器的安装位置与连接方式，下列说法正确的有（　）。","a":"ACD","e":"考查避雷器的装设位置与并联特性。课件依据：「主变压器避雷器紧靠变压器套管安装」及线路避雷器挂在横担靠近导线处的描述；避雷器是并联在电气设备/线路上的“安全泄压阀”，正常运行时不导电，串接限流的说法错误。","o":["母线避雷器安装在各电压等级母线（10kV、35kV、110kV、220kV、500kV）上","避雷器必须逐台串接在线路导线中间，作为限流元件长期通过负荷电流","主变压器避雷器紧靠变压器套管安装","输电线路避雷器挂在高压铁塔横担上、靠近导线位置，山区、雷击多发地段、易跳闸线路常加装"]},{"i":176,"c":7,"t":2,"s":"关于各类电容器在变电站中的功能特性，下列说法正确的有（　）。","a":"ABD","e":"考查几种电容器功能的区分。课件依据：并联电容器「实时补偿系统无功功率」，串联电容器「利用容抗补偿线路感抗」，断路器电容器「并联在超高压断路器断口两端，均衡断口间电压分布」；均衡断口电压是断路器电容器的功能，耦合电容器用于高频信号的耦合传输，故C错误。","o":["并联电容器接入变电站母线，实时补偿系统无功功率、提升功率因数","串联电容器串接于变电站出线端，利用容抗补偿线路感抗，减少长距离输电的电压降落","耦合电容器并联在超高压断路器断口两端，均衡断口间的电压分布","断路器电容器并联在超高压断路器断口两端，均衡断口电压分布、改善灭弧性能、提高分断能力"]},{"i":496,"c":7,"t":2,"s":"变压器“电磁感应”的工作过程可分解为环环相扣的三个步骤。下列属于这三个步骤的有（　）。","a":"ABC","e":"交变电流经原绕组“电生磁”产生交变磁场，磁场经铁芯“磁场传导”耦合到副绕组，再“磁生电”感应出电动势；静电感应、光电效应与变压器工作原理无关。","o":["电生磁","磁生电","磁场传导","静电感应","光电效应"]},{"i":652,"c":7,"t":2,"s":"课件按用途对变压器进行分类，下列属于其中类别的有（　）。","a":"ACDE","e":"考查变压器按用途的分类。课件将变压器分为电力变压器、仪用变压器、特种变压器、试验变压器四类；干式变压器是按绝缘介质划分的类型。","o":["电力变压器","干式变压器","仪用变压器","特种变压器","试验变压器"]},{"i":658,"c":7,"t":2,"s":"10kV高压开关柜中的电压互感器可用于（　）。","a":"ABDE","e":"考查高压开关柜内PT的用途。课件依据：「用途：母线电压监测、电量计量、柜内设备绝缘监察、接地故障保护」；直流操作电源并不是电压互感器提供的。","o":["母线电压监测","电量计量","向低压回路提供直流操作电源","柜内设备绝缘监察","接地故障保护"]},{"i":670,"c":7,"t":2,"s":"关于电容器在变电站中的作用，下列说法正确的有（　）。","a":"ABCE","e":"考查电容器的作用。课件依据：「1.无功补偿（核心作用）；2.提高功率因数；3.支撑母线电压，稳定设备运行；4.滤除谐波，保护站内电气设备」；电容器储存和释放电场能，不能持续提供有功功率。","o":["无功补偿是其核心作用","可以提高功率因数","支撑母线电压，稳定设备运行","能够持续向系统提供有功功率","可以滤除谐波，保护站内电气设备"]},{"i":177,"c":7,"t":3,"s":"变压器工作时，原边绕组和副边绕组之间存在电的直接接触。","a":"错","e":"考查变压器的能量传递方式。课件依据：「能量以磁场为媒介进行传递，原边和副边绕组之间没有电的直接接触，实现了电气隔离与能量的高效转换」。"},{"i":178,"c":7,"t":3,"s":"运行中的电流互感器二次侧不得开路，电压互感器二次侧严禁短路，且互感器二次侧应有一个端子接地。","a":"对","e":"考查互感器二次回路的运行硬性要求。笔记依据（重点整理-19班）：「电流互感器二次侧不得开路！电压互感器二次侧严禁短路！电流互感器和电压互感器二次侧有一端子必须接地（防止一、二次绝缘击穿，高压串入二次侧）」。"},{"i":667,"c":7,"t":3,"s":"电流互感器按绝缘介质划分，只有油浸式一种类型，不存在干式或六氟化硫电流互感器。","a":"错","e":"考查电流互感器按绝缘介质的分类。课件列出油浸式电流互感器、干式电流互感器和六氟化硫（SF6）电流互感器三种类型。"},{"i":674,"c":7,"t":3,"s":"并联电容器组投入运行会挤占变压器的供电容量，使变压器设备利用率下降。","a":"错","e":"考查并联电容器组的作用。课件依据：并联电容器组可「释放变压器供电容量，提升设备利用率」，其余作用还包括调节母线电压、降低电网有功损耗、改善功率因数。"},{"i":678,"c":7,"t":3,"s":"避雷器的安装位置包括主变压器、各电压等级进线间隔、母线、电容器组以及电缆终端、GIS组合电器等处。","a":"对","e":"考查避雷器的装设位置。课件依据：避雷器安装在「1.主变压器 2.各电压等级进线间隔 3.母线 4.电容器组 5.电缆终端、GIS组合电器」。"},{"i":179,"c":8,"t":1,"s":"当电路发生短路、过载等故障时，高压断路器能在多长时间内自动“跳闸”切断故障电流（　）。","a":"A","e":"考查断路器保护作用的动作速度。课件依据：「当电路发生短路、过载等故障时，它能在几十毫秒内自动‘跳闸’切断故障电流」，是守护电网安全的“防火墙”。","o":["几十毫秒内","几秒钟内","十几秒内","一分钟内"]},{"i":180,"c":8,"t":1,"s":"移开式（手车式）高压开关柜区别于固定式开关柜的显著特点是（　）。","a":"B","e":"考查开关柜按有无手车的分类。课件依据：「移开式（手车式）……断路器安装在可移动的手车上，可方便地整体拉出柜外，手车与柜体之间通过专用的机械联锁装置保证操作安全」；A为固定式的特征。","o":["断路器及其他所有电气元件均固定安装在柜体内部，接线方式相对固定","断路器安装在可移动的手车上，可方便地整体拉出柜外，手车与柜体之间通过专用的机械联锁装置保证操作安全","主回路封闭在充六氟化硫的气箱内，体积小","柜内各高压隔室全部采用绝缘隔板相互隔离"]},{"i":181,"c":8,"t":1,"s":"按灭弧介质分类，适用于72.5kV及以上高压、超高压输电网及大型枢纽变电站的断路器类型是（　）。","a":"C","e":"考查断路器按灭弧介质分类的适用场景。课件依据：SF6断路器「灭弧能力最强，适用于超高压/特大电流……适用场景：72.5kV及以上高压、超高压输电网，大型枢纽变电站核心设备」；真空断路器是中压领域的绝对主力。","o":["油绝缘断路器","真空断路器","六氟化硫断路器","空气断路器"]},{"i":182,"c":8,"t":1,"s":"关于隔离开关的性能特点，下列说法正确的是（　）。","a":"D","e":"考查隔离开关的本质特点。课件依据：「隔离开关……没有灭弧装置。它既不能断开正常负荷电流，更不能断开短路电流，否则即发生‘带负荷拉刀闸’的严重事故」。","o":["隔离开关装有简单灭弧装置，可以开断正常的负荷电流","隔离开关可以依靠串联熔断器来开断任意短路电流","隔离开关能够在数十毫秒内自动切除故障电流","隔离开关没有灭弧装置，既不能断开正常负荷电流，更不能断开短路电流"]},{"i":183,"c":8,"t":1,"s":"常见的GW4型隔离开关在操作机构动作时，力经主轴、拉杆等传动部件传递，带动支持绝缘子绕自身轴线旋转的角度是（　）。","a":"B","e":"考查GW4型隔离开关的工作原理。课件依据：「带动支持绝缘子绕自身轴线旋转 90°，使动静触头完成‘接触’（合闸）或‘分离’（分闸）」。","o":["45°","90°","135°","180°"]},{"i":184,"c":8,"t":1,"s":"高压开关柜是由断路器、负荷开关、隔离开关、互感器等组装而成的成套金属封闭配电装置，其额定电压范围和工频频率为（　）。","a":"A","e":"考查高压开关柜的基本参数。课件依据：「额定电压 3.6～40.5kV、工频 50Hz，用来接收、分配高压电能，实现电路的通断、控制、保护与监测，一般具备五防闭锁功能」。","o":["额定电压3.6～40.5kV、工频50Hz","额定电压0.4～10kV、工频50Hz","额定电压3.6～40.5kV、工频60Hz","额定电压72.5～550kV、工频50Hz"]},{"i":468,"c":8,"t":1,"s":"隔离开关按组成部分划分的五个组成部分是（　）。","a":"B","e":"隔离开关由开断导电部分、绝缘部分、传动机构、支持底座和操动机构五部分组成；A项是高压断路器的五大组成部分，注意区分两套部件清单。","o":["通断元件、中间传动机构、操动机构、绝缘支撑件、基座","开断导电部分、绝缘部分、传动机构、支持底座、操动机构","铁芯、绕组、绝缘结构、冷却系统、外壳","触头、导电杆、灭弧室、缓冲器、接线端子"]},{"i":576,"c":8,"t":1,"s":"10kV配电线路分支线和配电变压器最常用的一种短路保护开关是（　）。","a":"A","e":"考点：高压跌落式熔断器的应用定位。笔记依据：「高压跌落式熔断器：10kV配电线路分支线和配电变压器最常用的一种短路保护开关」。","o":["高压跌落式熔断器","真空断路器","SF6断路器","高压负荷开关"]},{"i":653,"c":8,"t":1,"s":"关于AIS断路器和GIS断路器，下列说法正确的是（　）。","a":"A","e":"考查断路器按结构形式的分类特点。课件依据：AIS断路器「瓷绝缘子实现相间、对地绝缘，占地面积大」，适用于变电站、高压电线杆上等户外场景；GIS断路器封装在接地金属筒内、靠筒内SF6气体绝缘、占地面积小，适用于市中心负荷变电站、地下／户内／楼宇变电站。","o":["AIS断路器以瓷绝缘子实现相间和对地绝缘，占地面积大","GIS断路器依靠筒内空气绝缘，占地面积比AIS断路器更大","GIS断路器适用于高压电线杆上等户外敞开场景","AIS断路器封装在接地金属筒内，适合地下变电站使用"]},{"i":656,"c":8,"t":1,"s":"GW4型隔离开关中，由连杆、拐臂、轴齿等组成，负责把操作力传递到动、静触头以实现分合闸动作的部分是（　）。","a":"B","e":"考查GW4型隔离开关的基本结构。课件依据：「传动部分：包含连杆、拐臂、轴齿等。负责将操作力传递到动静触头，实现分合闸动作」；导电部分则包括静触头、动触头、接线座。","o":["导电部分","传动部分","绝缘部分","底座部分"]},{"i":662,"c":8,"t":1,"s":"隔离开关按结构形式分类，除单柱式、双柱式外还包括（　）。","a":"C","e":"考查隔离开关按结构形式的分类。课件将隔离开关分为单柱式隔离开关、双柱式隔离开关、三柱式隔离开关三种结构形式。","o":["四柱式","立柱伸缩组合式","三柱式","移动小车式"]},{"i":668,"c":8,"t":1,"s":"按操动方式的不同，隔离开关可分为手动式隔离开关和（　）。","a":"A","e":"考查隔离开关按操动方式的分类。课件按操动方式将隔离开关分为手动式隔离开关和电动式隔离开关两类。","o":["电动式隔离开关","气动式隔离开关","液压式隔离开关","弹簧储能式隔离开关"]},{"i":673,"c":8,"t":1,"s":"关于GIS组合电器的安装与维护特点，下列说法正确的是（　）。","a":"C","e":"考查GIS组合电器的安装与维护特点。课件依据：「安装周期短：由于实现小型化，可在工厂内进行整机装配和试验合格后，以单元或间隔的形式运达现场」；同时GIS结构布局合理、检修周期长、维修工作量小、离地面低，日常维护方便。","o":["全部部件只能在现场逐一散装并试验，无法工厂化装配","检修周期极短，维修工作量很大","可在工厂内完成整机装配和试验后，以单元或间隔形式运达现场，缩短现场安装工期","设备离地面很高，日常维护十分不便"]},{"i":675,"c":8,"t":1,"s":"柜内主回路封闭在充六氟化硫的气箱内、体积小、适合狭小配电室使用的高压开关柜是（　）。","a":"B","e":"考查高压开关柜按绝缘介质的分类。课件依据：「主回路封闭在充六氟化硫的气箱内，体积小，即C-GIS充气柜，适合狭小配电室」；柜内主回路靠空气绝缘的开关柜最为普遍。","o":["空气绝缘高压开关柜","六氟化硫气体绝缘高压开关柜（C-GIS充气柜）","铠装式高压开关柜","移开式（手车式）高压开关柜"]},{"i":185,"c":8,"t":2,"s":"高压断路器的结构复杂且精密，下列关于其主要组成部分及作用的说法正确的有（　）。","a":"ABCD","e":"本题为全选题，考查断路器四大结构。课件依据：「主要由灭弧部分、绝缘部分、操作机构部分和导流部分组成」，并对各部分的功能和示例作了说明。","o":["灭弧部分用于熄灭电弧，SF6断路器以SF6气体为灭弧介质","绝缘部分用于隔离带电部分与接地部分，如SF6断路器的陶瓷绝缘子","操作机构部分实现断路器的分闸和合闸操作，如SF6断路器的弹簧操作机构","导流部分用于传导电流，确保电流能够顺畅地通过断路器"]},{"i":186,"c":8,"t":2,"s":"关于隔离开关的作用，下列说法正确的有（　）。","a":"ABC","e":"考查隔离开关的三大作用。课件依据：「(1)隔离电源……(2)倒换线路或母线……(3)关合与开断小电流电路」；隔离开关无灭弧装置，不能断开短路电流，切断短路电流应由断路器完成。","o":["隔离电源，在带电区域和检修区域之间形成明显的断开点","倒换线路或母线，按运行需求进行倒闸操作","可以关合与开断小电流电路","快速切断短路电流并可靠熄灭强烈电弧"]},{"i":187,"c":8,"t":2,"s":"关于GIS组合电器的特点，下列说法正确的有（　）。","a":"BCD","e":"考查GIS组合电器的特点。课件依据：「小型化……大幅度缩小变电站的体积」「可靠性高……优良的抗地震性能」「安全性好……没有触电的危险……无火灾危险」；GIS靠金属壳体对电磁和静电实现屏蔽、抗无线电干扰能力强，故A错误。","o":["带电部分裸露在空气中，易受灰尘雨雪影响，抗无线电干扰能力弱","采用绝缘性能卓越的SF6做绝缘和灭弧介质，能大幅度缩小变电站体积，实现小型化","带电部分全部密封于惰性气体中，可靠性高，具有优良的抗地震性能","带电部分密封于接地的金属壳体内，没有触电危险，且SF6为非燃烧气体，无火灾危险"]},{"i":188,"c":8,"t":2,"s":"关于GIS组合电器的分类，下列说法正确的有（　）。","a":"ABD","e":"考查GIS的分类与气室划分。课件依据：「110kV电压等级普遍采用三相共桶式」「220kV及以上电压等级普遍采用单相单桶式」，故C颠倒；「按SF6气体压力分成气压高的断路器室，稍低压力的隔离开关、PT室、BL室、母线等」。","o":["按布置形式分为户内式GIS组合电器和户外式GIS组合电器","110kV电压等级普遍采用三相共桶式","220kV及以上电压等级普遍采用三相共桶式","按SF6气体压力要求不同分为若干气室，包括气压高的断路器室和压力稍低的隔离开关室、PT室、BL室、母线等"]},{"i":189,"c":8,"t":2,"s":"关于高压开关柜的各种类型，下列说法正确的有（　）。","a":"ABC","e":"考查开关柜的多种分类方式。课件依据：「各高压隔室……全部用金属隔板相互隔离，安全性最高，最常用」及对间隔式、箱式的说明；手车式恰以断路器装在可移动手车上并能整体拉出为特征，D张冠李戴。","o":["铠装式高压开关柜各高压隔室（断路器室、母线室、电缆室、二次室）全部用金属隔板相互隔离，安全性最高，最常用","间隔式高压开关柜部分隔室采用金属隔板、部分采用绝缘隔板，隔离等级低于铠装，属老型号，很少用","箱式高压开关柜柜体为整体箱体、内部没有完整分隔，结构简单造价低，多用于环网配电、小区配电室","移开式（手车式）高压开关柜的所有电气元件均固定安装在柜体内部，没有任何可移动部件"]},{"i":190,"c":8,"t":2,"s":"“五防”闭锁是高压开关柜的一般功能要求，下列各项属于“五防”内容的有（　）。","a":"ABDE","e":"考查开关柜“五防”闭锁的具体条目。课件依据：高压开关柜「一般具备五防闭锁功能」；课堂笔记整理的五防包括防误分误合断路器、防带负荷分合隔离开关、防带电挂接地线、防带地线送电、防误入带电间隔，不含“防止过电压”。","o":["防止误分、误合断路器","防止带负荷分、合隔离开关","防止过电压","防止带电挂（合）接地线（接地开关）","防止误入带电间隔"]},{"i":485,"c":8,"t":2,"s":"下列属于高压开关柜作用的有（　）。","a":"ABC","e":"高压开关柜集控制、保护、隔离等功能于一体，用于接收和分配高压电能；改变电压等级是变压器的功能，不属于开关柜的作用。","o":["控制：接通和断开电路","保护：故障时自动跳闸","隔离：形成明显断口，保障检修安全","变压：改变电压等级"]},{"i":659,"c":8,"t":2,"s":"GIS组合电器是把若干元件组合封闭在接地的金属壳体内、充以一定压力SF6气体作为绝缘介质的成套开关设备。下列属于其组合封闭元件的有（　）。","a":"ACDE","e":"考查GIS组合电器内部的组合元件。课件依据：GIS「将断路器、隔离开关、接地开关、电流互感器、电压互感器、避雷器、母线、进出线套管或电缆终端等元件组合封闭在接地的金属壳体内」；主变压器不属于其组合元件。","o":["断路器、隔离开关、接地开关","主变压器","电流互感器、电压互感器","避雷器、母线","进出线套管或电缆终端"]},{"i":671,"c":8,"t":2,"s":"高压开关柜按柜内元件及功能配置可分为多种柜型，下列属于课件所列柜型的有（　）。","a":"ABCD","e":"考查高压开关柜按功能的分类。课件依据：包括「进线柜：电源引入，配置断路器、保护」，以及出线柜、母联柜、PT柜、计量柜、避雷器柜、电容器柜等；整流柜不在其列。","o":["进线柜","母联柜","计量柜","电容器柜","整流柜"]},{"i":191,"c":8,"t":3,"s":"真空断路器体积小、灭弧能力强，因此是72.5kV及以上高压、超高压输电网的核心设备。","a":"错","e":"考查灭弧介质与适用电压等级的对应。课件依据：真空断路器「灭弧能力强、体积小，是中压领域的绝对主力」，适用场景为10kV～40.5kV中压配电网；72.5kV及以上高压、超高压输电网以SF6断路器为核心设备。"},{"i":192,"c":8,"t":3,"s":"高压断路器可以带负荷操作，而隔离开关没有灭弧装置，严禁带负荷拉合。","a":"对","e":"考查断路器与隔离开关操作能力的根本区别。课件依据：断路器是「用来接通或切断高压电路」的控制与保护设备；隔离开关「既不能断开正常负荷电流，更不能断开短路电流」，否则发生“带负荷拉刀闸”严重事故。"},{"i":460,"c":8,"t":3,"s":"开关电器灭弧的基本手段包括冷却电弧、拉长电弧和吹散带电离子。","a":"对","e":"考点：灭弧的基本方法。依据：「灭弧＝冷却＋拉长电弧＋吹散离子」，旨在加强去游离从而熄灭电弧。"},{"i":489,"c":8,"t":3,"s":"GIS组合电器是依靠空气绝缘的敞开式开关设备。（　）","a":"错","e":"GIS是将断路器、隔离开关、互感器、避雷器等元件封闭在接地金属壳体内、充入SF6气体作为绝缘介质的气体绝缘金属封闭开关设备；依靠空气绝缘的敞开式设备是AIS。"},{"i":622,"c":8,"t":3,"s":"按结构形式分类，高压断路器可分为空气绝缘敞开式（AIS）断路器和气体绝缘金属封闭（GIS）断路器两大类。","a":"对","e":"考点：断路器按结构形式的分类。笔记依据：「按结构形式分：AIS断路器（空气绝缘敞开式）、GIS断路器（气体绝缘金属封闭）」。"},{"i":650,"c":8,"t":3,"s":"真空断路器灭弧能力弱、体积庞大，目前正在被油绝缘断路器逐步取代。","a":"错","e":"考查断路器按灭弧介质分类的现状。课件依据：油绝缘断路器「维护繁琐且不环保，现已基本被淘汰」，仅在少数老旧电站可见；真空断路器恰恰灭弧能力强、体积小，是中压领域的绝对主力。"},{"i":665,"c":8,"t":3,"s":"按照安装场所的不同，隔离开关可分为户内式隔离开关和户外式隔离开关。","a":"对","e":"考查隔离开关按安装场所的分类。课件将隔离开关分为户内式隔离开关和户外式隔离开关两类。"},{"i":193,"c":9,"t":1,"s":"我国电力系统的标准额定频率是多少？该参数能否保持稳定对电网运行至关重要，其变化还直接反映系统有功功率的平衡状况。","a":"B","e":"考点：电力系统基本特征之频率。课件依据：「频率是交流电振荡频率，不同国家标准不同，我国为50Hz，频率稳定对电网运行至关重要，反映有功功率平衡。」","o":["40Hz","50Hz","60Hz","100Hz"]},{"i":194,"c":9,"t":1,"s":"在输送功率一定的条件下，电网对远距离大容量输电采用超高压等级，主要原因是什么？","a":"A","e":"考点：为什么需要超高压输电。课件依据：「在输电功率不变的情况下，输电电压越高，输电电流越小，电能的损耗越小」；超高压输电可显著减少线路损耗并提升远距离大容量输电的经济性。","o":["电压越高则输电电流越小，能显著减少线路损耗，提升远距离输电的经济性","电压越高则导线允许通过的载流量越大，可以选用更细的导线","电压越高则线路走廊越窄，可减少占地和拆迁费用","电压越高则用户端的功率因数越高，无功需求越少"]},{"i":195,"c":9,"t":1,"s":"分裂导线能够增大导线的等效半径、减小电晕，且电压等级越高通常采用的分裂数越多。按此配置原则，500kV超高压输电线路通常采用的导线分裂形式是？","a":"C","e":"考点：电压等级与分裂导线数的对应。课件依据：双分裂导线适用于220kV、四分裂导线适用于500kV、八分裂导线适用于1000kV，单导线多用于110kV及以下。","o":["单导线","双分裂导线","四分裂导线","八分裂导线"]},{"i":196,"c":9,"t":1,"s":"下列不属于架空地线（避雷线）核心功能的是？","a":"D","e":"考点：架空地线的功能范围。课件依据：架空地线具有防雷击、分流、耦合、屏蔽及通信（OPGW）等功能，架设于导线上方用于防雷保护，并不承担负荷电流的输送任务。","o":["防止导线遭受直接雷击，引导雷电流安全进入大地","当杆塔遭受雷击时分流雷电流，有效降低塔顶电位","通过与导线的耦合作用及屏蔽效应，降低线路绝缘子电压和导线感应过电压","承担线路的正常负荷电流，把电能从电源侧输送至负荷侧"]},{"i":197,"c":9,"t":1,"s":"由铝绞线和钢芯组合而成，兼具较高机械强度和良好导电性能、在高压输电线路中广泛应用的导线是？","a":"C","e":"考点：导地线的种类与特点。课件依据：钢芯铝绞线由铝绞线和钢芯线组成，「较高的强度和良好的导电性能，在高压输电线路中广泛应用」。","o":["铜绞线","镀锌钢绞线","钢芯铝绞线","铝合金绞线"]},{"i":198,"c":9,"t":1,"s":"玻璃绝缘子在运行中无须进行“零值”检测，是因为其具有哪一特性？","a":"B","e":"考点：玻璃绝缘子的“零值自爆”特性。课件依据：「表面处于压缩预应力状态，如发生裂纹和电击穿，玻璃绝缘子将自行破成碎块，俗称‘自爆’」，因此运行中无须进行零值检测。","o":["绝缘件表面覆盖瓷釉，绝缘裕度极大，不会出现零值绝缘子","表面处于压缩预应力状态，发生裂纹或电击穿时会自行破碎成小碎块（俗称“自爆”），零值缺陷直观可见","芯棒采用玻璃纤维树脂材料，机械强度极高，永不劣化","内部充有SF6气体，可以对绝缘状态实现在线监测"]},{"i":199,"c":9,"t":1,"s":"用于将导线固定于耐张段的金具是？","a":"A","e":"考点：金具的类型与功能。课件依据：「耐张线夹：固定导线于耐张段」「悬垂线夹：连接导线与绝缘子」「接续金具：导线之间的连接」「保护金具：减振、防闪络、防腐蚀」。","o":["耐张线夹","悬垂线夹","接续金具","保护金具"]},{"i":200,"c":9,"t":1,"s":"输电设备的缺陷分为紧急缺陷、重大缺陷、一般缺陷和其他四类，其中紧急缺陷的处理时限是多长时间以内？","a":"A","e":"考点：缺陷分级与处理时限。19班重点整理明确：「输电线路缺陷类型：紧急（24h）、重大（7天）、一般（3个月）、其他」。","o":["24小时","72小时","7天","3个月"]},{"i":201,"c":9,"t":1,"s":"线路跳闸后，重合闸装置根本不动作，据此通常可以作出的判断是？","a":"B","e":"考点：重合闸动作情况的故障判别。课件依据：「重合闸动作情况分为重合成功、重合不成功和重合闸不动作」「重合闸不动作说明是三相短路或重合闸自身故障」。","o":["发生了雷击、鸟害等瞬时性故障，重合必然成功","发生了三相短路故障，或者重合闸装置自身存在故障","故障点一定位于本线路首端，距离保护Ⅰ段必然动作","线路并未真正发生故障，属于误发信号"]},{"i":202,"c":9,"t":1,"s":"输电线路停电检修的基本流程中，最先执行的环节是？","a":"D","e":"考点：停电检修的基本流程。课件依据：「工作许可→现场工前会→开始作业→工作结束→清理作业现场→现场工后会→撤离作业现场→办理工作终结」。","o":["办理工作终结","召开现场工后会","撤离作业现场","取得工作许可"]},{"i":417,"c":9,"t":1,"s":"架空输电线路跳闸后，重合闸成功率通常较高的故障类型是（　）。","a":"C","e":"考点：不同故障诱因的重合闸成功率差异。依据：「鸟害、雷击重合成功率较高」，而山火引起的跳闸重合成功率不高。","o":["山火","覆冰","鸟害、雷击","吊车碰线"]},{"i":519,"c":9,"t":1,"s":"架空输电线路中，绝缘子的核心作用是（　）","a":"D","e":"绝缘子的核心作用是使带电部分与杆塔（大地）之间保持绝缘、防止闪络；“连接导线与杆塔”主要由金具完成，“将雷电流引入大地”则是接地装置的功能。","o":["将雷电流引入大地","连接导线与杆塔","承担机械张力","使导线等带电部分与杆塔（大地）之间绝缘并防止闪络"]},{"i":520,"c":9,"t":1,"s":"下列架空输电线路部件与其主要功能的对应关系，正确的是（　）","a":"A","e":"杆塔用于支承导线和避雷线并保持安全距离；接地装置负责泄放雷电流，绝缘子负责绝缘，固定导线于耐张段的是耐张线夹（金具），防污闪靠绝缘子防污措施实现。","o":["杆塔——支承导线和避雷线，保持其对地和相间的安全距离","接地装置——将导线固定于耐张段","绝缘子——确保雷电流可靠泄入大地","金具——防止绝缘子串发生污秽闪络"]},{"i":524,"c":9,"t":1,"s":"下列输电线路故障中，属于永久性故障的是（　）","a":"D","e":"雷击闪络、鸟粪闪络、树竹放电等多为瞬时性故障，重合闸通常能成功；倒杆、断线、掉串等永久性故障只能靠抢修恢复，重合闸难以奏效。","o":["雷击闪络","鸟粪闪络","树竹对线放电","倒杆、断线、掉串"]},{"i":525,"c":9,"t":1,"s":"下列情形中，属于外力破坏的是（　）","a":"C","e":"大型车辆碰线等由人为活动造成的破坏属于外力破坏；污秽、覆冰、舞动分别属于积污和恶劣气象引发的线路故障。","o":["绝缘子污秽","导线覆冰","大型车辆碰线","导线舞动"]},{"i":526,"c":9,"t":1,"s":"瓷质绝缘子运行超过（　）年，应开展零值检测","a":"C","e":"瓷质绝缘子运行超过20年应开展零值检测，年均劣化率大于0.02%时应进行更换；玻璃绝缘子具有自爆特性，运行中无须零值检测。","o":["10","15","20","25"]},{"i":529,"c":9,"t":1,"s":"当土壤电阻率不超过100Ω·m时，输电线路杆塔的工频接地电阻不应大于（　）Ω","a":"B","e":"土壤电阻率不超过100Ω·m的地区，杆塔工频接地电阻要求不大于10Ω；土壤电阻率越高，允许的接地电阻限值相应放宽。","o":["5","10","15","30"]},{"i":530,"c":9,"t":1,"s":"输电线路的接地电阻由散流电阻、引下线电阻以及（　）组成","a":"A","e":"接地电阻是散流电阻、引下线电阻与接触电阻之和，三者共同决定雷电流泄放入地的效果。","o":["接触电阻","交流电阻","冲击电阻","容抗"]},{"i":558,"c":9,"t":1,"s":"对沿线路架设有避雷线且多基杆塔相互连接的情况，测量杆塔接地电阻宜采用的方法是（　）。","a":"D","e":"考点：接地电阻测量方法的适用场合。笔记依据：「接地电阻测量（三极法—接地装置、电流极和电压极；钳表法—有避雷线且多基杆塔）」。","o":["三极法","电流电压表法","红外测温法","钳表法"]},{"i":559,"c":9,"t":1,"s":"为减少电流电压不对称、限制对通信的影响，架空线路长度超过（　）时应采用换位杆塔进行导线换位。","a":"B","e":"考点：换位杆塔的应用条件。笔记依据：「换位塔：10km以上线路要用换位杆进行导线换位，减少电流电压不对称，限制对通信影响」。","o":["5km","10km","20km","50km"]},{"i":560,"c":9,"t":1,"s":"架空输电线路中，接地电阻由（　）三部分组成。","a":"A","e":"考点：接地电阻的构成。笔记依据：「接地装置＝接地体＋接地引下线；接地电阻＝散流电阻＋引下线电阻＋接触电阻」。","o":["散流电阻、引下线电阻和接触电阻","散流电阻、绝缘电阻和过渡电阻","接地体电阻、大地电阻和土壤电阻","工频电阻、冲击电阻和残留电阻"]},{"i":203,"c":9,"t":2,"s":"下列属于架空输电线路组成部分的有？","a":"ABCD","e":"考点：输电线路的组成与功能。课件依据：「输电线路组成部分及功能（导线、地线、绝缘子、杆塔、金具、基础、接地装置）」，高压断路器属于变电一次设备而非线路本体部件。","o":["导线","避雷线（架空地线）","绝缘子","杆塔","高压断路器"]},{"i":204,"c":9,"t":2,"s":"架空地线的核心功能包括？","a":"ABCE","e":"考点：架空地线的功能。课件依据：「1防止雷击 2分流作用 3耦合作用 4屏蔽效应 5通信功能（光纤复合架空地线OPGW承担通信任务）」，架空地线不起增大载流量的作用。","o":["防止导线受到直接雷击，吸引雷电并将其安全引入大地","当杆塔遭受雷击时分流雷电流，有效降低塔顶电位","通过导线与地线之间的相互耦合，降低线路绝缘子的电压","增大导线的载流量，提高线路的输送容量","发挥屏蔽效应，降低导线上的感应过电压"]},{"i":205,"c":9,"t":2,"s":"输电业务主要由哪些部分组成？","a":"BCD","e":"考点：输电业务的组成。课件依据：「输电业务主要由电网规划与设计、输电线路建设、电力传输运行管理、线路维护与管理、技术研究与创新等组成」，电费抄核收不属于输电业务。","o":["电费抄核收与用电稽查","电网规划与设计","输电线路建设","电力传输运行管理"]},{"i":206,"c":9,"t":2,"s":"关于杆塔按功能结构分类及其用途，下列对应正确的有？","a":"AB","e":"考点：杆塔按功能结构的分类。课件依据：「直线塔用于线路直线段；耐张塔用于导线转角、终端、跨越位置；转角塔用于线路方向改变处；终端塔连接变电站或引线段」。","o":["直线塔——用于线路直线段","转角塔——用于线路方向改变处","终端塔——设置于档距中央，用于导线防振","耐张塔——仅用于接续避雷线的接头"]},{"i":207,"c":9,"t":2,"s":"输电线路金具按用途分类主要包括？","a":"BCDE","e":"考点：金具的主要类型。课件依据：金具主要有悬垂线夹、耐张线夹、连接金具、保护金具、接续金具，分别承担连接、固定、保护、防振及接续等功能，高压熔断器不属于金具。","o":["高压熔断器","悬垂线夹","耐张线夹","接续金具","保护金具"]},{"i":208,"c":9,"t":2,"s":"架空输电线路的导地线按材料和结构主要分为哪三类？","a":"ABD","e":"考点：导地线的分类。课件依据：导地线分为金属导地线（镀锌/镀铜钢丝，强度高防腐好）、钢芯铝绞线（强度高导电好，高压常用）、复合导地线（轻质耐腐蚀，适用于海边、沙漠等恶劣环境）三类。","o":["镀锌钢丝（镀铜钢丝）等金属导地线","钢芯铝绞线","聚氯乙烯绝缘电线","复合导地线"]},{"i":209,"c":9,"t":2,"s":"输电线路的巡视方式包括？","a":"ABD","e":"考点：巡视的方式与方法。19班重点整理明确巡视方式为人工、无人机、在线监测；在线监测通过传感器、摄像头等对线路运行状态和环境变化进行实时、持续的监控检查，带电水冲洗不属于巡视方式。","o":["人工巡视","无人机巡视","带电水冲洗绝缘子","在线监测巡视"]},{"i":210,"c":9,"t":2,"s":"输电线路的预试定检（预防性试验）主要包括哪些项目？","a":"ACDE","e":"考点：预试定检的内容。19班重点整理明确：「预试定检包括红外测温、接地电阻测量、绝缘子检测、污秽检测」，绕组直流电阻测量属于变压器类试验项目。","o":["红外测温","绕组直流电阻测量","接地电阻测量","绝缘子检测","污秽检测"]},{"i":211,"c":9,"t":2,"s":"导地线因长期暴露于自然环境出现断股、损伤后，常用的检修修补方法包括？","a":"ABDE","e":"考点：导地线断股损伤的修补方法。课件依据：「导地线断股、损伤检修的常用方法：修光棱角、毛刺，缠绕补强法，预绞丝补修法，补修管补修法等」，具体选择应按运行规程附录A执行。","o":["修光棱角、毛刺","缠绕补强法","拆除原导线并更换更大截面的导线","预绞丝补修法","补修管补修法"]},{"i":212,"c":9,"t":2,"s":"关于输电线路工程验收，下列说法正确的有？","a":"AB","e":"考点：验收阶段的划分与要求。课件依据：「隐蔽工程验收是对覆盖前看不见部分的查验记录并确保合格消缺的过程」「竣工验收是对输电线路投运前质量的最终确认」；接地工程属隐蔽工程，验收以查看资料为主、现场检查为辅，竣工档案资料同样需要验收移交。","o":["竣工验收是对输电线路投运前工程质量的最终确认，也是线路工程投产的最基本要求","对将被覆盖后看不见的隐蔽实物部分，应在覆盖前完成查验记录并确保合格消缺","接地工程验收时应将全线杆塔的接地体全部开挖检查","竣工档案资料不属于工程验收范围，无需验收移交"]},{"i":425,"c":9,"t":2,"s":"课堂上特别提示的大电网典型故障诱因中，容易导致大范围跳闸且短时间内难以恢复的两种是（　）。","a":"AB","e":"考点：大电网典型故障诱因。依据：「大电网典型故障诱因（特别提到的两个）：覆冰、山火，容易导致大范围跳闸，且短时间难以恢复」。","o":["覆冰","山火","杆塔倾斜","绝缘子积污"]},{"i":433,"c":9,"t":2,"s":"架空输电线路的绝缘子按材料划分，主要包括（　）。","a":"ACD","e":"考点：绝缘子按材料的分类。依据：「绝缘子按材料＝瓷、玻璃、复合」，并无木质绝缘子这一类别。","o":["瓷质绝缘子","木质绝缘子","玻璃绝缘子","复合绝缘子"]},{"i":521,"c":9,"t":2,"s":"按介质材料分类，架空输电线路的绝缘子可分为（　）","a":"ABC","e":"按介质材料绝缘子分为瓷质、玻璃、复合三类；悬式、支柱是按结构形式划分的类别，不是材料分类。","o":["瓷质绝缘子","玻璃绝缘子","复合绝缘子","悬式绝缘子","支柱绝缘子"]},{"i":523,"c":9,"t":2,"s":"输电线路巡视的类型包括（　）","a":"ACD","e":"输电线路巡视类型分为正常巡视、故障巡视、特殊巡视三类；夜间巡视只是特殊巡视的一种具体形式，不作为独立类型。","o":["正常巡视","夜间巡视","故障巡视","特殊巡视"]},{"i":591,"c":9,"t":2,"s":"下列属于杆塔基础类型的有哪些？","a":"ACDE","e":"考点：杆塔基础的类型列举。笔记依据：「类型：现场浇制、预制钢筋混凝土、金属、灌注桩式、岩石基础」；“木桩基础”不在其中。","o":["现场浇制基础","木桩基础","预制钢筋混凝土基础","金属基础","灌注桩式、岩石基础"]},{"i":592,"c":9,"t":2,"s":"输电线路巡视的目的包括下列各项中的（　）。","a":"ABDE","e":"考点：输电线路巡视的目的。笔记依据：「巡视目的：及时掌握线路的运行状况、及时发现设备缺陷和威胁线路安全的问题、及时找出故障点和故障类型，预防事故发生」。","o":["及时掌握线路的运行状况","及时发现设备缺陷和威胁线路安全的问题","对线路运维班组的绩效进行考核排名","及时找出故障点和故障类型","预防事故发生"]},{"i":593,"c":9,"t":2,"s":"按课程口径，输电线路的巡视类型包括（　）。","a":"ABC","e":"考点：输电线路巡视类型的构成。笔记依据：「巡视类型：正常（定期全面查）、故障（事故后追因）、特殊（按需专项检）」；夜间巡视属电缆线路巡视类型，勿混淆。","o":["正常巡视（定期全面查）","故障巡视（事故后追因）","特殊巡视（按需专项检）","夜间巡视"]},{"i":213,"c":9,"t":3,"s":"输电线路故障跳闸中，一般以单相跳闸较多，两相、三相跳闸相对较少。","a":"对","e":"考点：线路跳闸的总体规律。课件依据：「跳闸情况分别以单相、两相、三相出现，一般以单相跳闸较多，两相、三相跳闸相对较少」。"},{"i":214,"c":9,"t":3,"s":"复合绝缘子的抗老化能力优于瓷质绝缘子和玻璃绝缘子。","a":"错","e":"考点：复合绝缘子的特点。课件依据：复合绝缘子尺寸小、重量轻、抗拉强度高、抗污秽闪络性能优良，「但抗老化能力不如瓷和玻璃绝缘子」。"},{"i":215,"c":9,"t":3,"s":"山火引起的线路跳闸，重合闸成功率不高，或出现重合闸成功后再次跳闸的情况。","a":"对","e":"考点：山火故障的特征。课件依据：「重合闸成功率不高（重点），或是重合闸成功后再次跳闸」；山火烟尘中夹有导电物质，容易造成单相接地或相间放电。"},{"i":216,"c":9,"t":3,"s":"杆塔基础的主要作用是防止绝缘子串发生污秽闪络。","a":"错","e":"考点：杆塔基础的作用。课件依据：「杆塔基础是指建筑在土壤里的杆塔地下部分，其作用是稳定杆塔，防止杆塔因受垂直、水平及事故荷重等而产生的上拔、下压甚至倾倒」，防污闪是绝缘子方面的要求。"},{"i":217,"c":9,"t":3,"s":"接地装置是接地体与接地引下线的总称，其作用包括确保雷电流可靠泄入大地、减少线路雷击跳闸率和避免跨步电压产生的人身伤害。","a":"对","e":"考点：接地装置的构成与作用。课件依据：「接地装置是接地体与接地引下线的总称……确保雷电流可靠泄入大地，保护线路设备绝缘，减少线路雷击跳闸率……避免跨步电压产生的人身伤害」。"},{"i":457,"c":9,"t":3,"s":"架空输电线路的巡视类型分为正常巡视、故障巡视和特殊巡视三类。","a":"对","e":"考点：输电线路巡视类型的划分。依据：「巡视类型＝正常、故障、特殊」，特殊巡视多在异常天气、特殊时段或特殊区段开展。"},{"i":458,"c":9,"t":3,"s":"线路跳闸后重合闸重合不成功、试送电也不成功的，一般为永久性故障；重合成功者多为瞬时性故障。","a":"对","e":"考点：重合闸结果对故障性质的研判。依据：「重合成功→多为瞬时性故障；重合不成功＋试送不成功→多为永久故障」。"},{"i":459,"c":9,"t":3,"s":"零序保护动作通常表明线路发生了单相接地故障。","a":"对","e":"考点：零序保护动作与故障类型的对应。依据：「零序保护动作→单相接地」，零序分量来源于不对称接地故障。"},{"i":522,"c":9,"t":3,"s":"输电线路杆塔基础中，“地脚螺栓式基础”属于按施工特点划分的基础类型。","a":"错","e":"地脚螺栓式基础是按基础与杆塔连接方式划分的类型；按施工特点划分的主要有现浇基础、装配式基础等。"},{"i":527,"c":9,"t":3,"s":"输电线路鸟害故障多发于22时至次日8时。","a":"对","e":"鸟类夜间活动集中，鸟害故障多发时段为22:00～08:00，可据此在夜间至凌晨加强防护与特巡。"},{"i":528,"c":9,"t":3,"s":"导线舞动多发于每年11月至次年3月，多发生在风速约5m/s、气温0℃以下的环境中。","a":"对","e":"导线舞动多发于每年11月至次年3月的冬春大风季节，常出现在风速约5m/s、气温0℃以下的环境。"},{"i":531,"c":9,"t":3,"s":"输电线路发生故障跳闸后，无论重合闸是否成功，都应及时组织故障巡视。","a":"对","e":"线路故障后应及时组织故障巡视，重合成功也须查明故障原因，重合不成功更需尽快找到故障点。"},{"i":532,"c":9,"t":3,"s":"为缩短停役等待时间，雷雨天气也可以进行杆塔接地电阻的测量工作。","a":"错","e":"雷雨天气杆塔存在雷击危险，严禁开展杆塔接地电阻测量等作业，应待天气好转后再测。"},{"i":218,"c":10,"t":1,"s":"电力系统必须在任何时刻保持发电功率总和精确等于负荷功率总和加上传输和转换过程中的损耗功率，这一要求体现的电力系统最根本的基本特征是？","a":"B","e":"实时平衡性是电力系统最根本、最重要的特征。课件依据：「在任何时刻，系统的发电功率总和必须精确等于负荷功率总和加上传输和转换过程中的损耗功率。」","o":["高度复杂性","实时平衡性","非线性","时变性"]},{"i":219,"c":10,"t":1,"s":"按照课件对电力电缆按电压等级的分类，额定电压为21/35kV的电缆属于？","a":"D","e":"按电压等级电缆分四类：低压1kV以下（如0.6/1kV），中压1kV～35kV（如8.7/10kV、21/35kV），高压66kV～220kV（如64/110kV、127/220kV），超高压330kV及以上。","o":["低压电缆","高压电缆","超高压电缆","中压电缆"]},{"i":220,"c":10,"t":1,"s":"下列绝缘材料中，属于热固性挤包绝缘材料的是？","a":"A","e":"挤包绝缘电缆以热塑性或热固性材料挤包形成绝缘：热塑性材料有PVC、PE、PP，热固性材料有XLPE和乙丙橡胶（EPR）。","o":["交联聚乙烯（XLPE）","聚氯乙烯（PVC）","聚丙烯（PP）","聚乙烯（PE）"]},{"i":221,"c":10,"t":1,"s":"关于挤包绝缘材料的长期工作温度，下列说法正确的是？","a":"C","e":"课件依据：热塑性材料（PVC、PE、PP）长期工作温度不超过70℃，热固性材料（XLPE、EPR）长期工作温度不超过90℃。","o":["热塑性材料长期工作温度不超过90℃","热固性材料长期工作温度不超过70℃","热塑性材料长期工作温度不超过70℃","各类挤包绝缘材料长期工作温度均不超过105℃"]},{"i":222,"c":10,"t":1,"s":"复习重点特别强调，中高压电力电缆必备的“三层共挤结构”是指？","a":"A","e":"笔记强调中高压电缆必有三层共挤结构「导体屏蔽、绝缘层、绝缘屏蔽」；石墨层并不是电力电缆的关键结构。","o":["导体屏蔽、绝缘层、绝缘屏蔽","导体屏蔽、金属屏蔽、金属护套","绝缘层、缓冲带、外护套","导体屏蔽、绝缘屏蔽、铠装层"]},{"i":223,"c":10,"t":1,"s":"电缆额定电压常用U0/U表示，其中U0指的是？","a":"C","e":"课件依据：「U0指电缆导体对金属屏蔽之间的额定工频电压，即相电压；U指电缆任意两相导体之间的额定工频电压，即线电压。」","o":["电缆任意两相导体之间的额定工频电压，即线电压","电缆导体对接地装置之间的耐受电压","电缆导体对金属屏蔽之间的额定工频电压，即相电压","电缆在系统中允许的最高运行电压"]},{"i":224,"c":10,"t":1,"s":"关于交联聚乙烯（XLPE）电缆的特点，下列说法正确的是？","a":"C","e":"XLPE电缆电气性能良好，正逐步取代油纸绝缘电缆，是目前应用最广泛的电缆；生产无需交联、退役后可回收是乙丙橡胶（EPR）电缆的特点。","o":["生产过程无需交联，工艺简单","退役后绝缘层易于回收再利用，符合“双碳”目标","长期运行温度可达90℃，短时可耐受250℃（不超过5秒）","低温冲击性能优异且导热能力强"]},{"i":225,"c":10,"t":1,"s":"以六氟化硫（SF6）气体为外绝缘、安装在气体绝缘封闭开关设备内部的电缆终端头是？","a":"D","e":"终端头分为户外终端（受阳光直射或暴露于气候环境，含瓷套式与复合套管式）、GIS终端（以SF6气体为外绝缘）和变压器终端（安装在油浸变压器油箱内，以绝缘油为外绝缘）。","o":["户外终端","瓷套式户外终端","变压器终端","GIS终端"]},{"i":226,"c":10,"t":1,"s":"电缆中间接头中，将被连接电缆的金属护套、接地金属屏蔽和绝缘屏蔽在电气上断开的接头称为？","a":"B","e":"直通接头连接两根电缆形成连续电路，其金属外壳与被连接电缆的金属屏蔽和绝缘屏蔽在电气上连续；绝缘接头则是使其在电气上断开的接头。","o":["直通接头","绝缘接头","过渡接头","分支接头"]},{"i":227,"c":10,"t":1,"s":"电缆附件的选型需综合考虑多方面因素，下列不属于附件选型考虑范畴的是？","a":"D","e":"附件选型主要考虑导体连接方式、电应力控制方式、绝缘材料选型与安装方式四方面；附件的作用是恢复导体、绝缘和外护层的性能。","o":["导体连接方式","电场设计——电应力控制方式","绝缘设计——绝缘材料选型","电缆敷设的实际完成日期"]},{"i":228,"c":10,"t":1,"s":"采用排管敷设电缆时，对排管管孔内径的要求是不小于电缆外径的？","a":"C","e":"课件依据：排管敷设「管内径≥1.5倍电缆外径，预留备用管≥20%」；管材可选用耐高温的MPP管或耐腐蚀的CPVC管。","o":["1.0倍","1.2倍","1.5倍","2.5倍"]},{"i":229,"c":10,"t":1,"s":"电缆主绝缘耐压试验前一般先用兆欧表初判绝缘好坏（110kV电缆一般选用2500V兆欧表），随后的主绝缘耐压试验应采用的试验条件是？","a":"B","e":"课件依据：「兆欧表测试电缆绝缘没有问题后再进行主绝缘耐压试验（2倍U0耐压1小时）」，完好的绝缘兆欧表阻值显示为无穷大。","o":["1.7倍U0耐压30分钟","2倍U0耐压1小时","2.5倍U0耐压10分钟","1倍U0耐压4小时"]},{"i":230,"c":10,"t":1,"s":"巡视中发现必须立即停电处理的紧急缺陷时，按规定其消除时限及配套措施是？","a":"A","e":"紧急缺陷必须立即停电处理，否则可能引发短路、接地故障甚至火灾；电缆缺陷分紧急、重大、一般三级，应优先处理紧急缺陷。","o":["24小时内消除，若无法立即处理需采取临时隔离措施","一周内消除，无需附加措施","30天内计划性消缺，期间加强监测","3个月内整改，或纳入年度检修计划"]},{"i":231,"c":10,"t":1,"s":"电缆故障应急处理采用“三步法”，先用脉冲反射仪初测粗定故障点，随后用于精确定点的方法是？","a":"D","e":"故障定位三步法：初测用脉冲反射仪（误差±10%）粗测，精测用声磁同步法（音频≤5Hz）精确定点，最后开挖后用兆欧表复测绝缘恢复情况。","o":["红外热成像扫描","兆欧表摇测比对","雷电冲击耐压验证","声磁同步法"]},{"i":409,"c":10,"t":1,"s":"在热塑性挤包绝缘材料中，按适用电压范围划分，可在高、中、低压全范围使用的是（　）。","a":"C","e":"考点：热塑性绝缘材料的适用电压范围。依据：「PVC低压；PE中低压；PP高、中、低压」；XLPE属热固性材料，不属于本组对比对象。","o":["PVC","PE","PP","XLPE"]},{"i":410,"c":10,"t":1,"s":"电缆检修五流程环节中，最先开展的是（　）。","a":"B","e":"考点：电缆检修五流程的顺序。依据：「作业准备→安全措施→检修实施→试验验收→恢复送电」。","o":["检修实施","作业准备","试验验收","恢复送电"]},{"i":734,"c":10,"t":1,"s":"在输电系统的组成中，枢纽变电站用于连接不同电压等级和线路，而主要进行线路的投切操作的是（　）。","a":"A","e":"课件在输电系统组成中指出「变电站／开关站：枢纽变电站（连接不同电压等级和线路）、开关站（主要进行线路的投切操作）」。配电室、开闭所、环网柜属配电系统设施。","o":["开关站","配电室","开闭所","环网柜"]},{"i":739,"c":10,"t":1,"s":"基于状态监测结果，对疑似存在缺陷或风险较高的区段进行的重点检查称为（　）。","a":"C","e":"课件规定：「状态巡视：基于状态监测结果，对疑似存在缺陷或风险较高的区段进行重点检查」；定期巡视是按规程周期开展的外观检查。","o":["定期巡视","特殊巡视","状态巡视","故障巡视"]},{"i":743,"c":10,"t":1,"s":"采用“直接推拉式”安装预制橡胶电缆附件时，需要特别注意的问题是（　）。","a":"A","e":"课件说明直接推拉式「需注意预制橡胶件在来回拖动中可能造成预制橡胶件内部损伤」；借助支撑管安装、支撑条预扩径分别属于另外两种安装方式的工艺。","o":["预制橡胶件在来回拖动中可能造成内部损伤","必须先把橡胶件套到比电缆外径大的支撑管上","必须预先将预制件扩径至原内径1.5倍以上","安装精度主要取决于抽调支撑条的时机"]},{"i":744,"c":10,"t":1,"s":"采用工厂预扩径方式安装电缆附件时，采用支撑条支撑，扩径后的尺寸要求达到原内径尺寸的（　）以上。","a":"B","e":"课件要求工厂预扩径方式「采用支撑条支撑，扩径后的尺寸要求达到原内径尺寸的1.5倍以上，装到电缆上后，抽调支撑条」。","o":["1.2倍","1.5倍","2倍","3倍"]},{"i":748,"c":10,"t":1,"s":"依据课件，下列不属于电缆检修目的的是（　）。","a":"D","e":"课件规定电缆检修的目的为「（1）消除隐患（2）恢复绝缘性能（3）预防击穿事故」三项；增大允许载流量不属于检修目的。","o":["消除隐患","恢复绝缘性能","预防击穿事故","增大电缆长期允许载流量"]},{"i":752,"c":10,"t":1,"s":"对于电缆工程的基础掩埋夯实、电缆附件安装等验收过程复杂或需要监督部分工序的项目，由建设单位派遣技术人员到安装现场对各关键环节开展的验收形式是（　）。","a":"C","e":"课件规定此类工程「要进行跟踪验收」，「建设单位派遣有关技术人员到安装现场，对各个关键环节进行跟踪验收」；监造面向设备制造厂，隐蔽工程验收须在掩埋前完成。","o":["监造","隐蔽工程验收","跟踪验收","竣工验收"]},{"i":232,"c":10,"t":2,"s":"关于电力电缆各组成部分的作用，下列说法正确的有？","a":"ABD","e":"缓冲带的作用是在电缆受挤压、弯曲或振动时通过弹性形变吸收机械应力、均匀分布压力并可吸收少量水分，与提高传输容量无关。","o":["导体是电力传输的通路，通过铜、铝等低电阻金属材料引导电流稳定流动","导体屏蔽层包裹在导体外层，填充表面毛刺与绞合缝隙，避免导体表面不平整导致电场集中","缓冲带的主要作用是提高电缆的传输容量","金属护套可抵御机械损伤、阻止水分潮气侵入，并能在绝缘损坏时传导故障电流触发保护动作"]},{"i":233,"c":10,"t":2,"s":"课件归纳了电力电缆的优势应用场景，下列场景与电缆优势的对应关系正确的有？","a":"ABCD","e":"课件依据：电缆优势场景包括城市中心区供电、高可靠性要求区域、沿海多雷区、跨水域连接（唯一可行输电方式）以及化工厂等特殊环境（耐腐蚀、防爆）。","o":["城市中心区供电——无需输电走廊，节约土地，美观安全","高可靠性要求区域——受天气影响小，故障率低","沿海、多雷区——抗风灾、盐雾腐蚀、雷击能力强","跨水域连接——海底、过江电缆是唯一可行的输电方式"]},{"i":234,"c":10,"t":2,"s":"关于电缆类型与技术选型的决策，下列做法正确的有？","a":"ACD","e":"环境温度选型应为高温区选用耐105℃材料、寒带选用防冻裂护套，B项两者颠倒；其余三项与课件选型表一致。","o":["按电压等级选择：低压可选用PVC绝缘，中高压选用交联聚乙烯（XLPE）绝缘","按环境温度选择：寒带地区应选用耐105℃的高温材料","按敷设方式选择：直埋采用钢带铠装，水下采用钢丝铠装并加强防水","按防火要求选择：民用建筑选用无卤低烟（WDZ），化工区选用阻燃A类（ZA）"]},{"i":235,"c":10,"t":2,"s":"关于电缆敷设方式及其技术要点，下列说法正确的有？","a":"ABD","e":"课件依据：「支架层距：高压≥250mm，低压≥200mm」，并非越小越好；隧道内还应设防火隔断并保证排水坡度。","o":["直埋敷设的开挖深度应在冻土层以下，并采取铺沙、盖板（砖）等防护措施","排管敷设可选用耐高温的MPP管或耐腐蚀的CPVC管","电缆沟、隧道的支架层间距离越小越好，高压电缆层距应不大于100mm","桥梁敷设可采用蛇形敷设补偿热伸缩，并配合弹性橡胶垫和夹具固定"]},{"i":236,"c":10,"t":2,"s":"关于电缆敷设的关键控制指标，下列数值要求正确的有？","a":"BCD","e":"课件依据：敷设温度「XLPE电缆≥-20℃，PVC电缆≥0℃」，PVC电缆不允许在-40℃直接敷设。","o":["PVC电缆在-40℃的环境中可直接进行敷设","牵引力控制：铜缆不大于70N/mm²，铝缆不大于40N/mm²","侧压力控制：无铠装电缆不大于3kN/m，铠装电缆不大于7kN/m","敷设温度控制：XLPE电缆一般不低于-20℃"]},{"i":237,"c":10,"t":2,"s":"电缆敷设常用的设备、工具与仪器有哪些？","a":"ABCD","e":"卷扬机（牵引机）、输送机等属敷设设备，牵引头、牵引网套、滑轮属常用工具，兆欧表用于敷设前后绝缘遥测，故障测试设备用于寻找故障点；抱杆属架空线路施工器具。","o":["电动卷扬机（牵引机）、电缆输送机","电缆盘支承架、液压千斤顶和电缆盘制动装置","电缆牵引头、电缆牵引网套和电缆滑轮","兆欧表（绝缘电阻表）、电缆故障测试设备","组立铁塔用的抱杆和拉线制作器具"]},{"i":238,"c":10,"t":2,"s":"关于电缆附件，下列说法正确的有？","a":"ACDE","e":"课件依据：终端头和中间接头均需具有一定的绝缘和密封性能，「运行中约70%的故障发生在附件处」，因此其绝缘密封质量至关重要。","o":["电缆附件分为电缆终端头和电缆中间接头两大类","附件只是机械固定件，对绝缘和密封性能没有要求","终端头安装在电缆线路的两端，使电缆与其他电气设备连接","中间接头安装在电缆与电缆之间，使两根及以上电缆导体连通形成连续电路","附件是整个电缆线路的薄弱环节，运行中约70%的故障发生在附件处"]},{"i":239,"c":10,"t":2,"s":"按19班复习笔记强调的口径，电缆线路的巡视类型包括？","a":"ABCD","e":"笔记强调巡视类型为五类：日常（常规检查）、特殊（异常天气/高负荷后）、故障（事故后专项排查）、夜间（利用高峰负荷或发光现象）、智能（自动化在线监测）。","o":["日常巡视","特殊巡视","故障巡视","夜间巡视","随机巡视"],"n":"课件正文将巡视列为定期巡视、特殊巡视、状态巡视三类；19班、18班笔记及个人补充笔记一致强调五类巡视口径，本题按《重点整理-19班》口径命题。"},{"i":240,"c":10,"t":2,"s":"关于电缆缺陷的分类和处理要求，下列说法正确的有？","a":"BCD","e":"一般缺陷多为轻微老化或外观问题，暂不影响电缆短期运行，可结合检修计划处理、3个月内整改；缺陷管理应优先处理紧急缺陷。","o":["一般缺陷会影响运行安全，必须立即停电处理","电缆缺陷分为紧急缺陷、重大缺陷、一般缺陷三个等级","紧急缺陷须在24小时内消除，不能立即处理的应采取临时隔离措施","重大缺陷一般在30天内计划性消缺，期间加强监测"]},{"i":241,"c":10,"t":2,"s":"电缆典型故障与判别特征的对应关系，正确的有？","a":"ABC","e":"水分侵入故障的判别特征是绝缘电阻呈波动性下降、介质损耗频率特性异常，且故障多发生在接头处，而非稳定上升。","o":["外力破坏故障——突发性跳闸（零序保护动作），故障点可见明显机械损伤，故障电阻通常较低（＜100Ω）","接头/终端故障——红外测温显示接头温度较正常高15℃以上，可见放电痕迹或硅脂溢出","护套破损故障——金属护层接地电流异常增大，外护套绝缘电阻下降，发展具有渐进性","水分侵入故障——绝缘电阻呈持续性稳定上升"]},{"i":242,"c":10,"t":2,"s":"电缆线路开展的预防性试验项目包括？","a":"ABCD","e":"课件所列预防性试验还有避雷器预防性试验等；杆塔接地电阻测量属输电线路专业项目，不属于电缆预防性试验。","o":["主绝缘耐压试验及绝缘电阻测试","护层过电压保护器试验","外护套直流耐压试验","局部放电检测","架空线路杆塔接地电阻测量"]},{"i":243,"c":10,"t":2,"s":"关于电缆检修的类型划分，下列说法正确的有？","a":"ACD","e":"故障后检修是在电缆发生故障后进行应急抢修或修复，属于被动响应型；基于固定周期执行的时间驱动型检修是定期检修。","o":["按检修目的和触发条件，分为定期检修、状态检修、故障后检修、预防性检修","故障后检修是基于监测数据的时间驱动型主动检修","按工作规模和性质，分为小修、大修、事故抢修、改进工程","状态检修依据实时监测数据（如温度、绝缘性能）分析电缆状态后针对性安排，属于数据驱动"]},{"i":244,"c":10,"t":2,"s":"关于电力电缆工程的验收，下列说法正确的有？","a":"ABCE","e":"课件依据：「竣工验收由施工单位的上级工程质量监督部门组织进行」；七个分部工程为电缆土建工程、支架和导管、电缆敷设、电缆终端和接头、接地系统、电气系统、电缆的防火与阻燃。","o":["电缆工程可分为中间过程验收和竣工验收两个环节","中间过程验收主要有监造、隐蔽工程验收、跟踪验收三个环节","隐蔽工程指工程竣工后不易或无法检查的各类施工项目，如电缆沟道建设、接地装置安装等","竣工验收由监理单位组织进行，并填写工程竣工验收签证书","电缆线路工程验收应按分部工程逐项进行，共分七个分部工程"]},{"i":426,"c":10,"t":2,"s":"按照工作规模和性质划分，电缆检修的类型包括（　）。","a":"ABCD","e":"考点：电缆检修的两维分类。依据：「按工作规模和性质，分为：小修、大修、事故抢修、改进工程」；状态检修属于按检修目的和触发条件的划分，两个维度不可混淆。","o":["小修","大修","事故抢修","改进工程","状态检修"]},{"i":601,"c":10,"t":2,"s":"电缆规划的主要内容包括（　）。","a":"ABCD","e":"考点：电缆规划的四个方面。笔记依据：「电缆规划：负荷需求分析、路径规划廊道选择、电缆类型与技术选择、系统可靠设计」。","o":["负荷需求分析","路径规划与廊道选择","电缆类型与技术选择","系统可靠设计","投产后运行值班班的编排"]},{"i":602,"c":10,"t":2,"s":"电缆检修按另一维度的类别划分，包括小修、大修以及（　）。","a":"ABC","e":"考点：电缆检修的两套类别划分。笔记依据：「电缆检修：【定期检修、状态检修、故障后检修、预防性检修】【小修、大修、事故抢修、改进工程】」。“状态检修”属第一组策略类划分。","o":["小修","大修","事故抢修","改进工程"]},{"i":735,"c":10,"t":2,"s":"关于输电系统的组成与功能，下列说法正确的有（　）。","a":"ABC","e":"课件明确输电系统「将大量电能以高电压远距离、大容量输送」，「升压变压器在发电厂出口将电压升高以减小输电损耗」，保护与控制系统用于快速隔离故障；就地分配电能是配电系统的功能，开关站主要进行线路投切操作。","o":["输电线路包括架空线路和地下、海底电缆","升压变压器装设在发电厂出口，将电压升高以减小输电损耗","保护与控制系统用于确保系统安全稳定运行并可快速隔离故障","输电系统的主要功能是将电能就地分配给家庭、商业、工业等各类用户","开关站用于变换电压等级并向低压侧供电"]},{"i":736,"c":10,"t":2,"s":"依据课件，下列属于配电系统组成的有（　）。","a":"ABCE","e":"课件列出配电系统组成：「配电变电站、配电线路（中压架空线路、电缆线路）、配电变压器、低压配电线路、开闭所环网柜配电箱、用户接入点（电表及计量装置）」；升压变压器属于输电系统。","o":["配电变电站","配电线路","配电变压器","升压变压器","开闭所、环网柜、配电箱"]},{"i":738,"c":10,"t":2,"s":"依据课件，下列属于电力电缆运行管理目标的有（　）。","a":"ABDE","e":"课件列出电缆运行管理的管理目标：「安全可靠供电、延长使用寿命、优化运行效率、快速响应故障、符合法规标准」五项；追求经营利润最大化并非所列目标。","o":["安全可靠供电","延长使用寿命","追求经营利润最大化","优化运行效率","快速响应故障"]},{"i":740,"c":10,"t":2,"s":"依据课件，电缆通道管理中应建立的防外力破坏机制包括（　）。","a":"ACDE","e":"课件要求与市政、规划部门协调避免其他施工造成外力破坏，「建立有效的防外力破坏机制（如设立警示标识、开展宣传、签订施工安全协议、进行现场监护）」。","o":["设立警示标识","发现问题一律事后追责即可，无须事先协调","开展宣传","签订施工安全协议","进行现场监护"]},{"i":742,"c":10,"t":2,"s":"依据课件，下列属于电缆附件导体连接方式的有（　）。","a":"ACDE","e":"课件列举导体连接方式为：「螺栓连接、压接（点压、围压）、钎焊连接、熔融焊、铝热剂焊、插入式」；缠绕绑扎不属于规范的导体连接方式。","o":["螺栓连接","缠绕绑扎连接","压接（点压、围压）","钎焊连接","铝热剂焊"]},{"i":746,"c":10,"t":2,"s":"依据课件，开展电力电缆预防性试验的目的包括（　）。","a":"BCDE","e":"课件归纳预防性试验的目的：「检测绝缘缺陷、评估电气性能、识别机械损伤或安装缺陷、延长电缆寿命」四方面；预防性试验并不能提高电缆的允许载流量。","o":["提高电缆长期允许载流量上限","检测绝缘缺陷，预防击穿事故","评估电气性能","识别机械损伤或安装缺陷","延长电缆寿命"]},{"i":747,"c":10,"t":2,"s":"依据课件，电缆运维中的隐患类型识别包括（　）。","a":"ABC","e":"课件将隐患类型分为三类：「外部隐患、本体隐患、附属设施隐患」；并在风险评估中另行划分紧急隐患与一般隐患两级。","o":["外部隐患（通道被挖占、积水、腐蚀、井盖缺失等）","本体隐患（外护套破损、接头过热、绝缘老化等）","附属设施隐患（接地箱锈蚀、标识牌缺失、防火措施失效等）","运行方式隐患（负荷分配不均等）"]},{"i":750,"c":10,"t":2,"s":"电缆检修基本流程的“安全措施”环节，主要包括的工作有（　）。","a":"ABC","e":"检修五环节为作业准备、安全措施、检修实施、试验验收、恢复送电，其中安全措施环节的工作是「停电、验电、接地、悬挂标识牌、装设遮拦围栏」；更换故障电缆头属检修实施，恢复送电是最后一环。","o":["停电","验电和接地","悬挂标识牌并装设遮拦围栏","更换故障电缆头","恢复送电"]},{"i":245,"c":10,"t":3,"s":"石墨层不是电力电缆的重要组成部分。","a":"对","e":"个人笔记明确：石墨层不是关键结构；课件列举的电缆各层组成中不含石墨层，中高压电缆必有的是导体屏蔽、绝缘层、绝缘屏蔽三层共挤结构。"},{"i":246,"c":10,"t":3,"s":"多台电缆输送机和牵引车同时敷设电缆时，必须配备联动控制装置，实现集中控制、关停同步、速度一致。","a":"对","e":"课件依据：「如果同时使用多台输送机和牵引车，则必须要有联动控制装置，使各台输送机和牵引车的操作能集中控制，关停同步，速度一致。」"},{"i":247,"c":10,"t":3,"s":"紧急缺陷若暂时不具备处理条件，可以留待下一年度综合检修计划中一并消除。","a":"错","e":"紧急缺陷必须立即停电处理并在24小时内消除，若无法立即处理需采取临时隔离措施，不能拖延至年度检修计划。"},{"i":248,"c":10,"t":3,"s":"乙丙橡胶（EPR）电缆退役后，其绝缘层很难降解，难以被加工再利用，只能焚烧掩埋。","a":"错","e":"难降解、只能焚烧掩埋造成环境污染是XLPE电缆的问题；EPR电缆退役后其绝缘层可回收再利用，符合“双碳”目标。"},{"i":249,"c":10,"t":3,"s":"进行外护套直流耐压试验时，试验前必须将护层过电压保护器断开。","a":"对","e":"课件依据：外护套直流耐压试验「试验时必须将护层过电压保护器断开」，再分别在每段电缆金属屏蔽或金属套与地之间施加直流电压10kV、加压1min不击穿。"},{"i":250,"c":10,"t":3,"s":"电缆中间接头局部损伤深度大于3mm时，仍可采用绝缘自粘带修复而不必更换整段接头。","a":"错","e":"依据南网修复标准（Q/SCG 1206007-2015第8.3条）：局部损伤深度≤3mm时采用绝缘自粘带修复，＞3mm需更换整段电缆接头。"},{"i":251,"c":10,"t":3,"s":"按电缆接地系统的验收要求，三芯统包交联电缆应两端接地，单芯电缆只应一端接地。","a":"对","e":"课件依据：「三芯统包交联电缆应两端接地，单芯电缆只应一端接地，钢铠接地与铜屏蔽接地应分别引出，互不连通。」"},{"i":252,"c":10,"t":3,"s":"电缆工程建设结束后，施工单位不必先行自检，可直接向监理单位、建设单位提出书面竣工验收申请。","a":"错","e":"课件依据：「工程建设结束后，施工单位应先进行自检，合格后向监理单位、建设单位提出书面验收申请。」"},{"i":438,"c":10,"t":3,"s":"电缆工程验收分为中间过程验收和竣工验收两大类。","a":"对","e":"考点：电缆工程验收的阶段划分。依据：「电缆工程验收分为中间过程验收、竣工验收」，竣工验收是工程整体把关环节。"},{"i":737,"c":10,"t":3,"s":"在配电系统中，配电变电站的作用是将输电电压（如110kV、220kV）降至中压（如10kV、35kV）。","a":"对","e":"课件明确：「配电变电站：将输电电压（如110kV、220kV）降至中压（如10kV、35kV）」，再由配电变压器把中压降至用户可用的低压。"},{"i":741,"c":10,"t":3,"s":"电缆中间接头安装在电缆线路的两端，其主要作用是使电缆与其他电气设备连接。","a":"错","e":"这是电缆终端头的特征。课件区分：「终端头安装在电缆线路的两端，使电缆与其他电气设备连接」「中间接头安装在电缆与电缆之间，使两根及以上电缆导体连通」。"},{"i":745,"c":10,"t":3,"s":"电缆重大缺陷影响设备长期运行安全，但短期内不会直接导致故障，通常不超过1个月安排处理，30天内计划性消缺，期间应加强监测。","a":"对","e":"课件将电缆缺陷分为紧急、重大、一般三级，重大缺陷「需尽快安排处理（通常不超过1个月）」「30天内计划性消缺，期间加强监测」，否则可能发展为危急缺陷。"},{"i":749,"c":10,"t":3,"s":"发现紧急缺陷虽尚未形成事故，但为免发生事故，及时发现后也应尽快组织修理，这种情况也称为事故抢修。","a":"对","e":"课件在事故抢修的定义中明确：「有紧急缺陷但尚未形成事故，及时发现后，也要尽快组织修理，以免发生事故，这种情况也称为事故抢修」。"},{"i":751,"c":10,"t":3,"s":"电缆沟道建设、接地装置安装、电缆附件安装等属于电缆工程的隐蔽工程，应在隐蔽工程掩埋之前组织技术人员验收。","a":"对","e":"课件指出隐蔽工程指工程竣工后不易或无法检查的施工项目，「主要有电缆沟道建设、接地装置安装、电缆附件安装等」，建设单位、监理单位应根据工程进度在掩埋之前组织验收。"},{"i":253,"c":11,"t":1,"s":"根据课件，计量专业的五大核心业务板块是指下列哪一组？","a":"B","e":"考点：计量专业五大核心业务板块。课件依据：「营销技术、计量项目、计量物资、计量运行、营销安全」，其中营销技术的核心内容包括低压透明化、计量3.0深化应用、电碳计量试点等。","o":["计量检定、计量项目、计量物资、计量运行、营销安全","营销技术、计量项目、计量物资、计量运行、营销安全","营销技术、计量检定、计量物资、计量运行、营销安全","营销技术、计量项目、计量运行、营销安全、电能计量事件"],"n":"个人补充笔记将五大核心业务板块写作“计量检定、计量项目……”；按要求以课件及《重点整理-19班》为准取“营销技术”，“计量检定”实为计量五类制度、标准、规程之一。"},{"i":254,"c":11,"t":1,"s":"运行中的电能计量装置按计量对象重要程度和管理需要分为Ⅰ、Ⅱ、Ⅲ、Ⅳ、Ⅴ五类，其中Ⅴ类电能计量装置指的是：","a":"C","e":"考点：电能计量装置的五类划分。课件依据：「Ⅴ类电能计量装置指220V单相电能计量装置」；380V～10kV装置为Ⅳ类。","o":["380V～10kV电能计量装置","10kV～110kV贸易结算用电能计量装置","220V单相电能计量装置","110kV～220kV考核用电能计量装置"]},{"i":255,"c":11,"t":1,"s":"根据课件，完整的计量自动化系统应由哪几部分组成？","a":"D","e":"考点：计量自动化系统的构成。课件依据：「计量自动化系统……由计量自动化系统主站、通信通道、计量自动化终端组成」。","o":["电能表、集中器、采集器","主站计算机、互感器、试验接线盒","厂站终端、负荷管理终端、卫星网络","计量自动化系统主站、通信通道、计量自动化终端"]},{"i":256,"c":11,"t":1,"s":"根据课件规定的电能计量事件分级，每次造成关口1000万千瓦时及以上，或者客户侧500万千瓦时及以上计量差错电量的，属于：","a":"D","e":"考点：电能计量事件分级门槛。课件依据：一类电能计量事件「每次造成关口1000万千瓦时及以上或者客户侧500万千瓦时及以上计量差错电量」。","o":["二类电能计量事件","三类电能计量事件","电能计量一般缺陷","一类电能计量事件"]},{"i":257,"c":11,"t":1,"s":"智能电表是在原有电子式电能表的基础上增加某一单元而形成的新一代电能表，这一单元是：","a":"B","e":"考点：智能电表的定义。课件依据：「在原有电子式电能表基础上增加通信单元，使其具有电能量计量、数据处理、实时监测、自动控制、信息交互等功能」。","o":["存储单元","通信单元","控制单元","显示单元"]},{"i":258,"c":11,"t":1,"s":"根据课件，机械式（感应式）电能表实现电能计量的方式是：","a":"A","e":"考点：三类电能表原理的区别。课件依据：机械式电能表「通过电磁感应原理把电压、电流、相位转变为磁力矩，推动铝圆盘转动进行计量」；B项所述为电子式电能表原理。","o":["通过电磁感应原理把电压、电流、相位转变为磁力矩，推动铝圆盘转动进行计量","对供电电压和电流实时采样，处理后相乘转换成与电能成正比的脉冲输出","利用光电传感器对转盘圈数计数后直接输出数字信号","依据电化学反应累积电荷量来反映消耗的电能"]},{"i":259,"c":11,"t":1,"s":"根据课件，负荷管理终端的安装场所及其主要服务对象是：","a":"D","e":"考点：各类计量自动化终端的应用场所。课件依据：「负荷管理终端安装于专变用户现场用于现场服务与管理，实现对专变用户的远程抄表、电能计量、设备工况、客户用电负荷与电能量监控等功能」。","o":["发电厂和变电站，用于采集存储电能表信息","公用配电变压器台区，用于采集公变侧电能信息","低压居民用户室内，用于实现本地抄表","专变用户现场，用于实现远程抄表与用电负荷监控"]},{"i":260,"c":11,"t":1,"s":"装表接电作业中使用验电器验电的正确做法（三步法验电）是：","a":"C","e":"考点：计量装置安装实施中的安全步骤。课件依据：「三步法验电：1、测试验电器 2、验电 3、再测试验电器」。","o":["先对设备验电，然后再测试验电器的好坏","直接用验电器触碰带电体判别有无电压即可","先测试验电器，然后验电，最后再测试验电器","验电结束后无需再检查验电器的状态"]},{"i":261,"c":11,"t":1,"s":"高压三相三线制带互感器计量装置安装时，为便于日常现场检表和不停电换表处理，应在电能表前端加装：","a":"B","e":"考点：计量装置安装的工艺要求。课件依据：「为便于日常现场检表和不停电换表处理需要，应在电能表前端加装试验接线盒」。","o":["小型断路器","试验接线盒","无功补偿电容器","信号指示灯"]},{"i":262,"c":11,"t":1,"s":"根据课件，对未曾被检定过的计量设备所进行的一种检定称为：","a":"A","e":"考点：计量检定相关术语。课件依据：「首次检定：对未曾被检定过的计量设备进行的一种检定」。","o":["首次检定","周期检定","临时检定","退运检定"]},{"i":263,"c":11,"t":1,"s":"低压透明化建设以新一代智能终端、分支监测单元和带拓扑识别宽带载波模块为技术路线，根据课件，其承载平台是：","a":"C","e":"考点：低压透明化的体系架构。课件依据：「低压透明化建设……以能源互联平台为承载平台，实现‘变压器-分支线路-低压用户’全链路实时监测功能，打通供电服务‘最后一百米’」。","o":["营销管理系统","生产指挥平台","能源互联平台","配电自动化主站"]},{"i":424,"c":11,"t":1,"s":"课程总结的计量专业几大设备品类中，与电能表、终端并列的另一大类计量器具是（　）。","a":"A","e":"考点：计量专业的设备品类构成。依据：「几大设备品类：电能表、互感器、终端」。","o":["互感器","断路器","避雷器","电抗器"]},{"i":467,"c":11,"t":1,"s":"计量专业在电网公司中的定位可以概括为（　）。","a":"B","e":"计量专业承担着电能公平交易的计量基准职能，并为线损分析、负荷管理等提供基础数据支撑，远不止抄表收费或单一的设备作业环节。","o":["仅负责抄表收费业务","电网公平交易的“定盘星”、线损分析的“数据源”、负荷管理的“参考系”","仅负责计量设备的采购与仓储","仅负责现场的装表接电作业"],"n":"原模拟题未附答案，按课件对计量专业定位的表述拟定为B"},{"i":474,"c":11,"t":1,"s":"在计量自动化系统的体系架构中，计量自动化系统主站的定位是（　）。","a":"A","e":"计量自动化系统由计量自动化系统主站、通信通道、计量自动化终端组成，主站是全系统的信息采集与控制中心，通道负责数据传输，终端负责现场采集。","o":["信息采集与控制中心","数据传输通道","现场终端设备","后备电源模块"],"n":"原模拟题未附答案，结合课件系统构成拟定为A"},{"i":498,"c":11,"t":1,"s":"某客户侧计量点发生计量差错电量300万千瓦时，按照电能计量事件分级，该事件应认定为（　）。","a":"B","e":"客户侧每次计量差错电量达到500万千瓦时及以上构成一类电能计量事件；300万千瓦时未达到一类门槛，但已超过二类事件的电量标准，应认定为二类电能计量事件。","o":["一类电能计量事件","二类电能计量事件","三类电能计量事件","不构成电能计量事件"],"n":"原模拟题未附答案，一类事件门槛与本库既有题一致（关口1000万千瓦时或客户侧500万千瓦时），据此按课件事件分级表递推拟定"},{"i":503,"c":11,"t":1,"s":"采用微电流注入法的新一代低压拓扑自动识别技术，拓扑识别准确率可高达（　）以上。","a":"D","e":"微电流注入法结合拓扑分析算法可实现“变—线—户”对应关系的自动识别，识别准确率可达95%以上。","o":["80%","85%","90%","95%"],"n":"原模拟题未附答案，按课件关于低压拓扑自动识别指标的表述拟定"},{"i":570,"c":11,"t":1,"s":"电能计量装置安装工作的正确流程是（　）。","a":"C","e":"考点：计量装置安装流程顺序。笔记依据：「计量装置安装流程：工器具准备→风险评估→安全施工→竣工验收」。","o":["工器具准备→风险评估→竣工验收→安全施工","安全施工→风险评估→工器具准备→竣工验收","工器具准备→风险评估→安全施工→竣工验收","风险评估→安全施工→竣工验收→工器具准备"]},{"i":754,"c":11,"t":1,"s":"某35kV贸易结算用电能计量装置，按照运行中的电能计量装置分类应属于（　）。","a":"C","e":"Ⅲ类电能计量装置指「10kV～110kV贸易结算用电能计量装置，10kV～220kV考核用电能计量装置」等；Ⅱ类对应的贸易结算装置是110kV～220kV，注意二者界限。","o":["Ⅰ类","Ⅱ类","Ⅲ类","Ⅳ类"]},{"i":757,"c":11,"t":1,"s":"依据课件，周期内实际检验电能表数量比应检总量的百分比，这一指标称为（　）。","a":"B","e":"课件界定：「周期检验完成率＝周期内实际检验电能表数量比应检总量的百分比」；首次检验完成率考核首次检验的完成比例，电能计量准确率考虑购电与售电差错电量影响。","o":["首次检验完成率","周期检验完成率","电能计量准确率","计量故障处理及时率"]},{"i":758,"c":11,"t":1,"s":"关于机械式、电子式和智能三代电能表的对比，下列说法正确的是（　）。","a":"B","e":"对比表中电子式电能表的优点是「准确度高、计量稳定、便于安装使用、过载能力强、防窃电能力强」，其维修复杂、抗干扰能力差、寿命不长（10年左右）；智能电表是在原有电子式电能表基础上增加通信单元形成的。","o":["机械式电能表准确度高、防窃电能力强","电子式电能表准确度高、过载能力强、防窃电能力强","电子式电能表的使用寿命一般在30年以上","智能电表是在感应式电能表基础上增加通信单元形成的"]},{"i":759,"c":11,"t":1,"s":"关于厂站电能量采集终端，下列说法正确的是（　）。","a":"D","e":"课件界定：「厂站电能量采集终端是应用在发电厂和变电站的终端，可以实现电能表信息的采集存储和电能表运行工况监测」；前三项分别为配变监测终端、负荷管理终端和集中器的功能。","o":["安装于公用配电变压器台区，采集公变侧电能信息","安装于专变用户现场，实现对专变用户的远程抄表","用于收集各采集器或电能表的数据，并与主站或手持设备进行数据交换","应用于发电厂和变电站，可实现电能表信息的采集存储和运行工况监测"]},{"i":760,"c":11,"t":1,"s":"安装于公用配电变压器台区，实现公变侧电能信息采集的计量自动化终端是（　）。","a":"C","e":"课件指出：「配变监测管理终端安装于公用配电变压器台区，实现公变侧电能信息采集，包括电能量数据采集，配电变压器运行状态监测，供电电能质量监测」，还可集成计量、台区电压考核等功能。","o":["厂站电能量采集终端","负荷管理终端","配变监测管理终端","低压集抄采集终端"]},{"i":761,"c":11,"t":1,"s":"依据低压透明化的停电实时感知判据，判定“线路停电”的依据是（　）。","a":"A","e":"停电池综合研判的三级判据为：「台区停电：额定电压<60%」「线路停电：三相电流<5A」「用户停电：过零信号3-5秒」。","o":["三相电流小于5A","额定电压小于额定值的60%","过零信号持续3～5秒","任一终端离线超过24小时"]},{"i":762,"c":11,"t":1,"s":"利用计量运行数据和GIS拓扑档案构建停电事件信息池，低压透明化的停电信息报送最快可达（　）内。","a":"A","e":"课件给出的停电实时感知指标为「停电报送最快达1分钟内」，研判准确率超过90%，以支撑应急抢修和快速复电管理。","o":["1分钟","5分钟","15分钟","30分钟"]},{"i":264,"c":11,"t":2,"s":"根据课件，计量专业人员需要掌握的核心系统功能涉及的系统包括：","a":"ABCD","e":"考点：计量岗位必备的核心系统。课件依据：「营销系统、计量自动化系统3.0、计量生产管理平台、电网管理平台、移动营销APP、施工管控平台」；财务管控系统不在其中。","o":["营销系统","计量自动化系统3.0","电网管理平台","移动营销APP","财务管控系统"]},{"i":265,"c":11,"t":2,"s":"对照课件中感应式电能表、电子式电能表与智能电表的功能对比，仅智能电表具备而电子式电能表不具备的功能是：","a":"BC","e":"考点：三代电能表功能差异。课件依据：功能对比表中「预付费功能」「远程停电复电」仅智能电表具备（O），电子式电能表均标注为不具备（－）；冻结、事件记录为电子式和智能电表共有。","o":["冻结功能","预付费功能","远程停电复电","事件记录功能"]},{"i":266,"c":11,"t":2,"s":"关于电压互感器和电流互感器，下列说法正确的有：","a":"BCD","e":"考点：两类互感器的名称与作用。课件依据：「电压互感器（Potential Transformer简称PT或TV）……可分为电磁式电压互感器和电容式电压互感器两种」「电流互感器（Current Transformer简称CT或TA）是依据电磁感应原理将一次侧大电流转换成二次侧小电流来测量的仪器」。","o":["电流互感器的作用是将二次侧小电流变换成一次侧大电流以便输送","电压互感器和变压器类似，是用来变换电压的仪器","电压互感器简称PT或TV，可分为电磁式电压互感器和电容式电压互感器两种","电流互感器简称CT或TA，是依据电磁感应原理将一次侧大电流转换成二次侧小电流来测量的仪器"]},{"i":267,"c":11,"t":2,"s":"课件指出计量自动化终端按照应用场所可以分为多种类型，下列属于其中的有：","a":"ABCD","e":"考点：计量自动化终端的分类。课件依据：「按照应用场所可以分为厂站电能量采集终端、负荷管理终端、配变监测计量终端、低压集抄采集终端（包括集中器、采集器）等类型」。","o":["厂站电能量采集终端","负荷管理终端","配变监测计量终端","低压集抄采集终端","高压直流输电在线监测终端"]},{"i":268,"c":11,"t":2,"s":"依据课件中互感器验收的相关要求，下列说法正确的有：","a":"ABC","e":"考点：互感器安装验收要求。课件依据：「极性应正确，二次线呈减极性接出」「未使用的二次绕组端子必须用二次线短接」「V/V接法的电压互感器组应B相二次电压接地」「电流互感器二次公共线应接地正确」，故D项说法相反。","o":["电流、电压互感器极性应正确，二次线呈减极性接出，二次线相别与一次一致","未使用的二次绕组端子必须用二次线短接","V/V接法的电压互感器组应B相二次电压接地","电流互感器二次公共线必须断开，严禁接地"]},{"i":269,"c":11,"t":2,"s":"关于电能表与计量终端的安装验收要求，下列说法正确的有：","a":"BCD","e":"考点：电能表及终端的安装验收要求。课件依据：「不得安装在活动的柜门上」「应以‘一孔一线’……流压同相，正相序接线为原则」；密封金属柜对无线信号产生屏蔽，终端安装于完全密封金属装置内则必须引出外置天线。","o":["终端天线应置于完全密封的金属装置内部以保证信号最强","电能表接线应以“一孔一线”，各处螺丝拧紧，并以流压同相、正相序接线为原则","负荷管理终端宜与计量电流回路串联、电压回路并联连接，并接入与电能表通讯的RS-485线","电能表应安装在电能计量柜内，不得安装在活动的柜门上"]},{"i":270,"c":11,"t":2,"s":"课件列举了低压透明化体系具备的功能，下列属于其中的有：","a":"ABCD","e":"考点：低压透明化的功能清单。课件依据：「重过载台区治理、三相不平衡治理、超负荷用电管理、低电压监测、停电实时监控、拓扑自动识别、分支线路监测」，其中不包含无功自动补偿。","o":["拓扑自动识别","三相不平衡治理","低电压监测","停电实时监控","变压器无功自动补偿"]},{"i":271,"c":11,"t":2,"s":"关于新一代低压拓扑自动识别采用的微电流注入法，下列说法正确的有：","a":"ABD","e":"考点：低压拓扑自动识别的原理与优缺点。课件依据：「当变压器二次侧或分支侧检测到该电流后，结合拓扑分析算法，实现‘变-线-户’拓扑关系自动识别」「优点：准确率高达95%以上……缺点：微电流增加一次系统谐波」。","o":["运用HPLC模块控制负载投切的技术，向电网中发送特征电流","当变压器二次侧或分支侧检测到该特征电流后，结合拓扑分析算法实现“变-线-户”拓扑关系自动识别","该方法注入的微电流对电网没有任何影响","优点是准确率高达95%以上，并可获取支路的电能量数据用于支撑三相不平衡、线损等高级应用"]},{"i":272,"c":11,"t":2,"s":"根据课件，计量AI指挥官主要包括的四大功能是：","a":"ABCD","e":"考点：计量AI指挥官的功能构成。课件依据：「主要包括AI巡视、AI诊断、AI运维、AI日报四大功能」。","o":["AI巡视","AI诊断","AI运维","AI日报"]},{"i":273,"c":11,"t":2,"s":"对照课件中的计量术语定义，下列说法正确的有：","a":"AC","e":"考点：现场检验、远程检验、临时检定等术语辨析。课件依据：现场检验「指在现场开展的首次检验、周期检验和临时检定（检验）工作」；远程检验是「利用计量自动化系统对在运行计量装置进行相位角检查、电流电压值检查和电量比对等工作」，并非拆回实验室检测。","o":["临时检定是对运行中或更换拆回的电能计量器具有疑义时所进行的计量准确性检定（检验）","现场检验只能在主站远程完成，无须到现场开展工作","退运电能表指因故障拆回、业扩拆换和批量更换等原因现场拆回的电能表","远程检验须将装置拆回实验室逐项检测后方可出具结论"]},{"i":478,"c":11,"t":2,"s":"下列属于Ⅰ类电能计量装置的有（　）。","a":"ACD","e":"按课件分类表，Ⅰ类电能计量装置包括220kV及以上贸易结算装置、500kV及以上考核用装置以及300MW及以上发电机发电量计量装置；10kV贸易结算装置级别较低，220V单相电能计量装置则属Ⅴ类。","o":["220kV及以上贸易结算用电能计量装置","10kV贸易结算用电能计量装置","500kV及以上考核用电能计量装置","计量单机容量300MW及以上发电机发电量的电能计量装置","220V单相供电的电能计量装置"],"n":"原模拟题未附答案，按课件电能计量装置Ⅰ～Ⅴ类分类表拟定"},{"i":483,"c":11,"t":2,"s":"下列属于计量项目板块核心内容的有（　）。","a":"ABD","e":"计量项目板块聚焦工程改造与轮换项目，如负控改造、表计轮换、专变终端改造；低压透明化建设属营销技术核心内容，计量装置巡检属计量运行范畴。","o":["负控改造","表计轮换","低压透明化建设","专变终端改造","计量装置巡检"],"n":"原模拟题未附答案，按课件五大业务板块的内容划分拟定"},{"i":490,"c":11,"t":2,"s":"下列属于营销技术板块核心内容的有（　）。","a":"ABDE","e":"低压透明化建设、计量电鸿、宽带全覆盖、计量3.0深化应用、电碳计量试点等均属营销技术板块的核心内容；表计轮换属计量项目板块内容。","o":["低压透明化建设","计量电鸿","表计轮换","计量3.0深化应用","电碳计量试点"],"n":"原模拟题未附答案，按课件五大业务板块的内容划分拟定"},{"i":753,"c":11,"t":2,"s":"依据课件，下列属于计量专业“营销安全”板块核心内容的有（　）。","a":"ABC","e":"营销安全板块核心内容为「现场安全管理、施工队安全管理、网络安全管理（防攻击）」，重点是线上线下安全督查；质量监督指标监控、库运比监控属计量物资板块的管理要点。","o":["现场安全管理","施工队安全管理","网络安全管理（防攻击）","质量监督31项指标监控","库运比指标监控"]},{"i":764,"c":11,"t":2,"s":"依据课件，电能表轮换“规划阶段”应用的智能体（智能应用）包括（　）。","a":"ABCD","e":"规划阶段依托「电能表状态评价智能体、年度轮换计划智能编排、专变改造方案智能生成、项目物资需求智能预测」四项应用实现智能决策、精准规划；工单全流程自动化流转（RPA）属于执行阶段。","o":["电能表状态评价智能体","年度轮换计划智能编排","专变改造方案智能生成","项目物资需求智能预测","工单全流程自动化流转智能体（RPA）"]},{"i":766,"c":11,"t":2,"s":"依据课件，电能表轮换“收尾阶段”应用的智能体包括（　）。","a":"BCD","e":"收尾阶段的三类智能体为「换表资料自动归档智能体、营销项目进度智能监控智能体、项目验收智能辅助智能体」，实现资料自动化、进度可视化；换表数据智能核验属执行阶段，电能表状态评价属规划阶段。","o":["换表数据智能核验智能体","换表资料自动归档智能体","营销项目进度智能监控智能体","项目验收智能辅助智能体","电能表状态评价智能体"]},{"i":767,"c":11,"t":2,"s":"依据课件，下列属于计量岗位“软技能”范畴的有（　）。","a":"ABC","e":"课件列出的软技能包括「安全意识（重中之重）、责任心、学习能力、沟通协作能力、问题分析与解决能力、细致严谨」；注册计量师属于证书类，电工基础属于技术技能。","o":["安全意识","责任心","细致严谨","注册计量师证书","电工基础知识"]},{"i":274,"c":11,"t":3,"s":"低压三相四线制带互感器计量装置安装时，三只低压电流互感器二次绕组宜采用不接地形式，但固定支架应接地。","a":"对","e":"考点：低压互感器安装的特殊要求。课件依据：「三只低压电流互感器二次绕组宜采用不接地形式（固定支架应接地）」。"},{"i":275,"c":11,"t":3,"s":"装设安全围栏时，应在围栏出入口悬挂“在此工作”标示牌，在工作位置悬挂“从此进出”标示牌。","a":"错","e":"考点：安全围栏标示牌的悬挂位置。课件依据：「在围栏出入口悬挂‘从此进出’标示牌，在工作位置悬挂‘在此工作’标示牌」，题干将两者互换。"},{"i":276,"c":11,"t":3,"s":"电能计量用互感器二次回路上不得接入任何与计量无关的设备，中间也不得经过任何辅助接点、接头或其他连接端子。","a":"对","e":"考点：计量二次回路的专用性。课件依据：「电能计量用互感器二次回路上不得接入任何与计量无关的设备，中间不得经过任何辅助接点、接头或其他连接端子」。"},{"i":277,"c":11,"t":3,"s":"实施低压透明化改造后，低压用户负荷数据的采集频率仍为一日一点。","a":"错","e":"考点：低压透明化改造前后采集频率对比。课件依据：改造前低压用户负荷数据为「一日一点」，改造后为「15分钟」，停电告警实现实时上报。"},{"i":278,"c":11,"t":3,"s":"电表并网投运时会进行首次检验，运行阶段还需要定期开展远程检验或现场周检。","a":"对","e":"考点：电表全生命周期的检验安排。课件依据：「电表出生并网时会进行首检，运行阶段需要进行定期远程检验或者现场周检」。"},{"i":279,"c":11,"t":3,"s":"短时之内不会劣化为紧急缺陷、尚能运行但影响准确计量的计量缺陷，属于电能计量紧急缺陷。","a":"错","e":"考点：计量缺陷分级定义。课件依据：上述表述实为「电能计量一般缺陷」的定义；紧急缺陷指直接威胁安全运行需立即处理，否则随时可能造成人身伤亡、设备损坏、客户用电中断等的计量缺陷。"},{"i":755,"c":11,"t":3,"s":"电能计量装置仅由电能表和互感器两部分组成，不包括二次回路。","a":"错","e":"课件明确：「计量装置构成由电能表、互感器及二次回路组成，含电能表柜」，以确保计量准确性。"},{"i":756,"c":11,"t":3,"s":"按照电能计量事件分级，每次造成关口计量点500万千瓦时及以上、1000万千瓦时以下计量差错电量的，属于二类电能计量事件。","a":"对","e":"课件分级规定：二类电能计量事件为「每次造成关口计量点500万千瓦时及以上1000万千瓦时以下、用户计量点200万千瓦时及以上500万千瓦时以下的计量差错电量」。"},{"i":763,"c":11,"t":3,"s":"低压透明化可充分利用重过载线路预警数据，通过“日监控、日报”机制及时将告警传递至镇街中心整改，支撑线路故障隐患排查治理。","a":"对","e":"典型应用案例显示，生产指挥中心通过能源互联共享平台监测低压透明化出线重过载信息，「建立『日监控、日报』机制」，全年完成过载、重载线路治理，有效排查线路故障隐患。"},{"i":765,"c":11,"t":3,"s":"RPA机器人作为“数字员工”，可模拟人工操作跨营销、用采及资产管理系统自动流转工单，实现7×24小时不间断运转。","a":"对","e":"课件介绍：「RPA机器人作为『数字员工』，模拟人工操作跨营销、用采及资产管理系统自动流转工单，实现业务数据的无缝同步与高效协同」，7×24小时不间断运转，将员工从重复繁琐的跨系统操作中解放。"},{"i":280,"c":12,"t":1,"s":"《中华人民共和国电力法》于1995年12月28日由第八届全国人民代表大会常务委员会第十七次会议通过，其正式施行的时间是（ ）。","a":"B","e":"考点：《电力法》的施行时间。课件依据：「《电力法》自1996年4月1日起施行，2009年、2015年和2018年做过文字表述或个别条款的修订」，共十章七十五条。","o":["1995年12月28日","1996年4月1日","1996年10月1日","1998年4月1日"]},{"i":281,"c":12,"t":1,"s":"根据《电力法》，国家对电力供应和使用实行的管理原则是（ ）。","a":"A","e":"考点：电力供应与使用的管理原则。课件依据：「国家对电力供应和使用，实行安全用电、节约用电、计划用电的管理原则」（第四章电力供应与使用第二十四条）。","o":["安全用电、节约用电、计划用电","安全用电、经济用电、优质用电","计划用电、定额用电、限量用电","节约用电、绿色用电、智能化用电"]},{"i":282,"c":12,"t":1,"s":"2024年3月18日，国家发展改革委发布第14号令，正式对外公布新修订的《供电营业规则》，该规则自（ ）起施行。","a":"D","e":"考点：新《供电营业规则》的施行时间。课件依据：「2024年3月18日，国家发展改革委发布第14号令，正式对外公布新修订的《供电营业规则》，自2024年6月1日起实行」。注意2024年3月1日是修订后《电力企业信息披露规定》的施行时间，易混淆。","o":["2023年12月1日","2024年1月1日","2024年3月1日","2024年6月1日"]},{"i":283,"c":12,"t":1,"s":"新修订的《供电营业规则》规范了中止供电的管理，停电或限电原因消除后恢复供电的时间由三天压缩至（ ）。","a":"C","e":"考点：新规则对恢复供电时限的修订。课件依据：「将停电或限电原因消除后、恢复供电的时间由三天压缩至二十四小时，保障用户合理的用电权利」。","o":["12小时","18小时","24小时","48小时"]},{"i":284,"c":12,"t":1,"s":"结合计量采集技术进步的实际，新修订的《供电营业规则》对违约使用电费收取标准作出的调整是（ ）。","a":"C","e":"考点：窃电违约使用电费标准的修订。课件依据：「将违约使用电费由固定的三倍调整为不高于三倍」，从而有利于根据违约情形、主观过错等因素合理确定违约责任。","o":["由固定的三倍调整为不高于五倍","由固定的两倍调整为固定的三倍","由固定的三倍调整为不高于三倍","全面取消了违约使用电费的收取"]},{"i":285,"c":12,"t":1,"s":"新《供电营业规则》为进一步精简流程环节、降低用户接电成本，将低压单相、三相接入容量界限分别提高至（ ）。","a":"B","e":"考点：业扩报装规则修订中的数字参数。课件依据：「将低压单相、三相接入容量界限分别提高至12千瓦、160千瓦，降低用户接电成本」。","o":["8千瓦、100千瓦","12千瓦、160千瓦","16千瓦、200千瓦","20千瓦、240千瓦"]},{"i":286,"c":12,"t":1,"s":"根据《供电监管办法》，供电企业违反公平、无歧视开放供电市场的有关规定，由电力监管机构责令改正，拒不改正的，可处（ ）罚款。","a":"D","e":"考点：《供电监管办法》罚则的罚款幅度。课件依据：「处10万元以上100万元以下罚款……情节严重的，可以吊销电力业务许可证」；5万元至50万元的罚款幅度属于《电力企业信息披露规定》。","o":["1万元以上10万元以下","5万元以上50万元以下","20万元以上200万元以下","10万元以上100万元以下"]},{"i":287,"c":12,"t":1,"s":"《供电监管办法》规定，供电企业发现用户受电设施存在故障隐患时，应当采取的做法是（ ）。","a":"A","e":"考点：供电企业对用户受电工程服务的监管要求。课件依据：「发现用户受电设施存在故障隐患时，应当及时一次性书面告知用户并指导其予以消除」；存在严重威胁电力系统安全和人身安全隐患的，隐患消除前不得送电。","o":["及时一次性书面告知用户并指导其予以消除","立即对用户中止供电并处以罚款","先行代为整改，再向用户收取全部费用","电话口头提醒用户自行安排处理"]},{"i":288,"c":12,"t":1,"s":"《电力企业信息披露规定》要求电力企业、电力调度交易机构披露信息应遵循的原则是（ ）。","a":"B","e":"考点：信息披露的基本原则。课件依据：「电力企业、电力调度交易机构披露信息遵循真实、及时、透明的原则」；「公开、公正和效率」是《供电监管办法》中供电监管应当遵循的原则。","o":["公开、公正、效率","真实、及时、透明","真实、准确、完整","广泛、便民、共享"]},{"i":289,"c":12,"t":1,"s":"按《用电检查管理实施细则》，对不同类型客户按一定周期开展周期用电检查，其中对10kV客户的检查周期为（ ）。","a":"D","e":"考点：周期用电检查的周期规定。课件依据：检查形式要求「重要客户每年1次，10kV客户每2年1次，居民客户每年抽查0.5%～2%」。","o":["每半年1次","每年1次","每3年1次","每2年1次"]},{"i":290,"c":12,"t":1,"s":"用电检查人员实行持证上岗、按证定级检查。持有二级用电检查证的人员，可以担任的用电检查工作是（ ）。","a":"C","e":"考点：用电检查证的资格等级与适用电压等级。课件依据：一级用电检查证可担任220千伏及以下电压供电客户的用电检查，二级担任20千伏及以下，三级担任0.4千伏及以下。","o":["0.4千伏及以下电压供电客户的用电检查","10千伏及以下电压供电客户的用电检查","20千伏及以下电压供电客户的用电检查","220千伏及以下电压供电客户的用电检查"]},{"i":402,"c":12,"t":1,"s":"关于《电力法》与新修订《供电营业规则》的篇章结构，下列说法正确的是（　）。","a":"A","e":"考点：两部电力法规的篇章结构。依据：「《电力法》＝10章75条」「新《供电营业规则》＝10章110条」。","o":["《电力法》共10章75条","《电力法》共10章110条","新《供电营业规则》共10章75条","两部法规均为10章90条"]},{"i":403,"c":12,"t":1,"s":"按照重要客户电源配置要求，应配置不少于三路电源的用户等级是（　）。","a":"A","e":"考点：重要客户分级电源配置。依据：「电源配置＝特级三路、一级两路、二级双回路」，三路电源对应特级重要用户。","o":["特级重要用户","一级重要用户","二级重要用户","临时重要用户"]},{"i":404,"c":12,"t":1,"s":"按照重要客户服务管理要求，对重要客户开展线路检修应提前多少天通知客户？（　）","a":"C","e":"考点：重要客户线路检修的通知时限。依据：「重要客户线路检修提前7天通知」。","o":["3天","5天","7天","15天"]},{"i":405,"c":12,"t":1,"s":"开展用电检查工作的主要目的是（　）。","a":"B","e":"考点：用电检查的工作定位。依据：「用电检查：维护供用电秩序＋保障供电安全」，并非增供促销或代办客户内部业务。","o":["扩大企业售电量规模","维护供用电秩序和保障供电安全","收集客户信息用于商业营销","代客户改造其产权设备"]},{"i":406,"c":12,"t":1,"s":"对违约用电、窃电行为进行处理时，正确流程的首要环节是（　）。","a":"A","e":"考点：违约用电、窃电的处理程序。依据：「违约/窃电＝依法取证→费用追缴→必要时中止供电」，取证在前，中止供电仅在必要时实施。","o":["依法取证","约谈客户负责人","费用追缴","中止供电"]},{"i":465,"c":12,"t":1,"s":"用电检查的目的是（　）。","a":"D","e":"用电检查的目的是维护正常供用电秩序、保障供电安全；它不具有行政处罚权，也不承担客户设备的维修保养义务。","o":["增加供电企业的营业收入","代替政府部门实施行政处罚","负责客户受电设备的维修保养","维护正常的供用电秩序、保障供电安全"]},{"i":475,"c":12,"t":1,"s":"从法律效力层次看，《供电营业规则》是《电力法》和《电力供应与使用条例》的（　）。","a":"B","e":"《供电营业规则》是《电力法》《电力供应与使用条例》最重要的配套规章，用于规范具体供用电营业行为，并非二者的上位法或替代文件。","o":["上位法","最重要的配套规章","替代性文件","参考性指南"]},{"i":480,"c":12,"t":1,"s":"新修订的《供电营业规则》共分为（　）。","a":"C","e":"新修订的《供电营业规则》共十章、一百一十条，自2024年6月1日起施行。","o":["八章、九十五条","九章、一百零二条","十章、一百一十条","十二章、一百三十条"]},{"i":484,"c":12,"t":1,"s":"按照《供电营业规则》，窃电时间无法查明时，窃电日数至少按（　）天计算。","a":"C","e":"窃电时间无法查明时，窃电日数至少以一百八十天计算，再乘以窃电容量确定窃电量。","o":["60","90","180","365"]},{"i":486,"c":12,"t":1,"s":"依据《供电营业规则》，窃电用户恢复送电须满足相应条件，其中包括承担（　）的违约使用电费。","a":"C","e":"按查处窃电的工作要求，窃电用户须补交电费并承担相应违约使用电费，接受处理并完成整改后方可恢复送电。","o":["补交电费的1倍","补交电费的2倍","补交电费的3倍","补交电费的5倍"],"n":"违约倍率与本库#284所引新规“不高于三倍”的新旧口径存在差异，本题主问按模拟题库原文口径命题"},{"i":488,"c":12,"t":1,"s":"供电企业对查获的窃电者，依据《供电营业规则》可以采取的措施是（　）。","a":"A","e":"供电企业对查获的窃电者应予制止并可当场中止供电；罚款、行政拘留属行政执法权力，没收财产也须经法定程序由有权机关实施，供电企业无权行使。","o":["当场中止供电","当场处以罚款","没收窃电设备和财产","直接给予行政拘留处罚"]},{"i":491,"c":12,"t":1,"s":"特级重要客户应具备的电源供电条件是（　）。","a":"C","e":"特级重要客户应具备三路电源供电条件；一级重要客户具备两路来自不同变电站的电源，二级重要客户具备双回路电源。","o":["一路电源","两路电源","三路电源","四路电源"]},{"i":499,"c":12,"t":1,"s":"按照供电服务质量要求，城市地区年供电可靠率应不低于（　）。","a":"C","e":"城市地区年供电可靠率不低于99%，同时城市居民用户受电端电压合格率不低于95%。","o":["95%","97%","99%","99.9%"]},{"i":500,"c":12,"t":1,"s":"按照供电企业的信息公示要求，下列供电服务信息的披露方式中错误的一项是（　）。","a":"D","e":"披露信息可以采取门户网站、报刊广播电视、信息发布会、简报公告等多种方式；“只允许线下张贴、禁止网络发布”与规定相反。","o":["通过门户网站发布","通过报刊、广播、电视刊播","召开信息发布会或印发简报公告","只允许在营业厅纸质张贴，禁止网络发布"]},{"i":552,"c":12,"t":1,"s":"依据《电力法》，在我国电力领域的法律体系中，《电力法》的定位是（　）。","a":"D","e":"考点：《电力法》的法律定位。笔记依据：「《电力法》：电力领域的基本法律，保护电力投资者、经营者的合法权益」。","o":["电力部门的工作规章","地方性电力管理办法","电力领域的行政法规","电力领域的基本法律"]},{"i":553,"c":12,"t":1,"s":"依据《供电监管办法》对供电质量的监管要求，城市地区年供电可靠率应不低于（　）。","a":"B","e":"考点：《供电监管办法》供电质量监管指标。笔记依据：「城市地区年供电可靠率不低于99%；城市居民用户受电端电压合格率不低于95%」。","o":["95%","99%","98%","99.9%"]},{"i":554,"c":12,"t":1,"s":"依据《供电监管办法》，10kV以上供电用户受电端的电压合格率应不低于（　）。","a":"C","e":"考点：《供电监管办法》供电质量监管指标。笔记依据：「10kV以上供电用户受电端电压合格率不低于98%」（城市居民用户为95%）。","o":["95%","97%","98%","100%"]},{"i":555,"c":12,"t":1,"s":"新《供电营业规则》对窃电量的认定原则是（　）。","a":"A","e":"考点：新《供电营业规则》公共用电秩序管理的修订要点。笔记依据：「窃电量以查实为优先、无法查实才估算」。","o":["以查实为优先，无法查实的才进行估算","一律按历史平均用电量估算","一律按举报人提供的数额认定","以供电企业的初步估计为准"]},{"i":556,"c":12,"t":1,"s":"按用电检查隐患分级，中断供电可能引发较大事故的重大隐患属于（　）。","a":"B","e":"考点：用电检查隐患分级。笔记依据：「I级重大隐患直接威胁电网安全；II级重大隐患可能引发较大事故；一般隐患需限期整改」。","o":["I级重大隐患","II级重大隐患","一般隐患","特别重大隐患"]},{"i":557,"c":12,"t":1,"s":"供电企业对重要客户的管理应遵循的原则是（　）。","a":"A","e":"考点：重要客户管理原则。笔记依据：「重要客户管理原则：政府主导、责任明确、分级管理、重点保障」。","o":["政府主导、责任明确、分级管理、重点保障","企业为主、市场运作、统一标准、均衡保障","重点突出、先急后缓、动态调整、全面兜底","客户至上、终身负责、无条件保障"]},{"i":712,"c":12,"t":1,"s":"《电力企业信息披露规定》由国家电力监管委员会于2005年11月30日发布，其最初开始实施的日期是（　）；后经2024年修订，新版自2024年3月1日起施行。","a":"B","e":"考点：《电力企业信息披露规定》的颁布与修订节点。课件原文：“由国家电力监管委员会于2005年11月30日发布，自2006年1月1日起实施。2024年1月4日，经《中华人民共和国国家发展和改革委员会令 第11号》修订，自2024年3月1日起施行。”","o":["2005年11月30日","2006年1月1日","2010年1月1日","2024年1月4日"]},{"i":713,"c":12,"t":1,"s":"根据《电力企业信息披露规定》，电力企业未按照规定披露有关信息或者披露虚假信息，经责令改正拒不改正的，将被处（　）罚款。","a":"B","e":"考点：信息披露违法行为的罚则。课件原文：“由电力监管机构给予批评，责令改正；拒不改正的，处5万元以上50万元以下的罚款，对直接负责的主管人员和其他直接责任人员，依法给予处分。”注意与《供电监管办法》10万元以上100万元以下的罚则相区分。","o":["1万元以上10万元以下","5万元以上50万元以下","10万元以上100万元以下","50万元以上500万元以下"]},{"i":716,"c":12,"t":1,"s":"重要用户的分级管理中，中断供电将可能造成较大环境污染、较大政治影响、较大经济损失，或造成一定范围社会公共秩序严重混乱的用电客户属于（　）。","a":"C","e":"考点：一级与二级重要用户后果程度的界限。课件载明二级重要用户的后果均为“较大”“一定范围”程度；表述为“严重环境污染”“重大政治影响”“重大经济损失”“直接引发人身伤亡”等的则属一级重要用户。","o":["特级重要用户","一级重要用户","二级重要用户","重点关注客户"]},{"i":291,"c":12,"t":2,"s":"关于《电力法》的有关规定，下列说法正确的有（ ）。","a":"ABC","e":"考点：《电力法》总则与电力建设、供应使用条款的综合理解。因抢险救灾需要紧急供电时供电企业必须尽速安排供电；用户使用的电力电量以计量检定机构依法认可的用电计量装置的记录为准。","o":["电是商品，是发、输、供、用同一瞬间完成的特殊商品","电力建设项目不得使用国家明令淘汰的电力设备和技术","城市电网的建设与改造规划应当纳入城市总体规划","因抢险救灾需要紧急供电时，供电企业可视自身情况择期安排供电","用户使用的电力电量以供电企业人工抄表的记录为准"]},{"i":292,"c":12,"t":2,"s":"新《供电营业规则》修订体现了国家加强自然垄断环节监管的要求，下列属于本次修订内容的有（ ）。","a":"BCD","e":"考点：新规则适应改革变化的修订要点。课件依据：「明确供电企业应当无歧视地向用户提供供电服务……删除了按指标供电和用电等内容，删除了供电贴费、电能表保证金、电费保证金等垄断性服务收费；增加了供电企业信息公开的要求」。供电企业不得自定电价。","o":["允许供电企业根据自身经营需要自主确定并执行自定电价","明确供电企业应当无歧视地向用户提供供电服务并按电力体制改革要求履行相应服务责任","删除了按指标供电和用电以及供电贴费、电能表保证金、电费保证金等已取消的垄断性服务收费","增加了供电企业信息公开的要求"]},{"i":293,"c":12,"t":2,"s":"新《供电营业规则》坚持利企便民完善业务规则，下列关于业扩报装和电能计量方面修订要点的表述，正确的有（ ）。","a":"ABD","e":"考点：新规则完善业扩报装、电能计量规则的要点。课件依据：「调整了计量装置赔偿责任，除因用户原因引起的情形，其他均由供电企业承担」，故C表述颠倒。","o":["取消了一般用户的设计审查、中间检查，进一步精简流程环节","规范了竣工检验业务要求，检验范围为投运后可能影响公共安全运行的涉网设备","计量装置损坏时，除因供电企业原因引起的情形外，赔偿责任均由用户承担","明确考核表或者其他电能量测量装置记录可作为电量计算的依据"]},{"i":294,"c":12,"t":2,"s":"《供电监管办法》明确了供电企业在供电经营活动中的禁止性行为，下列属于禁止行为的有（ ）。","a":"BCDE","e":"考点：《供电监管办法》第十八条、第十九条规定的禁止性行为。A项是供电企业应当履行的义务而非禁止行为，其余各项均属明令禁止的行为。","o":["严格按照国家核准电价或市场交易价、依据依法认可的计量记录向用户计收电费","无正当理由拒绝用户用电申请","违反市场竞争规则，以不正当手段损害竞争对手的商业信誉或者排挤竞争对手","对用户受电工程指定设计单位、施工单位和设备材料供应单位","擅自在电费中加收或者代收国家政策规定以外的其他费用"]},{"i":295,"c":12,"t":2,"s":"《供电监管办法》规定，电力监管机构依法履行职责进行现场检查时，可以采取的措施包括（ ）。","a":"ABCD","e":"考点：《供电监管办法》中的监管措施。课件依据第二十八条规定了进入检查、询问说明、查阅复制封存资料、当场纠正或限期改正四项现场检查措施，扣留人员不在其列。","o":["进入供电企业进行检查","询问供电企业的工作人员，要求其对有关检查事项作出说明","查阅、复制与检查事项有关的文件、资料，对可能被转移、隐匿、损毁的文件、资料予以封存","对检查中发现的违法行为，可以当场予以纠正或者要求限期改正","当场扣留涉嫌违法行为的直接责任人员"]},{"i":296,"c":12,"t":2,"s":"《电力企业信息披露规定》要求从事供电业务的企业向电力用户披露相关信息，下列属于应披露信息的有（ ）。","a":"BCDE","e":"考点：供电企业应向电力用户披露的信息内容。课件依据第七条列出了供电质量标准、配电电价销售电价和收费标准、用电业务办理程序、停电限电和事故抢修处理情况、用电投诉处理情况等信息，不含其他用户的隐私信息。","o":["其他用户用电投诉单据及其个人身份信息","国家规定的供电质量标准","国家批准的配电电价、销售电价和收费标准","用电业务的办理程序","停电、限电和事故抢修处理情况"]},{"i":297,"c":12,"t":2,"s":"按《用电检查管理实施细则》，用电检查的主要范围是客户受电装置，出现下列情形时检查范围可延伸至相应目标所在处的有（ ）。","a":"ABDE","e":"考点：用电检查范围可延伸的情形。课件依据列举了有多类电价用电性质、有自备电源、有违约用电窃电及安全隐患需延伸检查、有影响电能质量用电设备、发生影响电力系统事故或重大不良影响事件需作调查、法律法规要求的其它检查等情形，用电量正常波动不属于延伸情形。","o":["客户有多类电价用电性质的","客户有自备电源（包括自备发电厂）的","客户当月用电量较上月有所波动的","客户有违约用电、窃电及安全隐患需延伸检查的","客户发生影响电力系统事故或重大不良影响事件需作调查的"]},{"i":298,"c":12,"t":2,"s":"关于用电检查的程序要求，下列说法正确的有（ ）。","a":"ABD","e":"考点：用电检查的程序要求。课件依据：「现场检查至少2人同行，全程客户陪同；禁止设备操作，采用外观检查＋资料核查」；计划制定要求年度计划审批后执行。","o":["现场检查应至少两人同行，并由客户全程陪同","检查中禁止操作客户设备，采用外观检查与资料核查的方式","用电检查人员可以单独一人前往客户现场开展常规周期检查","年度检查计划经审批后方可执行"]},{"i":299,"c":12,"t":2,"s":"根据重要用户分级管理规定，一级重要用户是指中断供电将可能产生下列（ ）后果之一的用电客户。","a":"ACDE","e":"考点：一级重要用户的界定后果。课件依据一级重要用户包括直接引发人身伤亡、造成严重环境污染、发生中毒爆炸或火灾、造成重大政治影响、重大经济损失及较大范围社会公共秩序严重混乱等情形；「造成一定范围社会公共秩序严重混乱」属于二级重要用户的情形。","o":["直接引发人身伤亡","造成一定范围社会公共秩序严重混乱","造成严重环境污染","发生中毒、爆炸或火灾","造成重大经济损失"]},{"i":300,"c":12,"t":2,"s":"关于重要客户自备应急电源的配置与管理要求，下列说法正确的有（ ）。","a":"BCD","e":"考点：重要客户自备应急电源配置要求。课件依据：「自备应急电源配置容量标准应达到保安负荷的120%」，故A错误；启动时间、闭锁防倒送电、签订安全使用协议后投入使用等均为规定要求。","o":["自备应急电源配置容量达到保安负荷的60%即满足标准要求","自备应急电源启动时间应满足安全要求","自备应急电源与电网电源之间应装设可靠的电气或机械闭锁装置，防止倒送电","重要客户自备电源不得私自并网，应与供电企业签订《客户自备电源安全使用协议》后方可投入使用"]},{"i":437,"c":12,"t":2,"s":"重要客户管理工作应遵循的原则包括（　）。","a":"ABCD","e":"考点：重要客户管理的原则。依据：「重要客户管理＝政府主导、责任明确、分级管理、重点保障」。“效益至上”不属于该项管理原则。","o":["政府主导","责任明确","分级管理","重点保障","效益至上"]},{"i":495,"c":12,"t":2,"s":"新修订的《供电营业规则》规定，供电企业应当无歧视地向用户提供供电服务。下列关于履行供电服务责任依据的说法，正确的有（　）。","a":"AB","e":"新增条款明确供电企业无歧视地向用户提供供电服务，并按照电力体制改革的要求和电力市场交易规则履行相应的服务责任；企业内部考核规定和个别用户的特殊诉求都不是履责依据。","o":["按照国家电力体制改革的要求","按照电力市场交易规则","按照供电企业内部的考核规定","按照个别用户提出的特殊诉求"]},{"i":497,"c":12,"t":2,"s":"窃电用户拒绝承担窃电责任的，供电企业应报请（　）依法处理。","a":"BC","e":"窃电者拒不接受处理的，应报请电力管理部门和公安部门依法处理；供电企业没有行政处罚权，也不能提请纪检监察或市场监管部门处理窃电案件。","o":["纪检监察部门","电力管理部门","公安部门","市场监督管理部门"]},{"i":501,"c":12,"t":2,"s":"根据《供电营业规则》关于窃电量确定的规定，下列说法正确的有（　）。","a":"AB","e":"窃电量可按私接设备额定容量乘以窃电时间计算，也可按计费电能表标定电流值所指容量乘以实际窃用时间计算；窃电时间无法查明时，窃电日数至少按180天计算，不按自报时间或“减半”估算。","o":["私接用电设备的，可按私接设备额定容量乘以实际使用时间确定窃电量","其他方式窃电的，可按计费电能表标定电流值所指容量乘以实际窃用时间确定窃电量","窃电时间无法查明时，窃电日数按窃电用户自报的时间确定","窃电量一律按上月用电量减半确定"]},{"i":597,"c":12,"t":2,"s":"按照课程归纳，作为“重要客户”应具备的条件包括（　）。","a":"ABC","e":"考点：重要客户的界定条件。笔记依据：「重要客户条件：重要地位、中断供电后果严重、对供电可靠性有特殊要求的用电场所」。","o":["用电场所在国家或社会中具有重要地位","中断供电后果严重","对供电可靠性有特殊要求","用电量在当地排名靠前"]},{"i":714,"c":12,"t":2,"s":"依据《供电营业规则》开展窃电费用追缴时，按不同类型的窃电行为应分别计算的内容包括（　）。","a":"ABC","e":"考点：窃电处理中费用追缴的计算口径。课件原文：“根据《供电营业规则》的相关规定，按不同类型的窃电行为分别计算追补电量、电费和违约使用电费。”","o":["追补电量","追补电费","违约使用电费","客户受电设备的折旧费"]},{"i":715,"c":12,"t":2,"s":"查处窃电的处理工作中，下列做法符合课件要求的有（　）。","a":"ACD","e":"考点：窃电处理的现场工作要点。课件载明工作内容包括“汇总相关证据，对相关设备进行封印封存”“告知用户在规定时间内进行窃电处理”，注意事项为“拒不整改→中止供电”，并无强行拆除全部受电装置的要求。","o":["汇总相关证据，对相关设备进行封印封存","当场强行拆除用户全部受电装置","告知用户在规定时间内进行窃电处理","用户拒不整改时中止供电"]},{"i":301,"c":12,"t":3,"s":"只要取得了用电检查证，用电检查人员就可以越级、超区到任意电压等级和任意区域的客户处开展用电检查。","a":"错","e":"考点：用电检查人员资质管理。课件依据：「按持证等级在指定区域内规定的电压等级客户从事用电检查，不得越级、超区开展检查」，资质信息变更还应及时更新。"},{"i":302,"c":12,"t":3,"s":"供用电安全责任按照“产权归谁，责任归谁”的原则界定，电力客户对其产权设施的安全负责。","a":"对","e":"考点：用电检查工作的核心原则——产权责任划分。课件依据：「供用电安全责任按照‘产权归谁，责任归谁’的原则界定，电力客户对其产权设施的安全负责」。"},{"i":303,"c":12,"t":3,"s":"窃电查处完成后，经现场确认窃电行为已消除，且窃电用户已接受处理并整改的，可对该用户恢复送电。","a":"对","e":"考点：窃电查处后恢复送电的条件。课件依据：「窃电查处完成后，经现场确认窃电行为已消除，窃电用户已接受处理并整改，可对窃电用户恢复送电」。"},{"i":304,"c":12,"t":3,"s":"新修订的《供电营业规则》保留了电费违约金不足1元者按1元收取的规定。","a":"错","e":"考点：营业电费规则的修订要点。课件依据：「删除了电费违约金不足1元者按1元收取的规定，实行据实结算」。"},{"i":305,"c":12,"t":3,"s":"在管理国家事务中具有特别重要作用、中断供电将可能危害国家安全的用电客户，属于一级重要用户。","a":"错","e":"考点：重要用户的分级界定。课件依据：「特级重要用户是指在管理国家事务中具有特别重要作用，中断供电将可能危害国家安全的用电客户」，并非一级重要用户。"},{"i":445,"c":12,"t":3,"s":"电是一种特殊商品，其生产（发电）、输电、供电、用电是在同一瞬间完成的。","a":"对","e":"考点：电能商品的即时性特征。依据：「电是发、输、供、用同一瞬间完成的特殊商品」，决定了电力产销必须实时平衡。"},{"i":446,"c":12,"t":3,"s":"对严重威胁电力系统和人身安全的用电安全隐患，在隐患消除前不得向客户送电。","a":"对","e":"考点：重大用电隐患的处置底线。依据：「严重威胁系统和人身安全的隐患，消除前不得送电」。"},{"i":447,"c":12,"t":3,"s":"用电安全隐患按照危害程度分为重大隐患和一般隐患两级。","a":"对","e":"考点：用电安全隐患的分级。依据：「用电安全隐患＝重大＋一般」，分级便于差异化管控与整改。"},{"i":448,"c":12,"t":3,"s":"重要客户自备应急电源的检查周期为：一级及以上重要客户每半年检查一次，二级重要客户每年检查一次。","a":"对","e":"考点：自备应急电源的周期检查要求。依据：「一级以上半年查一次、二级一年查一次」，且配置容量应达到保安负荷的120%。"},{"i":470,"c":12,"t":3,"s":"用电检查应当以事实为依据，以国家有关电力供应与使用的法律法规以及国家和电力行业的标准为准则。（　）","a":"对","e":"这是用电检查工作的基本准则：查清事实，依照法律法规和国家标准、行业标准开展检查。"},{"i":502,"c":12,"t":3,"s":"旧版《供电营业规则》中“本规则应放置在供电企业的用电营业场所”的规定，在新修订版本中被完全删除。（　）","a":"错","e":"该条款并未被删除，而是经过修改后移入新规则的相应条款，并增加了主动公开和线上渠道公告的要求；答题时应注意“删除”与“修改”的区别。"},{"i":504,"c":12,"t":3,"s":"处理窃电现场时，应要求窃电用户落实防窃电改造措施。（　）","a":"对","e":"查处窃电时应同步要求窃电用户进行防窃电改造，从技术上防止同类问题再次发生。"},{"i":505,"c":12,"t":3,"s":"窃电数额较大或情节严重的，供电企业可以直接追究窃电者的刑事责任。（　）","a":"错","e":"供电企业只能提请司法机关依法追究刑事责任；追究刑事犯罪的权力专属于司法机关，供电企业无权“直接追究”。"},{"i":506,"c":12,"t":3,"s":"重要客户名单确定后，无须向任何部门备案。（　）","a":"错","e":"重要客户名单确定后应报当地电力监管机构备案，实行名录化管理，不得秘而不报。"},{"i":507,"c":12,"t":3,"s":"重要客户的自备应急电源与电网电源之间，应装设可靠的电气或机械闭锁装置，防止倒送电。（　）","a":"对","e":"为防止自备应急电源向电网倒送电而危及人身和设备安全，两种电源之间必须装设可靠的电气或机械闭锁装置。"},{"i":508,"c":12,"t":3,"s":"涉及重要客户的线路检修停电，提前3天通知重要客户即可。（　）","a":"错","e":"涉及重要客户的停电检修，应按规定提前7天通知重要客户，以便客户提前安排应急保安措施。"},{"i":509,"c":12,"t":3,"s":"对重要客户应实行“一户一册”档案管理，并纳入营销系统统一管理。（　）","a":"对","e":"重要客户实行“一户一册”档案管理并纳入营销系统统一管理，便于动态掌握客户供电保障情况。"},{"i":608,"c":12,"t":3,"s":"《供电监管办法》于2009年11月26日发布，并自发布之日起施行，其后于2024年1月4日修订。","a":"错","e":"考点：《供电监管办法》的发布与施行时间。笔记依据：「2009.11.26发布，2010.1.1起施行，2024.1.4修订」，并非自发布之日起施行。"},{"i":306,"c":13,"t":1,"s":"按照电压等级对用户进行划分，采用（　）及以上电压等级供电的工业、大型商业用户称为高压用户。","a":"B","e":"考点：客户分类之电压等级划分。课件依据：「高压用户：如10kV及以上电压等级供电的工业、大型商业用户」，220V/380V供电的居民、小商户则为低压用户。","o":["1kV","10kV","35kV","110kV"]},{"i":307,"c":13,"t":1,"s":"营销系统客户三户模型中，（　）是指与供电企业建立电费结算关系的组织或个人，用于记录用电户主体的电费结算相关信息。","a":"C","e":"考点：三户模型的构成与定位。课件依据：「结算户：与供电企业建立电费结算关系的组织或个人」；客户为统领对象，用电户承载业务关系。","o":["客户","用电户","结算户","档案户"]},{"i":308,"c":13,"t":1,"s":"为客户办理新装、增容、变更用电及相关业务手续的全过程管理，称为（　）。","a":"A","e":"考点：业扩（业务扩充）的定义。课件依据：「业扩的工作范畴（全称业务扩充）是指为客户办理新装、增容、变更用电及相关业务手续的全过程管理」，其核心目标是实现客户用电需求的受理、审查、实施及后续服务。","o":["业务扩充","变更用电","电费复核","电能计量"]},{"i":309,"c":13,"t":1,"s":"低压客户业扩时限要求规定，无电力外线工程的低压新装用电业务应在（　）个工作日内完成接火送电。","a":"B","e":"考点：低压业扩流程时限。课件依据：「低压时限要求：无电力外线工程5个工作日内、有电力外线工程15个工作日内」。","o":["3","5","10","15"]},{"i":310,"c":13,"t":1,"s":"高压客户业扩流程中，答复供电方案的时限为：单电源不超过10个工作日，双电源不超过（　）个工作日。","a":"C","e":"考点：高压业扩各环节时限。课件依据：「答复供电方案：单电源10个工作日、双电源20个工作日」；另有业务受理1个工作日、设计审查3个工作日、中间检查2个工作日、竣工检验及装表6个工作日。","o":["5","15","20","30"]},{"i":311,"c":13,"t":1,"s":"按照95598投诉下单标准，执行欠费停电的用户缴费后多少小时及以上（以系统缴费记录为准）仍未复电的，符合“欠费复电”投诉下单场景？","a":"A","e":"考点：投诉下单“欠费复电”场景的判定标准。课件依据：「缴费后12小时及以上（以系统缴费记录为准），客户反映仍未复电」。","o":["12小时","6小时","8小时","24小时"]},{"i":312,"c":13,"t":1,"s":"投诉人对投诉办理结论存在异议，可以通过设置的专门救济渠道提出申诉的工单类型是（　）。","a":"D","e":"考点：12398投诉处理办法特有的异议申诉环节。课件依据：「此章为投诉人设置了专门救济途径，投诉人可以向12398平台进行申诉，投诉人申诉事项实行属地管理原则，由申诉事项发生地属地派出机构统一调查处理」。","o":["95598投诉工单","95598举报工单","业扩工单","12398能源监管热线投诉工单"]},{"i":313,"c":13,"t":1,"s":"客户投诉举报处置总体遵循“六步法”，其中居于首位、要求第一时间联系客户的是（　）。","a":"D","e":"考点：投诉举报处置“六步法”。课件依据：「客户投诉举报处置总体遵循“六步法”，即：速联系、态度好、讲明白、马上办、给预期、常走访」。","o":["讲明白","态度好","常走访","速联系"]},{"i":407,"c":13,"t":1,"s":"按照95598业务处理时限要求，故障报修工单的处理时限为（　）。","a":"D","e":"考点：客服业务的处理时限。依据：「故障报修处理时限＝24小时」，注意与投诉举报首联1小时的时限相区分。","o":["4小时","12小时","48小时","24小时"]},{"i":408,"c":13,"t":1,"s":"对客户反映的投诉、举报工单，完成首次联系客户的时间要求是不超过（　）。","a":"B","e":"考点：投诉与举报工单的首联时限。依据：「投诉与举报首联＝1小时」，高于一般咨询查询类工单的时限要求。","o":["30分钟","1小时","6小时","24小时"]},{"i":578,"c":13,"t":1,"s":"营销系统客户三户模型中，“用电户”是在什么情况下生成的？","a":"D","e":"考点：三户模型各主体的生成时机。笔记依据：「用电户：依法建立供用电、购售电关系后产生的实体……计量装置安装完成后生成」。","o":["客户通过渠道触点成功受理业务后","与供电企业建立电费结算关系时","该客户第一次缴纳电费后","依法建立供用电、购售电关系后，其计量装置安装完成时"]},{"i":314,"c":13,"t":2,"s":"下列选项中，属于客户服务八大业务类型的有（　）。","a":"ACD","e":"考点：客服工单八大业务类型。课件依据：八大业务类型分别为投诉、举报、意见、建议、业务办理、故障报修、咨询查询、表扬；业扩报装属于投诉下单场景之一，不在业务类型之列。","o":["投诉","业扩报装","表扬","举报"]},{"i":315,"c":13,"t":2,"s":"依据客户服务业务类型的界定，下列属于“举报”业务受理情形的有（　）。","a":"ABCD","e":"考点：举报业务的界定。课件依据：「检举和反映违约供（用）电、窃电、盗窃破坏电力设施等侵害企业或客户权益的行为」「检举供电企业行风」。","o":["检举和反映违约用电行为","检举和反映窃电行为","检举和反映盗窃破坏电力设施的行为","检举供电企业行风"]},{"i":316,"c":13,"t":2,"s":"根据业扩业务分类，下列属于变更用电类项目的有（　）。","a":"BCD","e":"考点：业扩三大类型与变更用电项目的区分。课件依据：业务扩充分为新装、增容、业务变更，变更用电包括减容、暂停、暂换、移表、更名过户、销户、改类、分户、并户、合同变更等，增容与变更用电并列而非其子项。","o":["增容","销户","移表","暂停"]},{"i":317,"c":13,"t":2,"s":"受理低压非居民客户（租赁经营户）的新装用电业务时，供电企业应采取有效措施防范电费回收风险，下列属于相应防范措施的有（　）。","a":"ABC","e":"考点：租赁经营户报装的电费回收风险防控。课件依据：「（1）提供产权人担保，签订《客户电费担保书》；（2）签订供用电合同电费分期预付条款；（3）装设售电管理装置」。","o":["提供产权人担保，签订《客户电费担保书》","签订供用电合同电费分期预付条款","装设售电管理装置","将租赁经营户列为差异服务客户"]},{"i":318,"c":13,"t":2,"s":"办理低压居民分布式光伏发电项目并网申请时，客户需准备的资料包括（　）。","a":"ABDE","e":"考点：分布式光伏并网申请资料在不同项目类型中的区别。课件依据：低压居民项目需提供客户身份证明资料、项目拟建设地点的物业权属证明资料、并网接入申请表、银行账户资料等；“与电力用户签订的能源服务管理合同”（合同能源管理方式）属于低压非居民、中压分布式光伏项目的资料。","o":["客户身份证明资料","项目拟建设地点的物业权属证明资料","与电力用户签订的能源服务管理合同","银行账户资料及对应开户人身份证明资料","分布式光伏发电项目并网接入申请表"]},{"i":319,"c":13,"t":2,"s":"依据95598投诉下单标准，下列属于“投诉下单”七大场景的有（　）。","a":"ABD","e":"考点：投诉下单七大场景与不下投诉五大场景的区分。课件依据：投诉下单七大场景为「业扩报装、欠费复电、电压质量、频繁停电、明确投诉、重复抱怨、重复投诉」；公司启动应急期间属于不下投诉场景。","o":["业扩报装","频繁停电","重复投诉","公司启动应急措施期间"]},{"i":320,"c":13,"t":2,"s":"下列情形中，属于95598“不下投诉”五大场景的有（　）。","a":"AB","e":"考点：不下投诉五大场景。课件依据：「特殊客户、投诉主体非供电部门、匿名工单、公司启动应急期间、近一年内已有首次投诉」；电压质量问题持续3个月及以上、欠费复电缴费后12小时未复电均属投诉下单场景。","o":["客户要求匿名投诉，坐席引导后仍坚持匿名","客户明确表达投诉对象为物业、房产开发商等第三方单位，希望供电部门予以协助处理","客户反映电压质量问题影响工作生活已持续3个月以上","执行欠费停电的用户缴费后12小时仍未复电"]},{"i":321,"c":13,"t":2,"s":"《12398能源监管热线投诉处理办法》明确了能源企业投诉处理的考核指标，下列属于该考核指标的有（　）。","a":"ABCD","e":"考点：12398能源企业投诉处理指标共4个。课件依据：「投诉事项及时办结率、投诉事项办理满意率、投诉申诉率、申诉有责率」。","o":["投诉事项及时办结率","投诉事项办理满意率","投诉申诉率","申诉有责率","投诉事项当场办结率"]},{"i":322,"c":13,"t":2,"s":"地市供电企业甄别评估认定的“高需求客户”，包括的客户群体有（　）。","a":"ABC","e":"考点：用户性质分类中的高需求客户。课件依据：「高需求客户指对某类或某几类需求较高的、客户数量较大的客户群体，包括小微企业、集团客户、重点社区客户及各地市供电企业认为需要开展差异化服务的一般大客户」；一级重要客户属高可靠性客户范畴，一般由政府有关部门认定。","o":["小微企业","集团客户","重点社区客户","一级重要客户"]},{"i":595,"c":13,"t":2,"s":"公司供电服务围绕“五化”目标强化服务质量，下列属于“五化”内容的有（　）。","a":"ABCD","e":"考点：供电服务“五化”目标。笔记依据：「公司围绕『五化』目标（推动办电便捷化、供电高质化、用电绿色化、服务普惠化、监管协同化）……提升服务质量」。","o":["办电便捷化","供电高质化","用电绿色化","服务普惠化","服务收费最大化"]},{"i":596,"c":13,"t":2,"s":"客户诉求场景的应对遵循三大核心原则，它们是（　）。","a":"ABD","e":"考点：客户诉求应对的核心原则。笔记依据：「客户诉求场景的应对3大核心原则：快速响应、闭环管理、技术赋能」。","o":["快速响应","闭环管理","从严问责","技术赋能"]},{"i":323,"c":13,"t":3,"s":"销户不属于变更用电类业务。","a":"错","e":"考点：变更用电类业务的项目范围。课件依据：业务变更包括「减容、减容恢复、暂停……移表、更名过户、销户、改类……分户、并户、合同变更」，销户属于变更用电类业务。"},{"i":324,"c":13,"t":3,"s":"无电力外线工程的低压新装用电业务，无论是居民还是非居民用电，均要求5个工作日内完成接火送电。","a":"对","e":"考点：低压业扩时限要求。课件依据：「低压时限要求：无电力外线工程5个工作日内、有电力外线工程15个工作日内」，无外线情形不限居民或非居民均为5个工作日。"},{"i":325,"c":13,"t":3,"s":"一级、二级重要客户一般由地方人民政府有关部门认定。","a":"对","e":"考点：高可靠性客户（重要客户）的认定主体。课件依据：「一级、二级重要客户一般由地方人民政府有关部门认定」，重点关注客户才是除政府认定外由地市供电企业甄别评估确定。"},{"i":326,"c":13,"t":3,"s":"95598渠道的咨询查询、故障报修、业务办理、表扬工单，其派发及回复均须经过网级服务调度审核。","a":"错","e":"考点：须审核工单与直派工单的分类。课件依据：「咨询查询、故障报修、业务办理、表扬工单执行直派、直回高效流程，缩短服务链条」；须经网级服务调度审核的是投诉、举报、意见、建议工单。"},{"i":327,"c":13,"t":3,"s":"国家能源局公开发布的《12398能源监管热线投诉处理办法》和《12398能源监管热线举报处理办法》，自2025年1月1日起正式执行。","a":"对","e":"考点：两个办法的发布与施行时间。课件依据：两办法于2024年11月1日由国家能源局在网上公开发布，「并于2025年1月1日起正式执行」。"},{"i":462,"c":13,"t":3,"s":"首问负责制要求做到“内转外不转”，并由首问责任人全过程跟进客户诉求直至解决。","a":"对","e":"考点：首问负责制的内涵。依据：「首问负责制＝内转外不转＋全过程跟进」，防止客户诉求在内部环节之间被推诿。"},{"i":463,"c":13,"t":3,"s":"客户反映的电压质量问题持续3个月及以上，或12个月内停电达5次及以上的，属于重点投诉标准的情形。","a":"对","e":"考点：重点投诉标准的量化条件。依据：「电压质量持续3个月及以上；12个月停电5次及以上属于重点投诉标准」。"},{"i":328,"c":14,"t":1,"s":"根据课件对数字经济的界定，数字经济是继下列哪一组经济形态之后的又一主要经济形态？","a":"A","e":"考点：数字经济的定位。课件依据：「数字经济是继农业经济、工业经济之后的主要经济形态，是以数据资源为关键要素，以现代信息网络为主要载体，以信息通信技术融合应用、全要素数字化转型为重要推动力」的新经济形态。","o":["农业经济、工业经济","农业经济、服务经济","工业经济、知识经济","网络经济、虚拟经济"]},{"i":329,"c":14,"t":1,"s":"按课程对历次科技革命与产业变革的划分，关于第四次工业革命的核心技术与生产要素，下列表述正确的是？","a":"D","e":"考点：四次工业革命的演进对比。课件指出第四次工业革命（4.0）的核心技术是人工智能、大数据、5G/6G等，生产要素转变为算法+算力+数据，世界经济由工业经济迈向数字经济。","o":["核心技术：计算机、互联网、半导体；生产要素：数据+技术+信息","核心技术：电力、内燃机、化工技术；生产要素：能源（电力）+资本","核心技术：蒸汽机、纺织机械；生产要素：劳动力+资本","核心技术：人工智能、大数据、5G/6G等；生产要素：算法+算力+数据"]},{"i":330,"c":14,"t":1,"s":"南方电网公司在数字化转型历程中首创提出“数字电网”理念是在哪一年？","a":"B","e":"考点：南网数字化转型历程关键节点。课件依据：「2019年首创提出“数字电网”理念」，同年印发《公司数字化转型和数字南网建设行动方案（2019年版）》并成立全球首家数字电网研究院。","o":["2017年","2019年","2020年","2021年"]},{"i":331,"c":14,"t":1,"s":"南方电网公司“2421”数字化转型战略路径中，“2”所对应的两大基础是指？","a":"C","e":"考点：“2421”战略路径的内涵。课件依据：「夯实基础设施和数据资产‘两大基础’，强化‘四位一体’业务赋能，提升融通创新和安全保障‘两项能力’，繁荣‘内外联动、开放共享’数字生态」。","o":["技术平台与基础设施","融通创新能力与网络安全屏障","强化基础设施建设与加速数据资产流通","迈上数字电网新台阶与开创数字产业新格局"]},{"i":332,"c":14,"t":1,"s":"关于数字化与数智化的本质区别，课件给出的判断标准是？","a":"B","e":"考点：数智化的本质。课件指出数智化与数字化的本质区别在于判断权的转移：数字化像导航、方向盘在人手里，数智化像自动驾驶，系统自己感知、判断、行动，判断标准是「系统有没有在某个业务场景里，获得了不需要人批准就能做判断的权利」。","o":["是否叠加了大模型等AI工具","系统能否在业务场景中不需要人批准而自主感知、判断、行动，即判断权发生转移","数据总量是否达到PB级以上","组织结构是否由科层制改为事业部制"]},{"i":333,"c":14,"t":1,"s":"在人工智能关键四要素中，被称为人工智能的“发动机”、提供数据处理和运算能力的是？","a":"D","e":"考点：AI关键四要素的分工。课件依据：「算力是硬件支撑，数据是燃料基础，模型是技术核心，场景是价值靶心，而人才要素是贯穿始终的聚合枢纽」，其中算力相当于“发动机”。","o":["数据","模型","场景","算力"]},{"i":334,"c":14,"t":1,"s":"南方电网“大瓦特”模型体系中，已建成的3个L0基础大模型（底座模型）是指？","a":"A","e":"考点：“大瓦特”模型体系分层。课件依据：「已建成L0基础大模型3个（NLP、CV、多模态）」，同时输变配、市场营销等22个业务领域建有L1业务域大模型，L2层为场景模型。","o":["大瓦特-NLP、大瓦特-CV、大瓦特-多模态","大瓦特-语音、大瓦特-文本、大瓦特-图像","大瓦特-预测、大瓦特-科学计算、大瓦特-NLP","大瓦特-CV、大瓦特-预测、大瓦特-多模态"]},{"i":335,"c":14,"t":1,"s":"南方电网公司2023年发布的电鸿物联操作系统，其重要作用是？","a":"C","e":"考点：电力鸿蒙（电鸿）物联操作系统。课件依据：「破解海量电力终端互联互通和数据贯通问题，填补电力行业统一物联网操作系统空白」，并以开源模式打造“电鸿”物联生态。","o":["建成全国规模最大的云计算数据中心集群","实现南方区域电力现货市场的全覆盖运行","填补电力行业统一物联网操作系统空白，破解海量异构电力终端互联互通和数据贯通难题","替代电网GIS平台完成输电线路三维建模"]},{"i":336,"c":14,"t":1,"s":"南方电网公司加强数据资产统筹，围绕的两条主线是？","a":"B","e":"考点：数据资产统筹的两条主线。课件依据：「围绕‘责权利、量本利’两条主线……打造全域贯通、智能分析、高效供给、生态应用的全环节数据资产管理能力」。","o":["“数据要素化”与“数据资产化”","“责权利”与“量本利”","“定责”与“确权”","“供给侧”与“需求侧”"]},{"i":337,"c":14,"t":1,"s":"公司聚焦基层业务“找数难、用数难”等痛点构建“都匀范式”，其要营造的生态口号是？","a":"D","e":"考点：数据赋能基层的“都匀范式”。课件依据：按业务域和岗位向每一位基层员工开放数据目录，「营造‘人人都是数据分析师’生态，提升了全员数字化素养」。","o":["“人人都是开发工程师”","“人人都是产品经理”","“业务与技术彻底分离”","“人人都是数据分析师”"]},{"i":338,"c":14,"t":1,"s":"据课件引用，麦肯锡的分析报告显示企业数字化转型的成功率仅为多少？","a":"A","e":"考点：数字化转型的失败率背景。课件依据：「麦肯锡的一份分析报告也表示，企业数字化转型的成功率仅为20%」；另据《2021中国企业数字转型指数研究》，2021年我国数字化转型效果显著的企业只有16%。","o":["约20%","约16%","约35%","约50%"]},{"i":339,"c":14,"t":1,"s":"根据南方电网关于数字化转型的基本认识，数字化转型的核心驱动是？","a":"C","e":"考点：数字化转型“九个基本认识”的对应关系。课件依据：「转型的核心驱动是数据要素」；此外，转型的成败关键是业技融合，根本目标是创造价值，本质是涉及生产力与生产关系重构的系统性变革。","o":["体制机制","人才队伍建设","数据要素","平台化、中台化建设"]},{"i":420,"c":14,"t":1,"s":"数字化转型的“几大转变”包括转意识、转路径、转方法、转组织、转文化。下列不属于其中内容的是（　）。","a":"C","e":"考点：数字化转型“几大转变”的内容。依据：「数字化转型几大转变＝转意识、转路径、转方法、转组织、转文化」，并无“转产能”之说。","o":["转意识","转方法","转产能","转文化"]},{"i":568,"c":14,"t":1,"s":"南方电网公司数字化转型顶层设计的演进路径，正确的顺序是（　）。","a":"B","e":"考点：南网数字化转型顶层设计的演进。笔记依据：「顶层设计演进：4321→4321+→2421→数智电网2243（十五五），推动公司全方位由『数字化』向『数智化』跃迁」。","o":["2421→4321→数智电网2243→4321+","4321→4321+→2421→数智电网2243","数智电网2243→2421→4321→4321+","4321→2421→4321+→数智电网2243"]},{"i":569,"c":14,"t":1,"s":"南方电网公司围绕数据“盘、规、治、用”打造数据管理核心能力，其中“盘”是指（　）。","a":"B","e":"考点：数据资产流通中“盘、规、治、用”的含义区分。笔记依据：「盘：筑数据之基，汇全域之数：构建云数一体的底座式数据中心」。","o":["建治理机制，优数据服务","筑数据之基，汇全域之数，构建云数一体的底座式数据中心","以自助分析工具打造一站式找数、看数、用数工作台","围绕责权利、量本利两条主线创新数据资产管理体系"]},{"i":783,"c":14,"t":1,"s":"据课件，南方电网西电东送已形成“八条交流、十一条直流”共19条500千伏及以上大通道，其送电规模超过（　）。","a":"D","e":"课件载明：「西电东送已形成『八条交流、十一条直流』19条500千伏及以上大通道，送电规模超过5800万千瓦」，公司是国家西电东送战略的实施主体。","o":["2800万千瓦","3800万千瓦","4800万千瓦","5800万千瓦"]},{"i":786,"c":14,"t":1,"s":"按照南方电网数字化转型历程，公司基本完成数字化转型的时间节点是（　）。","a":"B","e":"转型历程时间轴载明：「2023年12月基本完成数字化转型」；2024年12月广东、深圳率先完成国资委数字化转型试点企业建设，2025年12月全面完成数字化转型。","o":["2022年5月","2023年12月","2024年12月","2025年12月"]},{"i":788,"c":14,"t":1,"s":"数智电网“2243”总体框架中，锚定的“3个能力”是指（　）。","a":"C","e":"「2243」总体框架为：夯实2大基础、做强2大平台、升级为「数智电网、数智运营、数智服务、数智产业」4个数智、锚定「3个能力：融通创新、本质安全、生态服务」。","o":["融通创新、网络安全、共享服务","本质安全、数据驱动、开放共享","融通创新、本质安全、生态服务","自主创新、生产安全、市场服务"]},{"i":790,"c":14,"t":1,"s":"据课件，南方电网公司数据资源丰富多元，其数据总量已超过（　）。","a":"C","e":"课件指出公司数据资源「包括了电网生产运行、经营管理数据、五省（区）政府授权能源行业数据、外部接入气象、卫星遥感和经济运行等数据，总量超过27PB」。","o":["7PB","17PB","27PB","37PB"]},{"i":791,"c":14,"t":1,"s":"2022年5月，公司在国家数据管理能力成熟度评估（DCMM）中高分获评最高等级优化级（5级），成为全国第（　）家获评该最高等级的单位。","a":"C","e":"课件载明：2022年5月9日高分获评国家数据管理能力成熟度评估最高等级优化级（5级），「成为全国第三家获评数据管理能力成熟度最高等级的单位」，下属各省公司整体达到四级以上水平。","o":["一家","两家","三家","五家"]},{"i":793,"c":14,"t":1,"s":"在南网电网智能规划应用中，利用（　）技术智能生成规划方案，实现了负荷智能切割、新出线智能并网、路径智能寻优。","a":"B","e":"课件指出电网智能规划针对线路重过载、线路大分支等网架问题，「利用强化学习技术智能生成规划方案，实现负荷智能切割、新出线智能并网、路径智能寻优」，在满足多种安全约束条件下求成本最优方案。","o":["专家经验规则","强化学习","线性回归拟合","人工逐案校核"]},{"i":794,"c":14,"t":1,"s":"能源行业首个“大瓦特APP”支持的双模型切换模式是（　）。","a":"A","e":"课件介绍：「大瓦特APP支持72B快答、671B深析模型切换，具备深度思考、内外网融合搜索、语音转写与翻译、自动提炼会议重点并生成会议纪要等核心能力」。","o":["72B快答与671B深析","小模型速答与大模型精算","端侧速答与云端深思","文本问答与语音问答"]},{"i":340,"c":14,"t":2,"s":"先进企业在数字化转型进程中形成了“八大重点”，下列属于其中内容的有？","a":"ABC","e":"考点：数字化转型“八大重点”。课件列举了以用户为中心、具备良好的数据基础、重视生态协作共享、重视自主创新、明确的转型实施路径、建设数字化人才队伍、一把手工程、业务与技术双驱动八项重点，D项与之相悖。","o":["坚持一把手工程，由一把手抓总、亲自部署推动落实","以用户为中心，以客户体验和一线感知为中心提升用户体验","具备良好的数据基础，重视数据治理与数据管理","大幅压减信息化投入，推迟新技术应用节奏"]},{"i":341,"c":14,"t":2,"s":"数字化部作为公司数字化转型统筹推进部门，要强化“五个统筹”，下列属于“五个统筹”内容的有？","a":"ACD","e":"考点：数字化部“五统筹”。课件依据：「统筹全业务数字化规划与实施、统筹全领域数字化技术管控、统筹数字化基础设施和平台建设、统筹全环节数据管理、统筹全方位安全运行」。B项不属于。","o":["统筹全业务数字化规划与实施","统筹所属各单位干部人事任免","统筹数字化基础设施和平台建设","统筹全环节数据管理"]},{"i":342,"c":14,"t":2,"s":"在企业数智化推进过程中，多数企业易陷入表面化、形式化的认知误区，课件概括的“四大认知错位”包括？","a":"ABCD","e":"考点：数智化四大认知错位。课件依据：「集中体现为：仅停留于改名层面、认为‘AI工具即数智化’、认为‘数字化和数智化是串行关系’、认为‘一把手重视即能实现数智化’等」。","o":["只改名、不升级，未改变“人定规则、人做决策、系统执行”的底层逻辑","只加AI、不换逻辑，简单叠加大模型而未改变原有决策链路","陷入串行思维误区，错误认为数智化是数字化的后续阶段、必须先完成数字化再推进数智化","落入“一把手工程”误区，仅靠行政权威强推而忽视考核机制、权责分配等制度配套"]},{"i":343,"c":14,"t":2,"s":"课件指出数智化转型工作推进过程中真正的困境在于愿意让出判断权、愿意信任算法、组织愿意重新分配权力，并将落地障碍概括为“三大硬骨头”，它们是？","a":"ACD","e":"考点：数智化落地的三大障碍。课件依据：“利益冲突、信任缺失、能力断层”三大硬骨头——如数据驱动的决策可把经验决策失误率从42%降到14%，但动摇了管理者依赖经验的价值，且存在一线人员不信任算法的困境。","o":["能力断层","算力供给不足","信任缺失","利益冲突"]},{"i":344,"c":14,"t":2,"s":"“十五五”期间，公司在原有框架基础上形成数智电网“2243”总体框架，其中要夯实的“2大基础”是指？","a":"BC","e":"考点：“2243”总体框架。课件依据：「夯实‘2大基础’：通感算控一体化新型数字基础设施、数据要素发展基础；做强‘2大平台’：具备共享、孪生特征的企业级中台、企业级技术平台」。A项属于“2大平台”，D项与课件无关。","o":["具备共享、孪生特征的企业级中台与企业级技术平台","通感算控一体化新型数字基础设施","数据要素发展基础","全域覆盖的固定电话通信网络"]},{"i":345,"c":14,"t":2,"s":"课件围绕数据资产管理提出了六个重点，下列属于这六个重点的有？","a":"ABD","e":"考点：数据资产管理的六个重点。课件依据：「定责：决定数据管理边界；确权：构建业务可为空间；享利：明确利益分配规则；拓量：拓展业务发展规模；优本：指导数据收益测算；创利：促进数据价值变现」。","o":["定责","确权","优化组织机构编制","优本"]},{"i":346,"c":14,"t":2,"s":"南方电网输电智能巡视经历了“人巡—机巡—智巡”三个发展阶段，下列说法正确的有？","a":"AB","e":"考点：输电智能巡视三阶段。课件依据：人巡（2013年以前）工作量大危险性高；机巡（2013-2017）“机器替代手脚，巡视效率提升2~3倍以上”；智巡智瞰（2018-至今）实现「“人工智能识别为主、人工复核为辅”」「提升4-5倍」。","o":["机巡阶段人工操控无人机巡检，巡视效率较人巡提升2~3倍以上，基本实现“机巡为主、人巡为辅”","智巡阶段基于“云边协同”的AI识别算法对照片集中智能缺陷分析，效率较人巡提升4-5倍","机巡阶段即已实现“人工智能识别为主、人工复核为辅”","智巡阶段的巡检效率反而低于人巡阶段"]},{"i":347,"c":14,"t":2,"s":"在开创数字产业新格局方面，南方电网公司取得的标志性成果包括？","a":"ABCD","e":"考点：数字产业重大成果体系。课件依据：「形成‘云’‘智’‘传奇’系列产品体系……自主研制首款全国产化电力专用主控芯片‘伏羲’并实现量产……‘大瓦特·驭电’获评世界人工智能大会最高奖……系统打造‘赫兹数智’数据产品品牌」。","o":["自主研制首款全国产化电力专用主控芯片“伏羲”并实现量产，入选央企十大“国之重器”","“大瓦特·驭电”获评世界人工智能大会最高奖、入选央企十大“国之重器”","打造“赫兹数智”数据产品品牌，建成数百个在运数据产品","构建“极目”系列传感器，覆盖输电、变电、配电、新能源及碳排放监测等场景"]},{"i":348,"c":14,"t":2,"s":"南方电网“大瓦特”模型体系按层级化方式构建，该体系包含的层级有？","a":"BCD","e":"考点：“大瓦特”模型体系架构。课件依据：「构建行业领先的‘大瓦特’模型体系，已建成L0基础大模型3个……22个业务领域L1业务域大模型24个，智能巡检、智能客服、人资小智等L2场景模型95个，小模型1606个」。课件未设L3层级。","o":["L3跨域超级大模型","L0通用大模型（基础大模型）","L1垂域大模型（业务域大模型）","L2场景大模型"]},{"i":349,"c":14,"t":2,"s":"关于AI在南网各业务领域的赋能成效，下列说法正确的有？","a":"ABC","e":"考点：AI业务赋能成效数据。课件依据：「高频咨询查询类业务机器代人率超过80%」「无人机精细化巡检图像分析超9000万张，算法平均发现率超过93%、准确率超过70%」及负荷预测三项提升指标。D项说法绝对化，与课件不符。","o":["营销领域：网级95598智能客服实现高频咨询查询类业务机器代人率超过80%","输配电领域：输、变、配电无人机精细化巡检图像分析超9000万张，算法平均发现率超过93%","调度领域：近三年AI综合负荷预测准确率相对于人工预测分别提升1.05%、0.97%、0.12%","客服领域：机器代人率已达到100%，人工坐席全部取消"]},{"i":350,"c":14,"t":2,"s":"关于南方电网人工智能运营机制，下列说法正确的有？","a":"ABD","e":"考点：人工智能“赛马”“揭榜挂帅”机制。课件依据：算法赛马「优胜者直接中标，并在生产环境落地应用，避免传统招投标的逆向选择风险」，可见C项错误。","o":["创新算力“赛马”机制，赛马成绩纳入算力采购参考，牵引自主可控算力性能提升","算法研发优先采用“赛马”方式公开竞争遴选优质算法，以自研方式为重要补充","所有算法一律通过传统招投标方式确定承担单位","场景建设按照“场景赛马—揭榜挂帅—责任签订—实施评审—推广应用”的步骤统筹推进"]},{"i":351,"c":14,"t":2,"s":"基于电力大模型的智能客服系统攻克多项技术难题，研发了五大功能模块，下列属于这五大模块的有？","a":"ACD","e":"考点：电力智能客服系统的构成。课件依据：「研发智能机器人、智能客服助手、智能质检、智能外呼、智能知识库等五大模块……高频咨询查询类业务机器代人率超过80%」。“智能抄表核算机器人”不属于其中。","o":["智能机器人","智能抄表核算机器人","智能质检","智能知识库"]},{"i":435,"c":14,"t":2,"s":"南方电网“2421”数字化转型战略路径中的“四位一体”业务赋能包括（　）。","a":"ABCD","e":"考点：“四位一体”的构成。依据：「四位一体＝数字电网、数字服务、数字运营、数字产业」，数字金融不在其中。","o":["数字电网","数字服务","数字运营","数字产业","数字金融"]},{"i":598,"c":14,"t":2,"s":"数智化推进的五大行动原则包括下列各项中的（　）。","a":"ABCD","e":"考点：数智化五大行动原则。笔记依据：「数智化五大行动原则：界定判断权边界、以场景验证价值、重构判断权分配、接受并行推进迭代、建立长期机制」；E项恰是应摒弃的串行思维误区。","o":["界定判断权边界","以场景验证价值","重构判断权分配","建立长期机制","先彻底完成数字化之后再启动数智化"]},{"i":599,"c":14,"t":2,"s":"数智化建设提出“五转”要求，下列属于其中的有（　）。","a":"ABDE","e":"考点：数智化建设“五转”。笔记依据：「数智化建设『五转』：转意识、转组织、转方法、转模式、转文化」；“转技术”不在其中。","o":["转意识","转组织","转技术","转方法","转文化"]},{"i":600,"c":14,"t":2,"s":"用好AI创造价值，应瞄准的方向包括（　）。","a":"ABC","e":"考点：AI创造价值的三个方向。笔记依据：「用AI创造价值，瞄准3个方向：生产力提升、防控关键风险、效率和体验提升」。","o":["生产力提升","防控关键风险","效率和体验提升","以AI全面替代一线员工"]},{"i":785,"c":14,"t":2,"s":"依据课件，数字经济的主要组成部分包括（　）。","a":"ACDE","e":"课件将数字经济划分为「数字产业化、产业数字化、数字化治理、数据价值化」四大部分；现代信息网络是数字经济「以现代信息网络为主要载体」中的载体，而不是其组成部分。","o":["数字产业化","现代信息网络","产业数字化","数字化治理","数据价值化"]},{"i":787,"c":14,"t":2,"s":"“4321+”总体规划蓝图中，企业级中台包括（　）。","a":"ABDE","e":"「4321+」蓝图明确的「1个中台——企业级中台」由「业务中台、技术中台、数据中台、安全中台」构成；国家工业互联网平台属于对接方向，不属于企业级中台的构成。","o":["业务中台","技术中台","工业互联网平台","数据中台","安全中台"]},{"i":792,"c":14,"t":2,"s":"关于电力人工智能“大瓦特”体系的建设成效，下列说法正确的有（　）。","a":"ABCD","e":"课件指出：「形成训练算力集中、推理算力网省地分级的部署架构」「人工智能基础设施、算力芯片、学习框架国产化率均达到100%」，构建行业领先的大瓦特模型体系，年累计调用达到46.81亿次。","o":["建成电力行业最大国产算力集群","形成了行业最大样本库","所有模型实现统一上架、监控和管理，年累计调用达到46.81亿次","人工智能基础设施、算力芯片、学习框架国产化率均达到100%","推理算力全部集中于网级，不作分级部署"]},{"i":352,"c":14,"t":3,"s":"课件指出，数字化转型的本质是一场涉及生产力与生产关系重构的系统性变革。","a":"对","e":"考点：数字化转型“九个基本认识”。课件依据：「数字化转型的本质是一场涉及生产力与生产关系重构的系统性变革；转型的根本目标在于创造价值」。"},{"i":353,"c":14,"t":3,"s":"数字化和数智化是先后接替的串行关系，企业必须先彻底完成数字化之后才能启动数智化转型。","a":"错","e":"考点：数智化认知错位之“陷入串行思维误区”。课件依据：应「忽视两者可并行推进的核心逻辑」这一错误被明确列为认知误区，并提出“建立并行推进逻辑”的行动原则。"},{"i":354,"c":14,"t":3,"s":"2020年11月，南方电网公司发布了《数字电网白皮书》。","a":"对","e":"考点：南网数字化转型历程。课件在转型历程时间轴中载明：2020年11月发布《数字电网白皮书》，同年7月信息部更名为数字化部，12月南网“智瞰”“智搜”上线。"},{"i":355,"c":14,"t":3,"s":"南方电网公司的集团管控所有主营业务活动经对标评估，获得的是数字化转型成熟度三星级证书。","a":"错","e":"考点：南网数字化转型水平评级。课件依据：「南方电网公司获得数字化转型成熟度五星级评估证书」，评估依据为GB/T45341-2025等标准，广度对标供应链产业链（平台用户群）、深度对标数据驱动。"},{"i":356,"c":14,"t":3,"s":"与大模型相比，小模型参数量较小，具有推理速度快、算力要求低、便于端侧部署等特点，大模型与小模型相互配合、协同应用可构成更灵活的解决方案。","a":"对","e":"考点：大小模型协同。课件依据：「小模型广泛应用于边端侧相对简单的业务场景，相较大模型参数量小（约几百至千万），具有推理速度快、算力要求低、便于端侧部署等特点」。"},{"i":357,"c":14,"t":3,"s":"南网智搜致力于打造南方电网自己的“百度”，实现电网上下游新闻、数据、应用、知识、文档等数据的“应搜尽搜”。","a":"对","e":"考点：统一技术平台的能力组件。课件依据：「南网智搜：打造自己的‘百度’，实现电网上下游新闻、数据、应用、知识、文档等数据‘应搜尽搜’，消解用户‘找不到、用不了、看不懂’的难题」。"},{"i":358,"c":14,"t":3,"s":"在人工智能关键要素中，场景相当于人工智能的“大脑”，用于对数据进行学习和预测。","a":"错","e":"考点：AI四要素的比喻对应。课件依据：模型是人工智能的“大脑”，基于算法构建；场景是人工智能的“舞台”，为其提供应用空间，决定人工智能的需求与目标。"},{"i":461,"c":14,"t":3,"s":"南方电网数字化转型中的“4321”体系，是指4业务平台＋3基础平台＋2对接＋1云化数据中心。","a":"对","e":"考点：“4321”体系的构成。依据：「4321＝4业务平台＋3基础平台＋2对接＋1云化数据中心」，其后又演进形成“4321+”升级框架。"},{"i":614,"c":14,"t":3,"s":"目前南方电网西电东送已形成“八交十一直”（八条交流、十一条直流）的通道格局。","a":"对","e":"考点：西电东送通道格局。笔记依据：「西电东送：『八条交流、十一条直流』八交十一直」。"},{"i":615,"c":14,"t":3,"s":"南方电网公司以数字电网建设推进数字化、绿色化“两化协同”，促进新型电力系统、新型能源体系“两型建设”。","a":"对","e":"考点：南网数字化转型的战略导向。笔记依据：「以数字电网建设推进数字化、绿色化『两化协同』促进新型电力系统、新型能源体系『两型建设』为导向，形成了『2421』数字化转型战略路径」。"},{"i":616,"c":14,"t":3,"s":"南方电网公司以输配电业务为核心，锚定新型电力系统、新兴产业、优质供电三大板块，推进数字电网、数字运营、数字能源生态发展。","a":"对","e":"考点：南网业务布局的三大板块。笔记依据：「南网以输配电业务为核心，锚定新型电力系统、新兴产业、优质供电三大板块」。"},{"i":784,"c":14,"t":3,"s":"中国最南端的供电局——三沙供电局于2012年8月28日在西沙永兴岛成立。","a":"对","e":"课件在介绍公司基本情况时载明：「2012年8月28日，中国最南端的三沙供电局在西沙永兴岛成立」，公司供电服务覆盖广东、广西、云南、贵州、海南五省区和港澳地区。"},{"i":789,"c":14,"t":3,"s":"公司建立了网、省、地三级信息官（CIO）制度，并实行信息官“双汇报”工作机制。","a":"对","e":"课件在加强业技融合的举措中明确：「设置各级信息官，建立网、省、地三级信息官（CIO）制度，建立信息官『双汇报』工作机制」。"},{"i":795,"c":14,"t":3,"s":"公司联合华为、百度和商汤等厂商制定测评依据，创新算力“赛马”机制，为划定算力采购份额提供科学依据，牵引自主可控算力性能大幅提升至国内最好。","a":"对","e":"课件载明：「发挥龙头企业引领作用，联合华为、百度和商汤等厂商制定各方可接受的测评依据，创新算力『赛马』机制，为划定算力采购份额提供科学依据」，助力突破算力瓶颈。"},{"i":359,"c":15,"t":1,"s":"无线电能传输又称为非接触电能传输，依据课件，其含义是通过发射器将电能转换为其他形式的中继能量，隔空传输一段距离后，再通过接收器将中继能量转换为电能。下列不属于课件所列举的中继能量形式的是？","a":"C","e":"考查无线电能传输的定义要点。课件依据：「通过发射器将电能转换为其他形式的中继能量（如电磁场能、激光、微波、超声波等）」，化学能不在所列中继能量形式之中。","o":["电磁场能","超声波","化学能","微波"]},{"i":360,"c":15,"t":1,"s":"依据课件按传输距离对无线电能传输技术方式的划分，下列各组合中完全属于远场传输技术的是？","a":"B","e":"考查近场与远场技术的分类结论。课件依据：「磁场耦合式和电场耦合式属于近场传输，传输距离短；微波、激光属于远场传输技术，距离可达数千米。」","o":["磁场耦合式与电场耦合式","微波与激光","激光与电场耦合式","微波与磁场耦合式"]},{"i":361,"c":15,"t":1,"s":"依据课件，在各类无线电能传输技术中，目前发展最为成熟的是？","a":"D","e":"考查各类技术成熟度的结论性表述。课件依据：「该技术原理是目前发展最为成熟的无线电能传输技术」，指的是磁场耦合式技术。","o":["微波","电场耦合式","超声波","磁场耦合式"]},{"i":362,"c":15,"t":1,"s":"微波无线电能传输通过空间电磁波的定向辐射实现电能传输。依据课件，其发射侧的实现方式是？","a":"A","e":"考查微波无线电能传输的技术原理。课件依据：「采用功率放大器将输入的直流电放大为射频功率后，注入至原边发射天线」，其余选项分别为激光式、超声波式和电场耦合式的做法。","o":["采用功率放大器将输入的直流电放大为射频功率后，注入至原边发射天线","采用激光发生器发出特定波长激光，经光学发射天线集中整形后发射","采用超声波发生器将电能转化为特定波长的超声波，经声介质传输至接收端","将谐振补偿后的高频交流电注入原边耦合金属板"]},{"i":363,"c":15,"t":1,"s":"2020年至2022年，历时3年技术攻关研制成功的电力杆塔无线供电成套设备，依据课件其主要指标是？","a":"C","e":"考查电力杆塔无线供电成套设备的关键指标。课件依据：「成功研制了国内外首套35kV电压等级的电力杆塔无线供电成套设备，成套设备输出额定功率50W，无线传能最优效率达82.8%。」","o":["国内外首套10kV电压等级，输出额定功率30W，无线传能最优效率65.8%","国内外首套110kV电压等级，输出额定功率250W，无线传能最优效率90%","国内外首套35kV电压等级，输出额定功率50W，无线传能最优效率达82.8%","国内外首套10kV电压等级，输出额定功率120W，无线传能最优效率达82.8%"]},{"i":364,"c":15,"t":1,"s":"课件所述首创的基于无线充电的无人机高可靠补能技术，其高功率密度机载端模组达到的指标是？","a":"D","e":"考查无人机无线充电模组的先进性指标。课件依据：「机载端模组功率密度达到1.4W/g，无线充电效率高达91%」；效率85%、功率密度1.17W/g为国内外同类产品水平。","o":["无线充电效率85%，功率密度1.17W/g","无线充电效率88%，功率密度1.2W/g","无线充电效率90%，功率密度1.4W/g","无线充电效率高达91%，机载端模组功率密度达到1.4W/g"]},{"i":365,"c":15,"t":2,"s":"经过多年发展，无线电能传输技术已在多个领域快速应用并正向更广泛的领域渗透。依据课件，下列属于其快速应用的八大领域的是？","a":"ABCE","e":"考查无线电能传输应用领域的分类列举。课件依据：「在家用电子设备、智能家居、医疗设备、工业机器人、石油勘探、水下探测设备、交通和航空航天八大领域快速应用」，智慧农业不在所列八大领域中。","o":["家用电子设备","医疗设备","石油勘探","智慧农业","航空航天"]},{"i":366,"c":15,"t":2,"s":"在复杂恶劣环境下，输电线路取能与长气隙无线供电面临稳定性难题。依据课件，下列说法正确的有？","a":"ABCD","e":"考查线路取能与长气隙无线供电的技术挑战。课件依据：「宽电流范围下稳定取能范围窄」「低载流：取能功率不足」「高载流：磁芯饱和，磁导率下降，取能功率骤降」「长气隙：米级传输进一步削弱耦合，增加级数」，且110kV-500kV线路绝缘距离达1.3米-4米。","o":["宽电流范围下稳定取能的范围窄","低载流时取能功率不足，难以支撑设备运行","高载流时磁芯饱和、磁导率下降，取能功率骤降","米级长气隙传输进一步削弱耦合，线圈与金属交叉耦合还会加剧损耗","线路绝缘距离一般不超过0.5米，安全间距问题容易解决"]},{"i":367,"c":15,"t":2,"s":"针对米级多中继无线供电传输环节多、路径复杂、损耗大的难点，课件提出了多项措施协同提升整体传输效率。下列属于这些措施的是？","a":"ACD","e":"考查米级多中继无线供电的效率提升技术。课件依据：「提出“单级线圈分布补偿-多级能量路径调控-端部金属漏磁抑制”协同的效率提升技术，大幅提升整体传输效率」；多中继结构正是米级跨高压传能所需架构，不能简单取消。","o":["多级能量路径调控","取消中继线圈以缩短传输路径","端部金属漏磁抑制","单级线圈分布补偿"]},{"i":368,"c":15,"t":2,"s":"课件所述面向海缆巡视的常驻型水下自主巡检机器人成套装备，由下列哪些部分组成？","a":"BCD","e":"考查常驻型水下自主巡检机器人成套装备的组成。课件依据：成套装备由「水下无线传能基站」「海缆巡检AUV」「卫星通信岸基一体化管控平台」组成；采用「AUV+海底基站」模式的意义正在于摆脱对大型母船的依赖。","o":["大型水面母船保障系统","卫星通信岸基一体化管控平台","水下无线传能基站","海缆巡检AUV"]},{"i":369,"c":15,"t":2,"s":"课件指出，无人机巡检应用存在三大瓶颈问题，亟需系统性开展无人机全自主巡检关键技术研究及装备研制。这三大瓶颈是？","a":"ABD","e":"考查无人机巡检应用的瓶颈概括。课件依据：「无人机巡检应用存在“充电可靠性低-作业半径小-环境适应性差”等三大瓶颈问题」，具体表现为触头磨损氧化、一机巢一飞机、体积大重量重等。","o":["充电可靠性低","作业半径小","巡检影像识别精度不高","环境适应性差","机巢选址限制过多"]},{"i":370,"c":15,"t":2,"s":"关于无线电能传输技术的发展历程与荣誉评价，依据课件，下列说法正确的有？","a":"ABC","e":"考查无线电能传输的发展历程节点。课件依据：「1891年尼古拉特斯拉提出无线电能传输技术概念」「2008年WPC(无线充电联盟成立)，聚焦标准制定」；2012年为世界经济论坛十大新兴技术，2014年为《时代》周刊最具影响力发明，2015年为中国科协未来十大科研方向，D项年份张冠李戴。","o":["1891年，尼古拉·特斯拉提出了无线电能传输技术概念","2008年，WPC无线充电联盟成立，聚焦标准制定","该技术先后入选世界经济论坛十大新兴技术与《时代》周刊世界最具影响力的发明","中国科协“引领未来的十大科学技术”评选结果发布于2012年"]},{"i":371,"c":15,"t":3,"s":"依据课件，磁场耦合式技术原理是目前发展最为成熟的无线电能传输技术。","a":"对","e":"考查各类无线电能传输技术成熟度的比较。课件依据：「磁场耦合技术原理为：将工频交流电整流-高频逆变-谐振补偿后，注入发射线圈……该技术原理是目前发展最为成熟的无线电能传输技术。」"},{"i":372,"c":15,"t":3,"s":"依据课件，“一机巢一飞机”的设计便于不同型号无人机共用同一机巢，能够极大降低推广应用投资。","a":"错","e":"“一机巢一飞机”意味着机巢仅适配一款无人机，是课件指出的待突破现状而非优点。课件依据：「改变机巢与无人机“单一适配”现状，无人机与机巢可复用，极大降低推广应用投资」。"},{"i":373,"c":16,"t":1,"s":"根据课件，下列各项中不属于招标投标基本原则的是（　）。","a":"B","e":"考查招标投标基本原则的构成。课件依据：「程序高度透明，招标公告、公开开标、公开中标结果等（公开）；按同样的标准对待所有投标人，不偏不倚（公正）；给每个投标人均等的机会，不歧视和排斥任何潜在投标人（公平）；不得随意终止招标，不得弄虚作假，不得串通投标（诚实信用）。」基本原则为公开、公平、公正、诚实信用，不含“效益优先”。","o":["公正","效益优先","诚实信用","公开"]},{"i":374,"c":16,"t":1,"s":"依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于（　）。","a":"D","e":"考查依法必须招标项目的备标时间下限。课件依据：「依法必须进行招标的项目，自招标文件开始发出之日起至投标人提交投标文件截止之日止，最短不得少于二十日。」","o":["五日","十日","十五日","二十日"]},{"i":375,"c":16,"t":1,"s":"根据《招标投标法实施条例》，招标文件要求中标人提交履约保证金的，履约保证金不得超过中标合同金额的（　）。","a":"C","e":"考查履约保证金的比例上限。课件依据：「履约保证金不得超过中标合同金额的10%。」注意与投标保证金区分，后者不得超过招标项目估算价的2%。","o":["2%","5%","10%","20%"]},{"i":376,"c":16,"t":1,"s":"根据南方电网公司采购管理制度，由3个及以上符合资格条件的供应商一次报出不得更改的价格，经评审确定成交供应商的采购方式是（　）。","a":"A","e":"考查四种非招标采购方式的定义辨析。课件依据：「询比采购，是指由3个及以上符合资格条件的供应商一次报出不得更改的价格，经评审确定成交供应商的采购方式。」谈判采购是与2个及以上供应商分别谈判，竞价采购是多轮次公开竞争报价，直接采购为非竞争方式。","o":["询比采购","谈判采购","竞价采购","直接采购"]},{"i":377,"c":16,"t":1,"s":"根据南方电网公司制度，公司系统范围内工程建设项目施工单项合同估算价达到（　）人民币（含）以上的，必须进行招标。","a":"C","e":"考查公司系统必须招标的规模标准。课件依据：「施工单项合同估算价在400万元人民币（含）以上」必须招标；同条规定重要设备、材料等货物为200万元以上，勘察、设计、监理等服务为100万元以上。","o":["200万元","300万元","400万元","500万元"]},{"i":378,"c":16,"t":1,"s":"依法必须进行招标的项目，投标人对评标结果有异议的，应当在中标候选人公示期间提出，招标人应当自收到异议之日起（　）作出答复。","a":"B","e":"考查评标结果异议的答复时限。课件依据：「招标人应当自收到异议之日起3日内作出答复；作出答复前，应当暂停招标投标活动。」","o":["1日内","3日内","5日内","7日内"]},{"i":421,"c":16,"t":1,"s":"关于采购与招标之间的关系，理解正确的是（　）。","a":"B","e":"考点：采购与招标的概念层级。依据：「采购是大概念，招标是采购方式之一」，除招标外还有谈判、询比、竞价、直接采购等非招标方式。","o":["招标是大概念，采购是招标的方式之一","采购是大概念，招标是采购的方式之一","二者界限分明、互不隶属","一切采购活动都必须采用招标方式"]},{"i":422,"c":16,"t":1,"s":"由3个及以上供应商参与、经过多轮报价竞争确定成交供应商的非招标采购方式是（　）。","a":"A","e":"考点：四种非招标采购方式的辨析。依据：「竞价≥3家多轮报价」，区别于询比的3家以上一次报价和谈判的2家以上。","o":["竞价采购","谈判采购","询比采购","直接采购"]},{"i":423,"c":16,"t":1,"s":"招标人与中标人应当自中标通知书发出之日起（　）内订立书面合同。","a":"D","e":"考点：中标后订立合同的法定时限。依据：「合同＝中标通知书后30日内签」。","o":["10日","15日","20日","30日"]},{"i":579,"c":16,"t":1,"s":"依法必须招标的项目，招标人对已发出的招标文件进行必要澄清或者修改的，应当在投标截止时间至少（　）前，以书面形式通知所有招标文件收受人。","a":"C","e":"考点：招标文件澄清修改的时限。笔记依据：「招标文件澄清/修改：应在投标截止时间至少15日前书面通知所有收受人；不足15日应顺延截止时间」。","o":["5日","10日","15日","20日"]},{"i":580,"c":16,"t":1,"s":"关于投标保证金的上限规定，正确的是（　）。","a":"C","e":"考点：投标保证金的限额。笔记依据：「上限：不得超过招标项目估算价的2%；施工项目最高不超过80万元」。注意区别于履约保证金（不超过中标合同金额的10%）。","o":["不得超过招标项目估算价的5%，施工项目最高不超过100万元","统一按10万元的标准收取","不得超过招标项目估算价的2%，施工项目最高不超过80万元","不得超过中标合同金额的10%"]},{"i":581,"c":16,"t":1,"s":"关于中标后签订合同，正确的做法是（　）。","a":"A","e":"考点：合同签订时限与实质性要求。笔记依据：「合同签订时限：中标通知书发出后30日内订立书面合同」「不得再行订立背离合同实质性内容的其他协议」。","o":["自中标通知书发出之日起30日内订立书面合同","自中标通知书发出之日起60日内再订立书面合同","中标人收到通知书后可先进场施工，合同随后补签","双方口头达成一致即视为合同成立"]},{"i":582,"c":16,"t":1,"s":"依法必须进行招标的项目，评标委员会中技术、经济等方面的专家不得少于成员总数的（　）。","a":"C","e":"考点：评标委员会的专家比例要求。笔记依据：「技术、经济等方面的专家不得少于成员总数的2/3；招标人代表不超过评委会总人数1/3」。","o":["1/3","1/2","2/3","3/4"]},{"i":722,"c":16,"t":1,"s":"按照《工程建设项目施工招标投标办法》，下列各项中不属于施工招标应当具备的条件的是（　）。","a":"D","e":"考点：施工招标应当具备的条件。课件列举的条件为“招标人已经依法成立；初步设计及概算应当履行审批手续的，已经批准；有相应资金或资金来源已经落实；有招标所需的设计图纸及技术资料”，事先内定施工单位显然不是法定条件。","o":["招标人已经依法成立","初步设计及概算应当履行审批手续的，已经批准","有相应资金或资金来源已经落实","已内定施工单位并完成进场准备"]},{"i":723,"c":16,"t":1,"s":"招标人以招标公告的方式邀请不特定的法人或者其他组织投标，这种招标方式是（　）。","a":"A","e":"考点：两种法定招标方式的定义辨析。课件原文：“公开招标，是指招标人以招标公告的方式邀请不特定的法人或者其他组织投标。邀请招标，是指招标人以投标邀请书的方式邀请特定的法人或者其他组织投标。”竞争性谈判、询比采购属于非招标采购方式。","o":["公开招标","邀请招标","竞争性谈判","询比采购"]},{"i":725,"c":16,"t":1,"s":"根据规定，招标人应当按照公告载明的时间、地点发售资格预审文件或者招标文件，其发售期不得少于（　）。","a":"B","e":"考点：资格预审文件和招标文件的发售要求。课件原文：“资格预审文件或者招标文件的发售期不得少于5日”，发售收费应限于补偿印刷、邮寄的成本支出，不得以营利为目的。","o":["3日","5日","10日","20日"]},{"i":730,"c":16,"t":1,"s":"关于南方电网公司系统范围内工程建设项目必须招标的规模标准，下列说法正确的是（　）。","a":"A","e":"考点：公司系统必须招标的规模标准体系。课件规定货物采购门槛为200万元（含）、施工为400万元（含）、勘察设计监理等服务为100万元（含），可合并计算的合计达到标准也必须招标；非工程建设项目货物和服务单项合同估算价100万元（含）以上原则上即应采用招标方式。","o":["重要设备、材料等货物采购单项合同估算价200万元（含）以上，必须招标","施工单项合同估算价300万元（含）以上，必须招标","勘察、设计、监理等服务采购单项合同估算价200万元（含）以上，必须招标","非工程建设项目货物和服务单项合同估算价500万元（含）以上才原则上采用招标方式"]},{"i":732,"c":16,"t":1,"s":"公司系统范围内的采购模式分为三大类，分别是专项采购、批次采购和（　）。","a":"C","e":"考点：公司采购模式的三大类划分。课件原文：“公司系统范围内的采购模式专项采购、批次采购、框架采购等三大类”；零星采购、电子商城采购属于其他采购渠道，拍卖不属于公司采购模式分类。","o":["零星采购","电子商城采购","框架采购","拍卖采购"]},{"i":379,"c":16,"t":2,"s":"根据《招标投标法实施条例》，下列情形中视为投标人相互串通投标的有（　）。","a":"BCD","e":"考查“属于串通”与“视为串通”的区分。课件将“协商投标报价等投标文件的实质性内容”列为属于串通的情形，而投标文件由同一单位或个人编制、异常一致或报价呈规律性差异、保证金从同一账户转出等均为法定“视为串通”的情形。","o":["投标人之间协商投标报价等投标文件的实质性内容","不同投标人的投标文件由同一单位或者个人编制","不同投标人的投标文件异常一致或者投标报价呈规律性差异","不同投标人的投标保证金从同一单位或者个人的账户转出"]},{"i":380,"c":16,"t":2,"s":"根据《招标投标法实施条例》，评标过程中应当否决投标的情形有（　）。","a":"ABC","e":"考查否决投标的法定情形。课件依据：「（一）投标文件未经投标单位盖章和单位负责人签字；（二）投标联合体没有提交共同投标协议……（五）投标报价低于成本或者高于招标文件设定的最高投标限价」。对实质性要求作出响应是投标合格的必要条件，不应据此否决。","o":["投标文件未经投标单位盖章和单位负责人签字","投标联合体没有提交共同投标协议","投标报价高于招标文件设定的最高投标限价","投标文件对招标文件提出的实质性要求和条件作出响应"]},{"i":381,"c":16,"t":2,"s":"根据南方电网公司采购管理制度，下列属于非招标采购方式的有（　）。","a":"ABCD","e":"考查公司采购方式的分类。课件依据：「非招标：谈判采购、询比采购、竞价采购、直接采购等方式，除直接采购外均包括公开和邀请两种方式。」零星采购是与招标、非招标、电子商城采购并列的单列采购形式，不属于非招标采购方式。","o":["谈判采购","询比采购","竞价采购","直接采购","零星采购"]},{"i":382,"c":16,"t":2,"s":"关于联合体投标，下列说法正确的有（　）。","a":"BD","e":"考查联合体投标的法定规则。课件依据：「由同一专业的单位组成的联合体，按照资质等级较低的单位确定资质等级」「招标人不得强制投标人组成联合体共同投标」。A、C两项表述正好相反。","o":["招标人可以根据项目需要强制投标人组成联合体共同投标","联合体各方均应当具备承担招标项目的相应能力以及国家有关规定或者招标文件规定的相应资格条件","由同一专业的单位组成的联合体，按照资质等级较高的单位确定其资质等级","联合体中标的，联合体各方应当共同与招标人签订合同，就中标项目向招标人承担连带责任"]},{"i":383,"c":16,"t":2,"s":"根据南方电网公司评标委员会组建要求，下列说法正确的有（　）。","a":"AC","e":"考查公司层面评标委员会组建的人数与专家要求。课件依据：「招标项目总人数为5人以上单数，非招标项目总人数为3人以上单数……招标人代表不超过评委会总人数三分之一」「对于不同电压等级整合为同一个采购项目的，应确保有对应专业最高电压等级的专家出席评审」。","o":["招标项目评标委员会总人数为5人以上单数","非招标项目评标委员会总人数为2人以上偶数即可","招标人代表不超过评委会总人数的三分之一","对于不同电压等级整合为同一个采购项目的，应确保有对应专业最低电压等级的专家出席评审"]},{"i":384,"c":16,"t":2,"s":"关于南方电网公司对投标人资格条件设置和业绩审核的要求，下列说法正确的有（　）。","a":"ACD","e":"考查资格条件设置的合规要求。课件依据：「投标人资格条件原则上不设置经营范围或注册资本要求」「不得出现‘电力行业’‘供电企业’‘南方五省区范围内’等特定约束条件」「业绩要求的时段一般不少于投标截止时间前三年」。","o":["招标人应结合品类特点明确承包资质、生产许可证等专用资格条件，不得以不合理的条件限制、排斥潜在投标人或者投标人","投标人资格条件原则上应设置明确的经营范围和注册资本门槛，以便筛选优质供应商","业绩应以同类型、同专业为标准，不得出现“电力行业”“供电企业”“南方五省区范围内”等特定约束条件","业绩要求的时段一般不少于投标截止时间前三年"]},{"i":436,"c":16,"t":2,"s":"依据招标投标有关规定，投标文件存在下列情形之一的，招标人应当拒收（　）。","a":"ABD","e":"考点：投标文件的拒收情形。依据：「逾期、未密封、未通过资格预审的投标文件应拒收」；报价偏低属于评审阶段评定的问题，不能作为拒收理由。","o":["未按要求密封的","逾期送达的","报价明显偏低的","未通过资格预审的申请人提交的"]},{"i":729,"c":16,"t":2,"s":"根据南方电网公司制度，开展招标应当具备的条件包括（　）。","a":"ABC","e":"考点：公司层面招标采购的条件。课件列举：“（一）项目须履行审批手续的，已经审批；（二）有相应的资金或资金来源已经落实；（三）能够提出招标所需的技术、商务要求；（四）法律法规规定的其他条件已经具备。”","o":["项目须履行审批手续的，已经审批","有相应的资金或资金来源已经落实","能够提出招标所需的技术、商务要求","相关法律法规规定的其他条件尚不具备也可先行启动招标"]},{"i":385,"c":16,"t":3,"s":"投标截止后投标人撤销投标文件的，招标人应当退还其投标保证金。","a":"错","e":"考查撤销投标文件对保证金的处理。课件依据：「投标截止后投标人撤销投标文件的，招标人可以不退还投标保证金。」注意与投标截止前书面撤回投标文件相区别，撤回的情形招标人应当自收到书面撤回通知之日起5日内退还保证金。"},{"i":386,"c":16,"t":3,"s":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行，开标由招标人主持，并邀请所有投标人参加。","a":"对","e":"考查开标的时间与组织要求。课件依据：「在招标文件确定的提交投标文件截止时间的同一时间公开进行」「开标由招标人主持，邀请所有投标人参加」，开标地点应当为招标文件中预先确定的地点。"},{"i":626,"c":16,"t":3,"s":"对于技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择的项目，按规定必须一律采用公开招标。","a":"错","e":"考点：可以不招标的情形。笔记依据：「技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择，可不招标」。"},{"i":724,"c":16,"t":3,"s":"采用公开招标方式的费用占项目合同金额的比例过大，属于依法必须招标项目可以采用邀请招标的情形之一。","a":"对","e":"考点：可以采用邀请招标的情形。课件所列实施条例情形为：“（一）技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择；（二）采用公开招标方式的费用占项目合同金额的比例过大。”"},{"i":726,"c":16,"t":3,"s":"招标人不得向他人透露已获取招标文件的潜在投标人的名称、数量等情况；设有标底的，标底必须保密。","a":"对","e":"考点：招标环节的保密要求。课件原文：“招标人不得向他人透露已获取招标文件的潜在投标人的名称、数量以及可能影响公平竞争的有关招标投标的其他情况。设有标底的，标底必须保密。”"},{"i":727,"c":16,"t":3,"s":"依法必须进行招标的项目，提交资格预审申请文件的时间，自资格预审文件停止发售之日起不得少于5日。","a":"对","e":"考点：资格预审申请文件提交时间的要求。课件原文：“依法必须进行招标的项目提交资格预审申请文件的时间，自资格预审文件停止发售之日起不得少于5日。”"},{"i":728,"c":16,"t":3,"s":"依法必须招标项目的境内投标单位，以现金或者支票形式提交的投标保证金，应当从其基本账户转出。","a":"对","e":"考点：投标保证金的提交要求。课件原文：“依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出”，并明确招标人不得挪用投标保证金。"},{"i":731,"c":16,"t":3,"s":"按照公司采购管理制度，非招标采购方式中，除直接采购外均包括公开和邀请两种方式。","a":"对","e":"考点：公司采购方式体系的细节。课件原文：“非招标：谈判采购、询比采购、竞价采购、直接采购等方式，除直接采购外均包括公开和邀请两种方式。”"},{"i":733,"c":16,"t":3,"s":"批次采购适用于采购项目范围特定、技术复杂、要求特殊的品类。","a":"错","e":"考点：三种采购模式适用场景的区分。课件载明“批次采购适用于需求明确、计划性强、交货周期较长的品类”，范围特定、技术复杂、要求特殊的品类应适用专项采购，两者特征不可混淆。"},{"i":387,"c":17,"t":1,"s":"在公司舆情工作的责任架构中，履行舆情工作第一责任人责任、统筹指导舆情各项工作并牵头组织应对重大舆情风险的是？","a":"C","e":"本题考查舆情工作三级领导责任分工。课件依据：「党委书记履行舆情工作第一责任人责任，统筹指导舆情各项工作，牵头组织应对重大舆情风险」；党委副书记为直接责任人，业务分管领导履行分管领域领导责任。","o":["党委副书记","业务分管领导","党委书记","党建部门负责人"]},{"i":388,"c":17,"t":1,"s":"某员工看到网上出现针对本单位的一条普通吐槽和个别负面评论，就将其当作重大舆情逐级上报、如临大敌。这种“不是舆情当舆情”的误区，属于下列哪种不科学认知？","a":"B","e":"本题考查舆情风险的四种不科学认知。“哈哈镜里看舆情”指把吐槽、简单爆料、个别负面评论当舆情，实质上是“不是舆情当舆情”的误区。","o":["放大镜里看舆情","哈哈镜里看舆情","望远镜里看舆情","显微镜里看舆情"]},{"i":389,"c":17,"t":1,"s":"按照“管业务必须管业务领域舆情”的要求，各业务部门在本业务领域舆情工作中承担的责任是？","a":"D","e":"本题考查业务部门在舆情责任架构中的定位。课件依据：「各业务部门负『管业务必须管业务领域舆情』的主体责任」。","o":["第一责任人责任","直接责任人责任","领导责任","主体责任"]},{"i":510,"c":17,"t":1,"s":"在公司舆情工作的责任架构中，党委副书记承担的职责是（　）","a":"C","e":"第一责任人责任和每年组织专题研究是党委书记的职责；组织做好分管领域内重大舆情应急处置是业务分管领导的职责；党委副书记履行直接责任人责任，协助党委书记组织开展舆情防控。","o":["履行舆情工作第一责任人责任","组织做好分管领域内重大舆情的应急处置","履行直接责任人责任，协助党委书记组织开展舆情防控","每年组织专题研究舆情工作"]},{"i":512,"c":17,"t":1,"s":"下列案例中，属于“AI时代舆情挑战”典型表现的是（　）","a":"D","e":"虚构台风“威尔逊”的AI视频是AI生成虚假信息引发舆情的典型案例；其余三项均由当事人真实言行引发，属于常规舆情情形。","o":["国企领导“牵手门”事件","“最快女护士”张水华的调休言论争议","中信建投实习生拍摄炫富短视频泄密","网传虚构台风“威尔逊”的AI视频"]},{"i":513,"c":17,"t":1,"s":"下列表述中，不符合当前国资央企面临的舆论环境特点的是（　）","a":"B","e":"课件明确当前社会舆论容忍度低，央企舆情呈易发多发、烈度大的特点，B项与之相反；A、C、D均为课件所述环境特点。","o":["身处舆论场中央，受关注度高","社会舆论容忍度较高，舆情不易发酵","员工个人言行容易被公众关联到所属企业","现实中的强势地位并不等于网络舆论场的优势"]},{"i":514,"c":17,"t":1,"s":"据气象部门辟谣内容，我国对于台风风力的级别最大为（　）级及以上","a":"D","e":"气象部门辟谣明确：目前我国对于台风风力的级别最大为17级及以上，此类夸张风力的谣言视频是AI时代舆情的典型样本。","o":["12","14","16","17"]},{"i":550,"c":17,"t":1,"s":"按照补充复习资料的界定，“在一定社会情境和传播环境中，公众围绕特定事件、议题或组织所形成的意见表达、情绪态度及其传播状态的综合体现”，指的是（　）。","a":"B","e":"考点：舆情的概念定义。笔记依据：「舆情：在一定社会情境和传播环境中，公众围绕特定事件、议题或组织所形成的意见表达、情绪态度及其传播状态的综合体现」。","o":["舆论","舆情","公共关系","网络热搜"]},{"i":551,"c":17,"t":1,"s":"舆情事后修复中的“固化经验”环节要求做好“三库”更新，这“三库”是指（　）。","a":"D","e":"考点：舆情事后修复之固化经验的“三库”。笔记依据：「固化经验：制度更新、『三库』更新（风险库、口径库、案例库）、经验共享」。","o":["人才库、技术库、资金库","预案库、队伍库、装备库","舆情库、媒体库、客户库","风险库、口径库、案例库"]},{"i":390,"c":17,"t":2,"s":"结合历史数据分析，公司舆情风险呈高发态势的节点包括？","a":"ABDE","e":"本题考查公司舆情风险高发的六大节点：重要政治与社会活动期间、公司关键业务开展期、用电负荷集中增长期、自然灾害期间、岁末年初关键时段、节假日期间。员工集中培训期间不在其中。","o":["重要政治与社会活动期间","公司关键业务开展期","组织员工集中培训期间","用电负荷集中增长期","自然灾害期间"]},{"i":391,"c":17,"t":2,"s":"舆情事件处置结束后进行复盘总结，需要复盘的三大环节是？","a":"ABC","e":"本题考查事后修复中复盘总结的三大环节。课件依据：「复盘三大环节：风险研判、信息核查、舆情处置」。","o":["风险研判","信息核查","舆情处置","责任追究"]},{"i":392,"c":17,"t":2,"s":"舆情处置结束后进入声誉修复环节，应采取的措施包括？","a":"ACDE","e":"本题考查声誉修复的四步举措：精准回应关切、强化正面宣传、聚焦民生诉求、做好风险跟踪，持续监测防止舆情反弹。回避质疑、被动等待均不符合要求。","o":["精准回应关切","回避核心质疑","强化正面宣传","聚焦民生诉求","做好风险跟踪"]},{"i":429,"c":17,"t":2,"s":"关于公司舆情工作的领导责任分工，下列对应关系正确的有（　）。","a":"ABC","e":"考点：舆情工作三级领导责任。依据：「党委书记＝第一责任人；党委副书记＝直接责任人；业务分管领导＝职责范围内领导责任」；舆情责任全员相关，D项错误。","o":["党委书记——第一责任人","党委副书记——直接责任人","业务分管领导——职责范围内领导责任","普通员工——无需承担任何舆情责任"]},{"i":430,"c":17,"t":2,"s":"做好舆情工作要用好舆情“三库”，指的是（　）。","a":"ACD","e":"考点：舆情“三库”的构成。依据：「舆情『三库』＝风险库、口径库、案例库」。","o":["风险库","照片库","口径库","案例库"]},{"i":431,"c":17,"t":2,"s":"课件从四个层面分析当前的舆论环境，这四个层面包括（　）。","a":"ACDE","e":"考点：舆论环境的四层面划分。依据：「舆论环境四层面＝国际、国内、媒体发展、国资国企」。","o":["国际层面","家庭社区层面","国内层面","媒体发展层面","国资国企层面"]},{"i":584,"c":17,"t":2,"s":"结合舆情风险信息来源分布，下列属于“线下渠道”来源的有（　）。","a":"ACD","e":"考点：舆情风险信息来源的线上线下划分。笔记依据：「线上平台：头部社交平台、综合资讯与内容聚合平台、线上投诉平台；线下渠道：政务与公共监督、法律与合规领域信息、企业内部管理与社会接触面、媒体选题动向」。","o":["政务与公共监督","头部社交平台","法律与合规领域信息","媒体选题动向","线上投诉平台"]},{"i":585,"c":17,"t":2,"s":"按照课程归纳，当前的“四大舆论环境”包括下列各项中的（　）。","a":"ACDE","e":"考点：四大舆论环境的构成。笔记依据：「四大舆论环境：国际环境、国内环境、媒体发展、国资央企」。","o":["国际环境","全球碳关税谈判进程","国内环境","国资央企","媒体发展"]},{"i":393,"c":17,"t":3,"s":"个人问题类舆情曝光后，公众往往会将该员工的个人行为与企业管理水平关联起来，负面标签容易附着在企业身上，影响公众对企业的认知。","a":"对","e":"本题考查个人问题类舆情的共性特征之一——与企业形象深度绑定。课件依据：「公众常常将国企员工的个人行为与企业管理水平关联起来，负面标签容易附着在企业身上」。"},{"i":394,"c":17,"t":3,"s":"有观点认为，大型企业在现实世界中处于强者地位，因而在网络舆论场上也必然处于强势地位。这一说法符合课件的观点。","a":"错","e":"本题考查网络舆论场与现实世界强弱关系的辨析。课件依据：「现实世界的强者是网络舆论场的弱者」，故该说法错误。"},{"i":440,"c":17,"t":3,"s":"“后真相时代”是指观点先于事实、情感大于理性地左右公众认知的传播环境。","a":"对","e":"考点：后真相时代的内涵。依据：「后真相时代＝观点先于事实，情感＞理性」，这一特征加大了舆情引导的难度。"},{"i":441,"c":17,"t":3,"s":"舆情是公众的意见表达、情绪态度及传播状态的综合体现。","a":"对","e":"考点：舆情的基本内涵。依据：「舆情＝公众意见表达＋情绪态度＋传播状态」。"},{"i":442,"c":17,"t":3,"s":"公司开展重大工作、作出重大决策前，应当进行舆情风险评估并落实前置防控措施。","a":"对","e":"考点：重大事项的舆情风险管理要求。依据：「重大工作、重大决策要做舆情风险评估和前置防控」。"},{"i":443,"c":17,"t":3,"s":"舆情处置工作做得好的经验亮点，主要体现在速度到位、节奏合理、态度诚恳三个方面。","a":"对","e":"考点：舆情处置的亮点。依据：「处置亮点＝速度到位、节奏合理、态度诚恳」。"},{"i":444,"c":17,"t":3,"s":"进入AI时代，舆论信息呈现出海量增长、真假难辨、舆论反转频发等特点。","a":"对","e":"考点：AI时代舆情环境的新特点。依据：「AI时代特点＝信息海量、真假难辨、舆论反转」。"},{"i":511,"c":17,"t":3,"s":"根据课件，公司舆情风险的信息来源既包括线上平台，也包括线下渠道。","a":"对","e":"课件将舆情风险信息来源概括为线上线下多个平台和渠道，防控时不可只盯线上而忽视线下渠道。"},{"i":515,"c":17,"t":3,"s":"舆情是指各类媒体上出现的关于公司的全部信息，凡提到公司即构成舆情。","a":"错","e":"舆情特指可能或已经对公司工作和形象产生负面影响的信息，并非关于公司的全部信息。"},{"i":516,"c":17,"t":3,"s":"在中信建投实习生事件中，处置策略是一次性完整回应所有问题，迅速形成闭环。","a":"错","e":"该事件的处置策略是“两段式”分层回应：首轮快速定性止损，第二轮完整公布问责情况并澄清网络谣言。"},{"i":517,"c":17,"t":3,"s":"在舆情认知误区中，“望远镜”误区是指过度关注本企业的微小负面信息、自我加压放大。","a":"错","e":"把本企业小舆情放大的自我加压属于“放大镜”误区；“望远镜”误区是指盯着行业和别人，总担心波及自身。"},{"i":518,"c":17,"t":3,"s":"个人问题类舆情往往通过微信私聊、群聊、朋友圈等渠道裂变传播，扩散速度快，需要高度警惕。","a":"对","e":"课件提示个人问题类舆情常借助私聊、群聊、朋友圈等社交链路裂变传播，扩散快、控制难，须高度警惕。"},{"i":605,"c":17,"t":3,"s":"舆情从出现到平息，其传播过程一般要经历潜伏期、发展期、高潮期和消退期四个阶段。","a":"对","e":"考点：舆情传播的四个阶段。笔记依据：「舆情的传播四个阶段：潜伏期、发展期、高潮期、消退期」。"},{"i":606,"c":17,"t":3,"s":"AI“后真相时代”的舆论特征表现为观点先于事实、情感大于理性。","a":"对","e":"考点：“后真相时代”的舆论特征。笔记依据：「AI『后真相时代』舆论特征：观点先于事实，情感大于理性」。"},{"i":607,"c":17,"t":3,"s":"作为国资央企员工，既是自然人，更是企业人，在网上发言、发帖时要树立谨慎言行的“被围观意识”。","a":"对","e":"考点：国资央企舆论环境与员工的“被围观意识”。笔记依据：「舆论场中央受关注度高；社会舆论容忍度低；是自然人，更是企业人，要有谨慎言行的『被围观意识』」。"},{"i":395,"c":18,"t":1,"s":"不同国家或地区对物流研究的侧重有所不同，下列对应关系正确的是？","a":"A","e":"本题考查各国或地区物流研究的侧重方向。课件依据：「美国：企业物流；日本：物流系统；欧盟：综合物流」。","o":["欧盟——综合物流","美国——物流系统","日本——企业物流","欧盟——企业物流"]},{"i":396,"c":18,"t":1,"s":"在现代物流体系架构中，下列要素与其定位对应正确的是？","a":"C","e":"本题考查现代物流体系架构的五组定位：基础设施——仓储网络、物质基础——物资储备、核心引擎——供需调配、关键驱动——运力配送、新发力点——逆向物资管理。","o":["基础设施——物资储备","物质基础——仓储网络","核心引擎——供需调配","关键驱动——逆向物资管理"]},{"i":411,"c":18,"t":1,"s":"关于公司供应链管理理念的转变方向，正确的表述是（　）。","a":"B","e":"考点：供应链的转变方向。依据：「供应链由成本效率和安全稳定并重，向安全稳定优先、兼顾成本、效率转变」，同时强调自主可控、风险评估、有序转移。","o":["由安全稳定优先向成本效率优先转变","由成本效率和安全稳定并重，向安全稳定优先、兼顾成本效率转变","由多元目标管理向单纯追求低成本转变","始终以成本效率为最高优先目标"]},{"i":412,"c":18,"t":1,"s":"供应链班组评价体系设置了多个星级等级，其中最高等级是（　）。","a":"A","e":"考点：供应链班组评价体系的等级构成。依据：「供应链班组评价体系，五星示范、五星、四星、三星、二星、一星」，五星示范居首。","o":["五星示范","五星","四星","三星"]},{"i":583,"c":18,"t":1,"s":"按照公司供应链班组评价体系，评价的最高等级是（　）。","a":"A","e":"考点：供应链班组评价体系的等级构成。笔记依据：「供应链班组评价体系：五星示范、五星、四星、三星、二星、一星」。","o":["五星示范","五星","四星","三星"]},{"i":397,"c":18,"t":2,"s":"根据物流的定义，下列属于物流基本功能的有？","a":"BDE","e":"本题考查物流定义所列举的基本功能。课件依据：「将运输、存储、装卸、搬运、包装、流通加工、配送、信息处理等基本功能有机结合，使物品从供应地向接收地进行实体流动的过程」。","o":["生产制造","包装","质量检验","信息处理","配送"]},{"i":398,"c":18,"t":2,"s":"现代物流的主要特征包括？","a":"BCDE","e":"本题考查现代物流的主要特征。课件依据：「现代物流的主要特征包括供需适配、安全高效、内外联通、绿色智慧」。","o":["规模领先","安全高效","绿色智慧","内外联通","供需适配"]},{"i":399,"c":18,"t":2,"s":"《“十四五”现代物流发展规划》明确，现代物流发展发挥着的作用包括？","a":"BCD","e":"本题考查“十四五”现代物流发展规划对现代物流作用的定位。课件依据：「现代物流发展发挥着先导性、基础性、战略性作用」。","o":["主导性","先导性","战略性","基础性"]},{"i":427,"c":18,"t":2,"s":"关于供应链改革的方向，下列属于其中内容的有（　）。","a":"ABCD","e":"考点：供应链改革方向。依据：「供应链改革方向：层级扁平、调度集中、资源共享、内外协同」，并推动仓储区域化、物流市场化。","o":["层级扁平","调度集中","资源共享","内外协同","层级叠加加密"]},{"i":428,"c":18,"t":2,"s":"现代物流体系建设要求重点关注三大计划的相互衔接，它们是（　）。","a":"ACD","e":"考点：供应链三大计划的衔接。依据：「现代物流要关注需求计划、供应计划、库存计划衔接」。","o":["需求计划","融资计划","供应计划","库存计划"]},{"i":603,"c":18,"t":2,"s":"供应链向“安全稳定优先、兼顾成本效率”转变的三方着力点的关键词是（　）。","a":"ABC","e":"考点：供应链转型提级的三个关键词。笔记依据：「增强供应链安全韧性，提升应急物流保障水平，3个关键词：自主可控，风险评估，有序转移」。","o":["自主可控","风险评估","有序转移","降本增效优先"]},{"i":604,"c":18,"t":2,"s":"按照公司的物资分类，下列属于其中的有（　）。","a":"ABCD","e":"考点：物资分类的四个类别。笔记依据：「物资分类：储备物资、项目物资、闲置物资、报废物资」。","o":["储备物资","项目物资","闲置物资","报废物资","临时借用物资"]},{"i":400,"c":18,"t":3,"s":"按照现代物流体系建设要求，应加强设备退役、再利用、处置等全过程管理，推动闲置物资、报废物资处置线上化，提升处置的效率、效益及规范水平。","a":"对","e":"本题考查设备退役与闲置、报废物资处置的要求。课件依据：「推动闲置物资、报废物资处置线上化，提升闲置物资再利用及报废物资处置效率、效益及规范水平」。"},{"i":439,"c":18,"t":3,"s":"推行库存精益管理、优化不同供应模式下的库存控制策略，能够从源头降低公司库存水平，助力“两金”压降。","a":"对","e":"考点：库存精益管理与“两金”压降的关系。依据：「推行库存精益管理……源头降低公司库存水平，助力两金『压降』」。"},{"i":627,"c":18,"t":3,"s":"现代物流管理只需抓好仓储作业效率，无需关注需求计划、供应计划与库存计划的衔接。","a":"错","e":"考点：现代物流的计划协同要求。笔记依据：「现代物流要关注：需求计划、供应计划、库存计划衔接。精准计划协同，解决少在仓库堆放或减少在仓库滞留的时长」。"}]};